window.DATA={"qcm":[{"c":"pd","q":"Au regard de l'article 1er du Code de procédure civile, quelles propositions sont exactes ?","o":[["Seules les parties introduisent l'instance, hors les cas où la loi en dispose autrement.",1],["Le juge peut se saisir d'office de tout litige d'ordre public.",0],["Les parties ont la liberté de mettre fin à l'instance avant qu'elle ne s'éteigne par l'effet du jugement ou en vertu de la loi.",1],["L'instance est introduite par le greffe dès l'enrôlement.",0],["Le ministère public dispose d'un monopole d'introduction de l'instance en matière contentieuse.",0]],"e":"L'article 1er consacre le principe dispositif dans sa double dimension : initiative de l'instance et maîtrise de son extinction par les parties. La saisine d'office demeure exceptionnelle et suppose un texte.","r":["CPC, art. 1"],"id":"5cea6bef"},{"c":"pd","q":"L'objet du litige, au sens de l'article 4 du Code de procédure civile :","o":[["est déterminé par les prétentions respectives des parties.",1],["est fixé par l'acte introductif d'instance et par les conclusions en défense.",1],["est déterminé par les moyens que le juge relève d'office.",0],["ne peut jamais être modifié en cours d'instance.",0],["peut être modifié par des demandes incidentes se rattachant aux prétentions originaires par un lien suffisant.",1]],"e":"L'article 4 fixe l'objet du litige par les prétentions des parties, telles qu'exprimées dans l'acte introductif et les conclusions en défense, et admet sa modification par des demandes incidentes présentant un lien suffisant (voir aussi l'article 70).","r":["CPC, art. 4","CPC, art. 70"],"id":"79a160a7"},{"c":"pd","q":"Un demandeur réclame 10 000 euros ; le tribunal lui en alloue 15 000. Quelles propositions sont exactes ?","o":[["Le juge a statué ultra petita, en méconnaissance de l'article 5.",1],["Le juge a commis une omission de statuer.",0],["La partie peut saisir la juridiction qui a statué sur le fondement de l'article 464, qui renvoie au régime de l'article 463.",1],["Le jugement est inexistant et peut être ignoré.",0],["Seule la tierce opposition permet de corriger ce vice.",0]],"e":"L'article 5 impose au juge de se prononcer sur tout ce qui est demandé et seulement sur ce qui est demandé. L'article 464 étend la procédure de l'article 463 (omission de statuer) au cas où il a été accordé plus qu'il n'a été demandé.","r":["CPC, art. 5","CPC, art. 463 et 464"],"id":"3de75040"},{"c":"pd","q":"Sur l'office du juge quant au droit applicable, quelles propositions sont exactes ?","o":[["Le juge doit donner ou restituer leur exacte qualification aux faits et actes litigieux sans s'arrêter à la dénomination proposée par les parties.",1],["Selon l'Assemblée plénière (21 décembre 2007, arrêt dit Dauvin ou Carteret), le juge n'est pas tenu, sauf règles particulières, de changer la dénomination ou le fondement juridique des demandes.",1],["Le juge a l'obligation de relever d'office tout moyen de pur droit, en toutes circonstances.",0],["En vertu d'un accord exprès et pour les droits dont elles ont la libre disposition, les parties peuvent lier le juge par les qualifications et points de droit auxquels elles entendent limiter le débat.",1],["Le juge peut fonder sa décision sur des faits qui ne sont pas dans le débat s'il les connaît personnellement.",0]],"e":"L'article 12 impose la qualification exacte et permet aux parties, par accord exprès sur des droits disponibles, de lier le juge. L'arrêt d'Assemblée plénière du 21 décembre 2007 (n° 06-11.343) précise que la requalification est une faculté et non une obligation, sauf règles particulières. L'article 7 interdit de statuer sur des faits hors débat.","r":["CPC, art. 7 et 12"],"id":"62ad0e1e"},{"c":"pd","q":"Le juge envisage de fonder sa décision sur un moyen de droit qu'il a relevé d'office. Il doit :","o":[["statuer immédiatement, le moyen de droit étant dans le débat par nature.",0],["inviter au préalable les parties à présenter leurs observations.",1],["obtenir l'accord exprès des deux parties.",0],["renvoyer l'affaire devant la formation collégiale.",0],["solliciter l'avis du ministère public.",0]],"e":"Article 16, alinéa 3 : le juge ne peut fonder sa décision sur les moyens de droit qu'il a relevés d'office sans avoir au préalable invité les parties à présenter leurs observations. C'est l'expression du principe de la contradiction à l'égard du juge lui même.","r":["CPC, art. 16"],"id":"d6aed5eb"},{"c":"pd","q":"Comment qualifie t on les faits qui figurent dans le débat mais que les parties n'ont pas spécialement invoqués au soutien de leurs prétentions, et que le juge peut prendre en considération ?","o":[["Les faits notoires.",0],["Les faits pertinents.",0],["Les faits adventices.",1],["Les faits constants.",0],["Les faits juridiques.",0]],"e":"Article 7, alinéa 2 : parmi les éléments du débat, le juge peut prendre en considération même les faits que les parties n'auraient pas spécialement invoqués au soutien de leurs prétentions. La doctrine les nomme faits adventices.","r":["CPC, art. 7"],"id":"18702e20"},{"c":"act","q":"Qu'est ce qu'une action attitrée ?","o":[["Une action que la loi réserve aux seules personnes qu'elle qualifie pour élever ou combattre une prétention.",1],["Une action exercée par un avocat titulaire d'un titre de spécialité.",0],["Une action ouverte à toute personne justifiant d'un intérêt légitime.",0],["Une action exercée par le ministère public en qualité de partie jointe.",0],["Une action dont l'exercice est subordonné à un titre exécutoire.",0]],"e":"L'article 31 ouvre l'action à tous ceux qui ont un intérêt légitime au succès ou au rejet d'une prétention, sous réserve des cas dans lesquels la loi attribue le droit d'agir aux seules personnes qu'elle qualifie : ce sont les actions attitrées (par exemple l'action en divorce, réservée aux époux).","r":["CPC, art. 31"],"id":"54dfa4dc"},{"c":"jug","q":"Sur l'autorité de la chose jugée, quelles propositions sont exactes ?","o":[["Elle suppose que la chose demandée soit la même, fondée sur la même cause, entre les mêmes parties formées par elles et contre elles en la même qualité.",1],["Selon l'arrêt Cesareo (Ass. plén., 7 juillet 2006), il incombe au demandeur de présenter dès l'instance relative à la première demande l'ensemble des moyens de nature à fonder celle ci.",1],["Une nouvelle demande identique, présentée sur un fondement juridique différent, se heurte en principe à l'autorité de la chose jugée.",1],["L'autorité de la chose jugée s'attache aux motifs du jugement.",0],["La chose jugée constitue une exception de procédure.",0]],"e":"L'article 1355 du Code civil pose la triple identité. L'arrêt Cesareo (n° 04-10.672) consacre la concentration des moyens, ce qui interdit de rejuger une même demande sous un autre fondement. L'article 480 du CPC attache l'autorité au dispositif, et l'article 122 range la chose jugée parmi les fins de non recevoir.","r":["C. civ., art. 1355","CPC, art. 122 et 480"],"id":"5cdca524"},{"c":"intro","q":"Lesquelles de ces demandes sont des demandes incidentes au sens de l'article 63 ?","o":[["La demande reconventionnelle.",1],["La demande additionnelle.",1],["L'intervention.",1],["La demande initiale.",0],["L'exception d'incompétence.",0]],"e":"L'article 63 énumère trois demandes incidentes : reconventionnelle, additionnelle et intervention. La demande initiale introduit l'instance (article 53). L'exception d'incompétence n'est pas une demande mais un moyen de défense (article 73). La demande reconventionnelle est celle par laquelle le défendeur originaire prétend obtenir un avantage autre que le simple rejet de la prétention adverse (article 64).","r":["CPC, art. 53, 63 à 66, 73"],"id":"2047af1c"},{"c":"jug","q":"Sur l'exécution provisoire des décisions de première instance, quelles propositions sont exactes ?","o":[["Les décisions de première instance sont, en principe, de droit exécutoires à titre provisoire à moins que la loi ou la décision n'en dispose autrement.",1],["Le juge peut écarter l'exécution provisoire de droit, en tout ou partie, s'il estime qu'elle est incompatible avec la nature de l'affaire.",1],["En cas d'appel, le premier président peut arrêter l'exécution provisoire de droit lorsqu'il existe un moyen sérieux d'annulation ou de réformation et que l'exécution risque d'entraîner des conséquences manifestement excessives.",1],["Les deux conditions d'arrêt de l'exécution provisoire de droit sont alternatives.",0],["L'exécution provisoire n'est jamais de droit ; elle doit toujours être ordonnée.",0]],"e":"Depuis le décret n° 2019-1333 du 11 décembre 2019, l'article 514 pose le principe de l'exécution provisoire de droit. L'article 514-1 permet au juge de l'écarter. L'article 514-3 exige, de manière cumulative, un moyen sérieux et des conséquences manifestement excessives.","r":["CPC, art. 514 à 514-3"],"id":"2ed1bc76"},{"c":"def","q":"Selon l'article 74, les exceptions de procédure :","o":[["doivent être soulevées simultanément.",1],["doivent être soulevées avant toute défense au fond ou fin de non recevoir.",1],["sont soumises à cette exigence même si les règles invoquées sont d'ordre public.",1],["peuvent être proposées en tout état de cause.",0],["ne deviennent pas irrecevables du seul fait d'une demande de communication de pièces.",1]],"e":"L'article 74 impose la présentation simultanée et in limine litis des exceptions, y compris lorsque la règle invoquée est d'ordre public. Son dernier alinéa précise que la demande de communication de pièces ne constitue pas une cause d'irrecevabilité des exceptions. La proposition en tout état de cause caractérise les fins de non recevoir (article 123).","r":["CPC, art. 74 et 123"],"id":"6343a3b2"},{"c":"def","q":"Parmi les moyens suivants, lesquels sont des exceptions de procédure ?","o":[["L'exception d'incompétence.",1],["L'exception de litispendance.",1],["L'exception de nullité d'un acte de procédure.",1],["La prescription.",0],["Le défaut de qualité à agir.",0]],"e":"L'article 73 définit l'exception de procédure comme tout moyen tendant à faire déclarer la procédure irrégulière ou éteinte, ou à en suspendre le cours. Le code en traite les espèces : incompétence, litispendance et connexité, exceptions dilatoires, nullité des actes. La prescription et le défaut de qualité sont des fins de non recevoir (article 122).","r":["CPC, art. 73 à 121","CPC, art. 122"],"id":"3c1059f8"},{"c":"def","q":"Sur la nullité des actes de procédure pour vice de forme, quelles propositions sont exactes ?","o":[["Aucun acte ne peut être déclaré nul pour vice de forme si la nullité n'en est pas expressément prévue par la loi, sauf en cas d'inobservation d'une formalité substantielle ou d'ordre public.",1],["La nullité ne peut être prononcée qu'à charge pour celui qui l'invoque de prouver le grief que lui cause l'irrégularité.",1],["L'exigence d'un grief s'applique même lorsqu'il s'agit d'une formalité substantielle ou d'ordre public.",1],["La nullité pour vice de forme peut être invoquée en tout état de cause.",0],["L'irrégularité d'ordre public dispense de la preuve d'un grief.",0]],"e":"L'article 114 pose la règle « pas de nullité sans texte » tempérée par les formalités substantielles ou d'ordre public, et exige un grief dans tous les cas. L'article 112 prévoit que la nullité est couverte si celui qui l'invoque a, postérieurement à l'acte critiqué, fait valoir des défenses au fond ou opposé une fin de non recevoir sans la soulever.","r":["CPC, art. 112 à 116"],"id":"7231642a"},{"c":"def","q":"Lesquelles de ces irrégularités constituent des irrégularités de fond au sens de l'article 117 ?","o":[["Le défaut de capacité d'ester en justice.",1],["Le défaut de pouvoir d'une personne figurant au procès comme représentant d'une personne morale.",1],["Le défaut de capacité ou de pouvoir d'une personne assurant la représentation d'une partie en justice.",1],["L'omission de la date dans une assignation.",0],["Le défaut d'intérêt à agir.",0]],"e":"L'article 117 énumère les irrégularités de fond. Elles peuvent être proposées en tout état de cause (article 118) et sans justification d'un grief (article 119). La Chambre mixte (7 juillet 2006, n° 03-20.026) a jugé cette liste limitative. L'omission de la date relève du vice de forme ; le défaut d'intérêt est une fin de non recevoir.","r":["CPC, art. 117 à 121"],"id":"c5d23f85"},{"c":"def","q":"Lesquels de ces moyens sont des fins de non recevoir énumérées par l'article 122 ?","o":[["La prescription.",1],["La chose jugée.",1],["L'incompétence territoriale.",0],["Le délai préfix.",1],["La connexité.",0]],"e":"L'article 122 vise, de façon non limitative (« tel »), le défaut de qualité, le défaut d'intérêt, la prescription, le délai préfix et la chose jugée. Ces moyens tendent à faire déclarer l'adversaire irrecevable sans examen au fond, pour défaut de droit d'agir. Incompétence et connexité sont des exceptions de procédure.","r":["CPC, art. 122"],"id":"1d4a0650"},{"c":"def","q":"Sur le régime des fins de non recevoir, quelles propositions sont exactes ?","o":[["Elles peuvent en principe être proposées en tout état de cause.",1],["Elles doivent être accueillies sans que celui qui les invoque ait à justifier d'un grief.",1],["Elles doivent être soulevées in limine litis, à peine d'irrecevabilité.",0],["Devant le tribunal judiciaire, lorsqu'un juge de la mise en état est désigné, il est seul compétent pour statuer sur les fins de non recevoir jusqu'à son dessaisissement.",1],["Elles doivent toutes être relevées d'office par le juge.",0]],"e":"Articles 123 et 124 : proposition en tout état de cause (sous réserve de dommages et intérêts en cas d'abstention dilatoire) et absence de grief. L'article 789 tempère la règle devant le tribunal judiciaire en concentrant les fins de non recevoir devant le juge de la mise en état, qui peut toutefois en renvoyer l'examen à la formation de jugement ; après la clôture, l'article 802 n'admet que celles dont la cause survient ou est révélée postérieurement.","r":["CPC, art. 123 à 125","CPC, art. 789"],"id":"8c24b901"},{"c":"def","q":"Quelles fins de non recevoir le juge a t il l'OBLIGATION de relever d'office ?","o":[["L'inobservation du délai d'appel.",1],["L'absence d'ouverture d'une voie de recours.",1],["Le défaut d'intérêt.",0],["La prescription extinctive de droit commun.",0],["La chose jugée.",0]],"e":"Article 125, alinéa 1 : le juge doit relever d'office les fins de non recevoir d'ordre public, notamment l'inobservation des délais de recours ou l'absence d'ouverture d'une voie de recours. L'alinéa 2 ouvre une simple faculté pour le défaut d'intérêt, le défaut de qualité et la chose jugée. L'article 2247 du Code civil interdit au juge de suppléer d'office le moyen tiré de la prescription.","r":["CPC, art. 125","C. civ., art. 2247"],"id":"b929d2cf"},{"c":"inst","q":"Le juge de la mise en état est, jusqu'à son dessaisissement, seul compétent pour :","o":[["statuer sur les exceptions de procédure.",1],["statuer sur les fins de non recevoir.",1],["accorder une provision au créancier lorsque l'existence de l'obligation n'est pas sérieusement contestable.",1],["statuer au fond sur la responsabilité contractuelle du défendeur.",0],["ordonner, même d'office, toute mesure d'instruction.",1]],"e":"L'article 789 attribue ces compétences exclusives au juge de la mise en état. Depuis le décret n° 2024-673 du 3 juillet 2024, il peut renvoyer l'examen d'une fin de non recevoir à la formation de jugement lorsque la complexité du moyen ou l'état d'avancement de l'instruction le justifie. Le décret n° 2025-660 a par ailleurs érigé l'instruction conventionnelle en principe (article 127).","r":["CPC, art. 127 et 789","Décret 2025-660, présentation"],"id":"4c9632a8"},{"c":"comp","q":"En matière délictuelle, le demandeur peut saisir à son choix :","o":[["la juridiction du lieu où demeure le défendeur.",1],["la juridiction du lieu du fait dommageable.",1],["la juridiction dans le ressort de laquelle le dommage a été subi.",1],["la juridiction de son propre domicile, en toute hypothèse.",0],["la juridiction du lieu de conclusion du contrat.",0]],"e":"Article 42 : principe de la juridiction du lieu où demeure le défendeur. Article 46 : option, en matière délictuelle, pour le lieu du fait dommageable ou celui dans le ressort duquel le dommage a été subi.","r":["CPC, art. 42 et 46"],"id":"54bf4754"},{"c":"comp","q":"Une clause dérogeant directement ou indirectement aux règles de compétence territoriale :","o":[["est valable si elle a été convenue entre des personnes ayant toutes contracté en qualité de commerçant.",1],["doit avoir été spécifiée de façon très apparente dans l'engagement de la partie à qui elle est opposée.",1],["est valable entre un professionnel et un consommateur dès lors qu'elle est écrite.",0],["est toujours valable si elle figure dans un contrat écrit.",0],["est réputée non écrite lorsque ces conditions ne sont pas réunies.",1]],"e":"L'article 48 répute non écrite toute clause attributive de compétence territoriale, sauf si elle a été convenue entre commerçants et spécifiée de façon très apparente.","r":["CPC, art. 48"],"id":"72af9865"},{"c":"comp","q":"Le même litige est pendant devant deux juridictions de même degré également compétentes pour en connaître. Que prévoit l'article 100 ?","o":[["La juridiction saisie en premier lieu doit se dessaisir.",0],["La juridiction saisie en second lieu doit se dessaisir au profit de l'autre si l'une des parties le demande, et peut le faire d'office à défaut.",1],["Les deux juridictions statuent et la première décision rendue l'emporte.",0],["La Cour de cassation désigne la juridiction compétente.",0],["Les deux instances sont jointes devant la juridiction de degré supérieur.",0]],"e":"Article 100 : litispendance. À distinguer de la connexité (article 101), qui suppose l'existence entre deux affaires d'un lien tel qu'il est de l'intérêt d'une bonne justice de les faire instruire et juger ensemble. Si les juridictions ne sont pas de même degré, l'exception ne peut être soulevée que devant la juridiction du degré inférieur (article 102).","r":["CPC, art. 100 à 107"],"id":"e0eae6c1"},{"c":"comp","q":"Sur l'incompétence, quelles propositions sont exactes ?","o":[["La partie qui la soulève doit, à peine d'irrecevabilité, la motiver et faire connaître devant quelle juridiction elle demande que l'affaire soit portée.",1],["La décision statuant sur la compétence peut faire l'objet d'un appel dans un délai de quinze jours à compter de sa notification.",1],["Le juge peut, en matière contentieuse, toujours relever d'office son incompétence territoriale.",0],["L'incompétence peut être prononcée d'office en cas de violation d'une règle de compétence d'attribution d'ordre public ou lorsque le défendeur ne comparaît pas.",1],["La voie de recours de droit commun est le contredit.",0]],"e":"Articles 75, 76, 77, 83 et 84. Le contredit a été supprimé par le décret n° 2017-891 du 6 mai 2017 et remplacé par un appel spécifique. En matière contentieuse, le relevé d'office de l'incompétence territoriale est limité aux litiges relatifs à l'état des personnes, aux compétences exclusives et au défaut de comparution du défendeur (article 77).","r":["CPC, art. 75 à 91"],"id":"88a1d71b"},{"c":"intro","q":"Sur la tentative préalable de résolution amiable de l'article 750-1, quelles propositions sont exactes ?","o":[["Elle concerne notamment les demandes tendant au paiement d'une somme n'excédant pas 5 000 euros.",1],["Son défaut est sanctionné par une irrecevabilité que le juge peut prononcer d'office.",1],["Elle s'impose avant une requête en injonction de payer.",0],["Elle peut prendre la forme d'une conciliation par un conciliateur de justice, d'une médiation ou d'une procédure participative.",1],["Elle s'applique à toute demande, quel qu'en soit le montant.",0]],"e":"L'article 750-1, rétabli par le décret n° 2023-357 du 11 mai 2023 après son annulation par le Conseil d'État (22 septembre 2022, n° 436939), s'applique aux instances introduites depuis le 1er octobre 2023. La Cour de cassation a estimé, dans un avis du 25 septembre 2025 (n° 25-70.013), que l'obligation ne s'applique pas à la requête en injonction de payer.","r":["CPC, art. 750-1","CNB, 750-1","Avis du 25 sept. 2025"],"id":"a5486a90"},{"c":"intro","q":"Sur la représentation devant le tribunal judiciaire, quelles propositions sont exactes ?","o":[["Le principe est la représentation obligatoire par avocat.",1],["Les parties en sont dispensées dans les matières relevant de la compétence du juge des contentieux de la protection.",1],["Les parties en sont dispensées, sous réserve d'exceptions, lorsque la demande porte sur un montant inférieur ou égal à 10 000 euros.",1],["Aucune exception n'existe devant le tribunal judiciaire.",0],["La représentation obligatoire s'applique aussi devant le juge des contentieux de la protection.",0]],"e":"Article 760 : principe de la représentation obligatoire. Article 761 : cas de dispense, dont les matières du juge des contentieux de la protection et les demandes n'excédant pas 10 000 euros, sauf exceptions prévues par ce texte (notamment certaines matières relevant de la compétence exclusive du tribunal judiciaire).","r":["CPC, art. 760 et 761"],"id":"65fb8d5e"},{"c":"inst","q":"Sur la péremption d'instance, quelles propositions sont exactes ?","o":[["L'instance est périmée lorsqu'aucune des parties n'accomplit de diligences pendant deux ans.",1],["La péremption éteint l'action.",0],["La péremption n'éteint pas l'action ; elle emporte extinction de l'instance.",1],["Elle peut être constatée d'office par le juge après avoir invité les parties à présenter leurs observations.",1],["Le délai de péremption est de trois ans.",0]],"e":"Articles 386, 388 et 389. La péremption doit, à peine d'irrecevabilité, être demandée ou opposée avant tout autre moyen. Le décret n° 2026-683 du 27 juillet 2026 a modifié les articles 524 et 1009-2 : en cas de radiation pour inexécution devant la cour d'appel ou la Cour de cassation, le délai de péremption court désormais à compter de la décision de radiation, et non plus de sa notification (à compter du 1er octobre 2026).","r":["CPC, art. 386 à 393","Décret 2026-683, présentation"],"id":"331646a7"},{"c":"inst","q":"Sur le désistement d'instance en première instance, quelles propositions sont exactes ?","o":[["Il n'est parfait que par l'acceptation du défendeur, sauf si celui ci n'a présenté aucune défense au fond ni fin de non recevoir au moment du désistement.",1],["Il emporte renonciation à l'action.",0],["Il n'emporte pas, à lui seul, renonciation à l'action.",1],["Le juge déclare le désistement parfait si la non acceptation du défendeur ne se fonde sur aucun motif légitime.",1],["Le désistement est impossible en appel.",0]],"e":"Articles 394 à 399. Le désistement d'instance éteint l'instance mais non l'action. Le désistement d'appel est expressément prévu par les articles 400 et suivants.","r":["CPC, art. 394 à 405"],"id":"dd961627"},{"c":"urg","q":"Sur le fondement de l'article 835, alinéa 1er, le juge des référés peut prescrire les mesures conservatoires ou de remise en état qui s'imposent. Quelles propositions sont exactes ?","o":[["L'urgence est une condition nécessaire.",0],["Il peut le faire même en présence d'une contestation sérieuse.",1],["Il peut le faire pour faire cesser un trouble manifestement illicite.",1],["Il peut le faire pour prévenir un dommage imminent.",1],["Sa décision a l'autorité de la chose jugée au principal.",0]],"e":"L'article 834 exige l'urgence ; l'article 835, alinéa 1er, ne l'exige pas et admet l'intervention malgré une contestation sérieuse. L'alinéa 2 permet d'accorder une provision lorsque l'existence de l'obligation n'est pas sérieusement contestable. L'article 488 refuse à l'ordonnance de référé l'autorité de la chose jugée au principal.","r":["CPC, art. 834, 835 et 488"],"id":"d5bc5977"},{"c":"urg","q":"Sur l'ordonnance de référé, quelles propositions sont exactes ?","o":[["Le délai d'appel est de quinze jours.",1],["Elle n'a pas, au principal, l'autorité de la chose jugée.",1],["Elle ne peut être modifiée ou rapportée en référé qu'en cas de circonstances nouvelles.",1],["Le délai d'appel est d'un mois.",0],["Elle lie le juge du fond.",0]],"e":"Articles 488 à 490. L'ordonnance de référé est une décision provisoire : elle ne lie pas le juge du principal. Le délai d'appel de quinze jours déroge au délai d'un mois de l'article 538.","r":["CPC, art. 484 à 492-1"],"id":"4ccab119"},{"c":"urg","q":"Sur l'ordonnance sur requête, quelles propositions sont exactes ?","o":[["Elle est rendue non contradictoirement.",1],["Elle suppose que le requérant soit fondé à ne pas appeler de partie adverse.",1],["S'il n'est pas fait droit à la requête, appel peut être interjeté, sauf si l'ordonnance émane du premier président.",1],["S'il est fait droit à la requête, tout intéressé peut en référer au juge qui a rendu l'ordonnance.",1],["Elle tranche le principal avec autorité de la chose jugée.",0]],"e":"Article 493 pour la définition, articles 494 à 497 pour le régime. Le référé rétractation devant le juge qui a rendu l'ordonnance rétablit a posteriori la contradiction.","r":["CPC, art. 493 à 498"],"id":"0ac7e816"},{"c":"pre","q":"Sur les mesures d'instruction in futurum de l'article 145, quelles propositions sont exactes ?","o":[["Elles supposent un motif légitime de conserver ou d'établir la preuve de faits dont pourrait dépendre la solution d'un litige.",1],["Elles doivent être sollicitées avant tout procès.",1],["Elles peuvent être ordonnées sur requête ou en référé.",1],["L'urgence est une condition de leur octroi.",0],["Elles peuvent être ordonnées alors qu'une instance au fond portant sur le même litige est déjà en cours.",0]],"e":"Le texte de l'article 145 ne pose pas de condition d'urgence. L'exigence d'une mesure « avant tout procès » exclut le recours à ce texte lorsque le juge du fond est déjà saisi du même litige. Le décret n° 2026-683 du 27 juillet 2026 impose, pour les ordonnances rendues à compter du 1er octobre 2026, l'exécution de l'ordonnance rendue sur requête sur ce fondement dans les trois mois, à peine de caducité relevée d'office (art. 495), et la saisine du juge de la rétractation dans le mois de la signification, à peine d'irrecevabilité (art. 496).","r":["CPC, art. 145","Décret 2026-683, présentation"],"id":"eb52b3a8"},{"c":"pre","q":"Sur la charge et l'administration de la preuve, quelles propositions sont exactes ?","o":[["Il incombe à chaque partie de prouver conformément à la loi les faits nécessaires au succès de sa prétention.",1],["Celui qui réclame l'exécution d'une obligation doit la prouver ; celui qui se prétend libéré doit justifier le paiement ou le fait qui a produit l'extinction de son obligation.",1],["Le juge doit ordonner une mesure d'instruction pour suppléer la carence d'une partie dans l'administration de la preuve.",0],["Une mesure d'instruction ne peut en aucun cas être ordonnée en vue de suppléer la carence de la partie dans l'administration de la preuve.",1],["La charge de la preuve pèse toujours sur le défendeur.",0]],"e":"Article 9 du CPC et article 1353 du Code civil. L'article 146, alinéa 2, interdit d'ordonner une mesure d'instruction pour suppléer la carence d'une partie.","r":["CPC, art. 9 et 146","C. civ., art. 1353"],"id":"b23a83ec"},{"c":"del","q":"Quel est le délai d'appel de droit commun d'un jugement rendu en matière contentieuse ?","o":[["Quinze jours.",0],["Un mois.",1],["Deux mois.",0],["Trois mois.",0],["Un an.",0]],"e":"Article 538 : le délai de recours par une voie ordinaire est d'un mois en matière contentieuse et de quinze jours en matière gracieuse. Il court en principe à compter de la notification du jugement (article 528).","r":["CPC, art. 528 et 538"],"id":"a3c16c7d"},{"c":"del","q":"Devant une juridiction ayant son siège en France métropolitaine, les délais d'appel sont augmentés :","o":[["d'un mois pour les personnes qui demeurent dans les collectivités d'outre mer énumérées par le texte.",1],["de deux mois pour les personnes qui demeurent à l'étranger.",1],["de quinze jours pour les personnes qui demeurent à l'étranger.",0],["d'aucun délai supplémentaire, quel que soit le lieu de résidence.",0],["de trois mois pour les personnes qui demeurent à l'étranger.",0]],"e":"Article 643 : délais de distance. Ils s'appliquent aux délais de comparution, d'appel, d'opposition, de recours en révision, de pourvoi en cassation et, dans un cas, de tierce opposition.","r":["CPC, art. 643 à 647-1"],"id":"21744497"},{"c":"del","q":"Un jugement contentieux de première instance est signifié le jeudi 1er octobre 2026. Quand expire le délai d'appel ?","o":[["Le samedi 31 octobre 2026 à 24 heures.",0],["Le dimanche 1er novembre 2026 à 24 heures.",0],["Le lundi 2 novembre 2026 à 24 heures.",1],["Le mardi 3 novembre 2026 à 24 heures.",0],["Le vendredi 30 octobre 2026 à 24 heures.",0]],"e":"Article 641 : le délai exprimé en mois expire le jour du dernier mois qui porte le même quantième que le jour de l'acte, soit le 1er novembre. Article 642 : le délai qui expirerait un samedi, un dimanche ou un jour férié ou chômé est prorogé jusqu'au premier jour ouvrable suivant. Le 1er novembre 2026 étant un dimanche et un jour férié, le délai expire le lundi 2 novembre 2026 à 24 heures.","r":["CPC, art. 640 à 642"],"id":"d902522c"},{"c":"vro","q":"Sur l'effet dévolutif de l'appel, quelles propositions sont exactes ?","o":[["L'appel défère à la cour la connaissance des chefs de dispositif du jugement qu'il critique expressément et de ceux qui en dépendent.",1],["La dévolution opère pour le tout lorsque l'appel tend à l'annulation du jugement.",1],["Depuis le 1er septembre 2024, l'appelant peut compléter, retrancher ou rectifier dans le dispositif de ses premières conclusions, remises dans les délais, les chefs critiqués mentionnés dans la déclaration d'appel.",1],["La cour d'appel ne statue qu'en droit.",0],["Une déclaration d'appel ne mentionnant aucun chef critiqué opère dévolution pour le tout.",0]],"e":"Articles 561 et 562. L'assouplissement issu du décret n° 2023-1391 du 29 décembre 2023 figure à l'article 915-2. La cour statue à nouveau en fait et en droit (article 561).","r":["CPC, art. 561, 562 et 915-2","Décret 2023-1391, présentation"],"id":"2a7590b1"},{"c":"vro","q":"Dans la procédure d'appel avec représentation obligatoire, quelles propositions sont exactes ?","o":[["En procédure avec mise en état, l'appelant dispose de trois mois à compter de la déclaration d'appel pour remettre ses conclusions, à peine de caducité de la déclaration d'appel relevée d'office.",1],["L'intimé dispose de trois mois à compter de la notification des conclusions de l'appelant, à peine d'irrecevabilité relevée d'office.",1],["En procédure à bref délai, l'appelant dispose de deux mois à compter de la réception de l'avis de fixation pour remettre ses conclusions.",1],["En procédure à bref délai, l'appelant dispose d'un mois.",0],["Le défaut de conclusions de l'intimé dans le délai est sanctionné par la caducité de l'appel.",0]],"e":"Articles 908 et 909 pour la procédure avec mise en état, article 906-2 pour le bref délai. Le décret n° 2023-1391 a porté le délai du bref délai d'un à deux mois pour les appels formés depuis le 1er septembre 2024.","r":["CPC, art. 906-2, 908 et 909","Légifrance, art. 906-2"],"id":"90b7b85e"},{"c":"vro","q":"Sur les prétentions et moyens nouveaux en appel, quelles propositions sont exactes ?","o":[["Les parties peuvent invoquer des moyens nouveaux.",1],["Une prétention qui tend aux mêmes fins que celle soumise au premier juge n'est pas nouvelle, même si son fondement juridique est différent.",1],["Une prétention nouvelle est recevable lorsqu'elle tend à opposer compensation.",1],["Toute prétention nouvelle est recevable dès lors qu'elle présente un lien suffisant avec les prétentions originaires.",0],["L'irrecevabilité des prétentions nouvelles ne peut pas être relevée d'office.",0]],"e":"Article 563 (moyens nouveaux), article 564 (irrecevabilité relevée d'office des prétentions nouvelles, sauf compensation, rejet des prétentions adverses, intervention d'un tiers, survenance ou révélation d'un fait), article 565 (mêmes fins) et article 566 (accessoire, conséquence ou complément nécessaire). Le critère du lien suffisant est celui des demandes incidentes en première instance (article 70).","r":["CPC, art. 563 à 567","CPC, art. 70"],"id":"76a52fc8"},{"c":"vre","q":"Sur le pourvoi en cassation, quelles propositions sont exactes ?","o":[["Le délai de pourvoi est de deux mois, sauf disposition contraire.",1],["Le pourvoi n'est pas suspensif d'exécution, sauf disposition contraire de la loi.",1],["Il n'est ouvert qu'à l'encontre des jugements rendus en dernier ressort.",1],["Le délai de pourvoi est d'un mois.",0],["La Cour de cassation constitue un troisième degré de juridiction qui juge les faits.",0]],"e":"Articles 579, 604, 605 et 612. Le pourvoi tend à faire censurer la non conformité du jugement aux règles de droit (article 604) ; la Cour ne connaît pas des faits.","r":["CPC, art. 579, 604, 605 et 612"],"id":"95049af8"},{"c":"jug","q":"Sur le jugement rendu en l'absence du défendeur, quelles propositions sont exactes ?","o":[["Il est rendu par défaut si la décision est en dernier ressort et si la citation n'a pas été délivrée à personne.",1],["Il est réputé contradictoire lorsque la décision est susceptible d'appel ou lorsque la citation a été délivrée à la personne du défendeur.",1],["Le jugement rendu par défaut est susceptible d'opposition.",1],["Le jugement rendu par défaut, ou réputé contradictoire au seul motif qu'il est susceptible d'appel, est non avenu s'il n'a pas été notifié dans les six mois de sa date.",1],["L'opposition est ouverte contre le jugement réputé contradictoire.",0]],"e":"Articles 473, 476, 478 et 571. L'opposition, voie de rétractation, n'est ouverte qu'au défaillant contre un jugement rendu par défaut. Le décret n° 2026-683 a ajouté un troisième alinéa à l'article 472 : lorsque l'acte a été délivré à personne, le juge peut faire droit à la demande, sauf opposition du demandeur, en contrôlant sa recevabilité et sa conformité à l'ordre public, sans examen de son bien-fondé ; ce régime s'applique aux instances introduites à compter du 1er octobre 2026.","r":["CPC, art. 472 à 479","CPC, art. 571 à 578"],"id":"4449baa8"},{"c":"vre","q":"Sur la tierce opposition, quelles propositions sont exactes ?","o":[["Elle est ouverte à toute personne qui y a intérêt, à condition qu'elle n'ait été ni partie ni représentée au jugement qu'elle attaque.",1],["Elle est ouverte à titre principal pendant trente ans à compter du jugement, sauf disposition contraire.",1],["Elle est ouverte aux parties à l'instance qui ont perdu leur procès.",0],["Elle constitue une voie extraordinaire de recours.",1],["Elle doit être formée dans le délai d'un mois à compter du jugement.",0]],"e":"Articles 580 (voies extraordinaires : tierce opposition, recours en révision, pourvoi en cassation), 582, 583 et 586. Lorsque le jugement a été notifié au tiers, la tierce opposition n'est recevable que dans les deux mois de cette notification, sous réserve des mentions exigées par l'article 586.","r":["CPC, art. 580 à 592"],"id":"058a2d11"},{"c":"pd","q":"Selon l'article 15 du CPC, les parties doivent se faire connaître mutuellement en temps utile :","o":[["les moyens de fait sur lesquels elles fondent leurs prétentions.",1],["les éléments de preuve qu'elles produisent.",1],["les moyens de droit qu'elles invoquent.",1],["la stratégie de plaidoirie qu'elles entendent adopter.",0],["les honoraires convenus avec leur avocat.",0]],"e":"L'article 15 impose cette communication afin que chacune soit à même d'organiser sa défense. Il complète l'article 16, qui impose au juge le respect de la contradiction.","r":["CPC art. 15 et 16"],"id":"12587351"},{"c":"pd","q":"Sur l'apport de la Cour européenne des droits de l'homme au procès civil, quelles propositions sont exactes ?","o":[["L'arrêt Golder (21 février 1975) déduit de l'article 6 § 1 un droit d'accès à un tribunal.",1],["L'arrêt Hornsby (19 mars 1997) juge que l'exécution d'une décision fait partie intégrante du procès.",1],["L'article 6 § 1 garantit le droit à être jugé dans un délai raisonnable.",1],["L'arrêt Hornsby consacre le droit d'accès au juge.",0],["L'article 6 § 1 ne s'applique qu'en matière pénale.",0]],"e":"L'article 6 § 1 s'applique aux contestations sur des droits et obligations de caractère civil. Golder et Hornsby sont les deux arrêts de référence pour l'accès au juge et l'exécution.","r":["CEDH art. 6 § 1"],"id":"133207cb"},{"c":"act","q":"L'intérêt à agir doit être :","o":[["légitime.",1],["né et actuel.",1],["personnel et direct.",1],["exclusivement patrimonial.",0],["reconnu par un titre exécutoire.",0]],"e":"L'article 31 exige un intérêt légitime ; la doctrine et la jurisprudence y ajoutent les caractères né et actuel, personnel et direct. Un intérêt moral peut suffire.","r":["CPC art. 31"],"id":"06893b50"},{"c":"act","q":"Quel est le montant maximal de l'amende civile encourue pour une action en justice dilatoire ou abusive ?","o":[["3 000 euros.",0],["5 000 euros.",0],["10 000 euros.",1],["15 000 euros.",0],["Aucun plafond n'est prévu.",0]],"e":"Article 32-1 : amende civile d'un maximum de 10 000 euros, sans préjudice des dommages et intérêts qui seraient réclamés.","r":["CPC art. 32-1"],"id":"bd6c8ddb"},{"c":"act","q":"Un mineur non émancipé assigne seul son voisin. Comment qualifier l'irrégularité ?","o":[["Fin de non recevoir tirée du défaut de qualité.",0],["Nullité pour vice de forme.",0],["Nullité pour irrégularité de fond tirée du défaut de capacité d'ester en justice.",1],["Défense au fond.",0],["Exception dilatoire.",0]],"e":"Le défaut de capacité d'ester en justice est une irrégularité de fond (art. 117), proposable en tout état de cause et sans grief (art. 118 et 119). Elle peut être couverte si sa cause a disparu au moment où le juge statue (art. 121).","r":["CPC art. 117 à 121"],"id":"740c5a7f"},{"c":"comp","q":"Une action en revendication d'un immeuble situé à Bordeaux est dirigée contre un défendeur domicilié à Lille. Quelle juridiction est territorialement compétente ?","o":[["Celle du domicile du défendeur, à Lille.",0],["Celle du lieu de situation de l'immeuble, à Bordeaux, seule compétente.",1],["Au choix du demandeur, Lille ou Bordeaux.",0],["Celle du domicile du demandeur.",0],["Le tribunal judiciaire de Paris.",0]],"e":"En matière réelle immobilière, la juridiction du lieu où est situé l'immeuble est seule compétente (art. 44).","r":["CPC art. 44"],"id":"670dd35c"},{"c":"comp","q":"Le juge des contentieux de la protection connaît notamment :","o":[["des actions tendant à l'expulsion des personnes qui occupent sans droit ni titre des immeubles bâtis aux fins d'habitation.",1],["des litiges relatifs au crédit à la consommation.",1],["des mesures de traitement des situations de surendettement.",1],["de la tutelle des majeurs.",1],["du divorce.",0]],"e":"Ces compétences résultent des articles L. 213-4-1 et suivants du code de l'organisation judiciaire. Le divorce relève du juge aux affaires familiales.","r":["COJ art. L. 213-4-1 et s."],"id":"b09346ef"},{"c":"comp","q":"En matière contentieuse, le juge peut relever d'office son incompétence territoriale :","o":[["dans les litiges relatifs à l'état des personnes.",1],["lorsque la loi attribue compétence exclusive à une autre juridiction.",1],["lorsque le défendeur ne comparaît pas.",1],["dans tous les cas.",0],["seulement à la demande du ministère public.",0]],"e":"Article 77. En matière gracieuse, le relevé d'office de l'incompétence territoriale est en revanche toujours possible.","r":["CPC art. 77"],"id":"3a6f2d98"},{"c":"intro","q":"Sur l'effet interruptif de la demande en justice, quelles propositions sont exactes ?","o":[["La demande en justice interrompt la prescription même en référé.",1],["L'interruption joue même si la demande est portée devant une juridiction incompétente.",1],["L'interruption joue même si l'acte de saisine est annulé par l'effet d'un vice de procédure.",1],["L'interruption est non avenue si le demandeur se désiste de sa demande.",1],["L'interruption est maintenue en cas de péremption de l'instance.",0]],"e":"Article 2241 du Code civil pour l'interruption, article 2242 pour sa durée, article 2243 pour les cas où elle est non avenue : désistement, péremption, rejet définitif de la demande.","r":["C. civ. art. 2241 à 2243"],"id":"1e0ea0ba"},{"c":"intro","q":"Sur la signification des actes, quelles propositions sont exactes ?","o":[["La signification doit être faite à personne.",1],["La signification à domicile n'est possible que si la signification à personne s'avère impossible.",1],["Le procès verbal de recherches est dressé lorsque le destinataire n'a ni domicile, ni résidence, ni lieu de travail connus.",1],["La signification est la notification d'un acte par le greffe.",0],["La signification à domicile est le mode de principe.",0]],"e":"Articles 651 (définition), 654 (à personne), 655 et 656 (à domicile ou résidence), 659 (procès verbal de recherches).","r":["CPC art. 651 à 659"],"id":"5fb26728"},{"c":"intro","q":"Sur l'intervention, quelles propositions sont exactes ?","o":[["Elle peut être volontaire ou forcée.",1],["L'intervention volontaire est principale lorsqu'elle élève une prétention au profit de celui qui la forme.",1],["L'intervention forcée résulte de la mise en cause d'un tiers par une partie.",1],["Elle est recevable sans qu'il soit besoin d'un lien suffisant avec les prétentions originaires.",0],["Elle n'est jamais possible en appel.",0]],"e":"Articles 66, 70, 329 à 331. En appel, l'intervention volontaire est ouverte aux personnes qui y ont intérêt (art. 554) et l'intervention forcée suppose une évolution du litige (art. 555).","r":["CPC art. 66, 70, 329 à 331, 554 et 555"],"id":"6fa71d3d"},{"c":"intro","q":"Sur l'assignation, quelles propositions sont exactes ?","o":[["C'est l'acte de commissaire de justice par lequel le demandeur cite son adversaire à comparaître devant le juge.",1],["Elle contient à peine de nullité un exposé des moyens en fait et en droit.",1],["Ses mentions sont prescrites à peine de nullité, selon le régime des vices de forme.",1],["Elle est remise directement par le demandeur au défendeur.",0],["Son irrégularité entraîne la nullité sans que le défendeur ait à prouver un grief.",0]],"e":"Articles 54, 55 et 56. La nullité d'une assignation pour omission d'une mention est une nullité de forme soumise à la preuve d'un grief (art. 114). Le décret n° 2026-683 a modifié l'article 56 à compter du 1er octobre 2026.","r":["CPC art. 54 à 56, 114"],"id":"b9c72256"},{"c":"del","q":"Un jugement est signifié le dimanche 31 janvier 2027 ; un délai d'un mois court à compter de cette signification. Quand expire t il ?","o":[["Le dimanche 28 février 2027 à 24 heures.",0],["Le lundi 1er mars 2027 à 24 heures.",1],["Le mercredi 3 mars 2027 à 24 heures.",0],["Le samedi 27 février 2027 à 24 heures.",0],["Le mardi 2 mars 2027 à 24 heures.",0]],"e":"À défaut de quantième identique, le délai expire le dernier jour du mois, soit le 28 février 2027 (art. 641 al. 2). Ce jour étant un dimanche, le délai est prorogé au lundi 1er mars 2027 (art. 642). L'hypothèse d'une signification un dimanche est retenue pour l'exercice de calcul.","r":["CPC art. 641 et 642"],"id":"0b84009e"},{"c":"del","q":"Un acte fait courir un délai de quinze jours le mercredi 3 mars 2027. Quand expire ce délai ?","o":[["Le mercredi 17 mars 2027 à 24 heures.",0],["Le jeudi 18 mars 2027 à 24 heures.",1],["Le vendredi 19 mars 2027 à 24 heures.",0],["Le lundi 22 mars 2027 à 24 heures.",0],["Le mardi 16 mars 2027 à 24 heures.",0]],"e":"Le jour de l'acte ne compte pas (art. 641 al. 1) : le délai court à partir du 4 mars et expire le 18 mars à 24 heures, qui est un jour ouvrable.","r":["CPC art. 641 et 642"],"id":"630f5d22"},{"c":"del","q":"Sur l'article 528-1 du CPC, quelles propositions sont exactes ?","o":[["Il fixe un délai de deux ans à compter du prononcé de la décision.",1],["Il concerne la partie qui a comparu, lorsque le jugement n'a pas été notifié.",1],["Il ne s'applique pas au recours en révision.",1],["Il permet d'agir pendant trente ans contre un jugement non notifié.",0],["Il s'applique à toute partie, même non comparante, sans distinction.",0]],"e":"L'article 528-1 enferme dans un délai de deux ans le recours à titre principal de la partie qui a comparu contre un jugement non notifié tranchant tout le principal ou mettant fin à l'instance. La deuxième chambre civile a jugé qu'il ne s'applique pas au recours en révision (23 mars 2023, n° 21-18.252).","r":["CPC art. 528-1","Cass. 2e civ., 23 mars 2023, n° 21-18.252"],"id":"7955b0c3"},{"c":"def","q":"Une assignation est affectée d'un vice de forme. Peut elle être régularisée ?","o":[["Oui, si aucune forclusion n'est intervenue et si la régularisation ne laisse subsister aucun grief.",1],["Non, la nullité est acquise dès la délivrance de l'acte.",0],["Oui, mais seulement avec l'accord du défendeur.",0],["Oui, mais seulement devant la cour d'appel.",0],["Oui, uniquement par une décision du juge prise d'office.",0]],"e":"Article 115 : la nullité est couverte par la régularisation ultérieure de l'acte si aucune forclusion n'est intervenue et si la régularisation ne laisse subsister aucun grief.","r":["CPC art. 115"],"id":"a14490d1"},{"c":"def","q":"Sur la défense au fond, quelles propositions sont exactes ?","o":[["Elle tend à faire rejeter la prétention adverse comme non justifiée après examen au fond du droit.",1],["Elle peut être proposée en tout état de cause.",1],["L'exception d'inexécution est une défense au fond.",1],["Elle doit être soulevée in limine litis.",0],["Elle tend à faire déclarer la procédure irrégulière.",0]],"e":"Articles 71 et 72. Le nom d'un moyen ne commande pas sa qualification : l'exception d'inexécution ou l'exception de nullité du contrat sont des défenses au fond.","r":["CPC art. 71 et 72"],"id":"0b78a1f1"},{"c":"def","q":"Lesquels de ces moyens constituent des exceptions dilatoires ?","o":[["Le délai pour faire inventaire et délibérer.",1],["Le bénéfice de discussion ou de division.",1],["Le délai pour appeler un garant.",1],["La prescription.",0],["Le défaut de qualité.",0]],"e":"Articles 108 à 111. Les exceptions dilatoires tendent à suspendre le cours de l'instance ; ce sont des exceptions de procédure.","r":["CPC art. 108 à 111"],"id":"82d7d098"},{"c":"def","q":"Le contrat prévoit une conciliation obligatoire et préalable à toute action ; le demandeur saisit directement le juge. Quelles propositions sont exactes ?","o":[["Le défaut de mise en œuvre de la clause constitue une fin de non recevoir.",1],["La fin de non recevoir s'impose au juge si les parties l'invoquent.",1],["Il s'agit d'une exception de procédure, à soulever in limine litis.",0],["Il s'agit d'une défense au fond.",0],["La clause est réputée non écrite.",0]],"e":"Chambre mixte, 14 février 2003, n° 00-19.423. La solution illustre le caractère non limitatif de la liste de l'article 122.","r":["Ch. mixte, 14 févr. 2003, n° 00-19.423","CPC art. 122"],"id":"74e39ce9"},{"c":"inst","q":"Lesquels de ces événements interrompent l'instance ?","o":[["La majorité d'une partie.",1],["La cessation des fonctions de l'avocat lorsque la représentation est obligatoire.",1],["Le décès d'une partie dans les actions transmissibles, à compter de sa notification.",1],["La radiation de l'affaire.",0],["Le sursis à statuer.",0]],"e":"Articles 369 et 370. La radiation (art. 381) et le sursis à statuer (art. 378) sont des causes de suspension, non d'interruption.","r":["CPC art. 369, 370, 378 et 381"],"id":"8f7d1fbc"},{"c":"inst","q":"Sur l'acquiescement, quelles propositions sont exactes ?","o":[["L'acquiescement à la demande emporte reconnaissance du bien fondé des prétentions de l'adversaire et renonciation à l'action.",1],["L'acquiescement au jugement emporte soumission aux chefs de celui ci et renonciation aux voies de recours.",1],["Il peut être exprès ou implicite.",1],["Il est admis pour tous les droits, y compris ceux dont les parties n'ont pas la libre disposition.",0],["Il n'emporte jamais renonciation aux voies de recours.",0]],"e":"Articles 408 à 410. L'acquiescement n'est admis que pour les droits dont la partie a la libre disposition (art. 408 al. 2).","r":["CPC art. 408 à 410"],"id":"2cfdd89f"},{"c":"inst","q":"Sur l'ordonnance de clôture, quelles propositions sont exactes ?","o":[["Après elle, aucune conclusion ne peut être déposée ni aucune pièce produite aux débats, à peine d'irrecevabilité prononcée d'office, sous les exceptions prévues.",1],["Elle ne peut être révoquée que s'il se révèle une cause grave depuis qu'elle a été rendue.",1],["Les conclusions postérieures restent recevables si l'adversaire ne s'y oppose pas.",0],["Elle est prononcée par le greffe.",0],["Elle peut être révoquée librement à la demande d'une partie.",0]],"e":"Articles 802 et 803.","r":["CPC art. 802 et 803"],"id":"b4954a3d"},{"c":"inst","q":"Sur l'instruction conventionnelle issue du décret n° 2025-660, quelles propositions sont exactes ?","o":[["Elle est devenue le principe, la mise en état par le juge constituant l'exception.",1],["Elle peut prendre la forme d'une instruction conventionnelle simplifiée.",1],["Elle ne dessaisit pas le juge, qui demeure compétent pour certains incidents.",1],["Elle interdit tout recours au juge jusqu'au jugement.",0],["Elle a été créée par le décret n° 2019-1333.",0]],"e":"Article 127 et articles 129 et suivants issus du décret n° 2025-660, en vigueur depuis le 1er septembre 2025.","r":["CPC art. 127 et s.","Décret n° 2025-660"],"id":"49e0921f"},{"c":"pre","q":"Sur la preuve obtenue de manière déloyale, depuis l'arrêt d'Assemblée plénière du 22 décembre 2023 :","o":[["elle n'est plus irrecevable par principe.",1],["le juge vérifie si sa production est indispensable à l'exercice du droit à la preuve.",1],["le juge vérifie si l'atteinte aux droits antinomiques est strictement proportionnée au but poursuivi.",1],["elle est toujours irrecevable.",0],["elle est toujours recevable.",0]],"e":"Ass. plén., 22 déc. 2023, n° 20-20.648 : le contrôle de proportionnalité remplace l'irrecevabilité de principe.","r":["Ass. plén., 22 déc. 2023, n° 20-20.648"],"id":"cf0f5883"},{"c":"pre","q":"Dans quel cas l'expertise peut elle être ordonnée ?","o":[["Dans tous les cas où une partie la demande.",0],["Lorsque des constatations ou une consultation ne suffiraient pas à éclairer le juge.",1],["Uniquement en matière de construction.",0],["Uniquement avant tout procès.",0],["Uniquement avec l'accord des deux parties.",0]],"e":"Article 263 : l'expertise est subsidiaire par rapport aux constatations et à la consultation.","r":["CPC art. 263"],"id":"1e37513b"},{"c":"pre","q":"Sur la communication et la production des pièces, quelles propositions sont exactes ?","o":[["La partie qui fait état d'une pièce s'oblige à la communiquer à toute autre partie à l'instance.",1],["Le juge peut enjoindre à une partie de produire un élément de preuve qu'elle détient.",1],["Le juge peut ordonner la production d'une pièce détenue par un tiers.",1],["Le juge doit toujours retenir les pièces non communiquées en temps utile.",0],["La communication des pièces n'est jamais obligatoire.",0]],"e":"Articles 11, 132, 135, 138 et 142. Le juge peut écarter des débats les pièces qui n'ont pas été communiquées en temps utile (art. 135).","r":["CPC art. 11, 132 à 142"],"id":"f5f499a4"},{"c":"pre","q":"Au delà de quel montant un acte juridique doit il en principe être prouvé par écrit ?","o":[["750 euros.",0],["1 500 euros.",1],["3 000 euros.",0],["5 000 euros.",0],["Aucun seuil n'existe.",0]],"e":"Article 1359 du Code civil et décret fixant le seuil à 1 500 euros. Les faits juridiques se prouvent librement.","r":["C. civ. art. 1358 et 1359"],"id":"991fd5da"},{"c":"jug","q":"Après avoir prononcé son jugement, le juge peut encore :","o":[["l'interpréter.",1],["rectifier les erreurs et omissions matérielles qui l'affectent.",1],["réparer une omission de statuer.",1],["le modifier s'il estime s'être trompé en droit.",0],["en changer le dispositif à la demande d'une partie mécontente.",0]],"e":"Article 481 (dessaisissement) et ses tempéraments : articles 461, 462 et 463.","r":["CPC art. 461 à 463, 481"],"id":"f8592cad"},{"c":"jug","q":"Quel jugement a force de chose jugée ?","o":[["Tout jugement dès son prononcé.",0],["Le jugement qui n'est susceptible d'aucun recours suspensif d'exécution.",1],["Le jugement confirmé par la Cour de cassation uniquement.",0],["Le jugement assorti de l'exécution provisoire.",0],["Le jugement rendu par défaut.",0]],"e":"Article 500. Ne pas confondre avec l'autorité de la chose jugée, acquise dès le prononcé (art. 480), ni avec le caractère irrévocable.","r":["CPC art. 480 et 500"],"id":"19881357"},{"c":"jug","q":"Un jugement peut il être exécuté contre celui auquel il est opposé avant de lui avoir été notifié ?","o":[["Oui, dès son prononcé.",0],["Non, sauf exécution volontaire.",1],["Oui, s'il est assorti de l'exécution provisoire.",0],["Oui, si le jugement est contradictoire.",0],["Non, sauf autorisation du ministère public.",0]],"e":"Article 503 al. 1.","r":["CPC art. 503"],"id":"95f3d4f8"},{"c":"jug","q":"Sur la forme du jugement, quelles propositions sont exactes ?","o":[["Il expose succinctement les prétentions respectives des parties et leurs moyens.",1],["Il doit être motivé.",1],["Il énonce la décision sous forme de dispositif.",1],["La motivation est facultative en première instance.",0],["L'absence de motifs n'est sanctionnée par aucune nullité.",0]],"e":"Articles 455 et 458. L'exposé des prétentions peut revêtir la forme d'un visa des conclusions avec indication de leur date.","r":["CPC art. 455 et 458"],"id":"afb10663"},{"c":"urg","q":"Pour obtenir une provision du juge des référés, le demandeur doit établir :","o":[["l'urgence.",0],["que l'existence de l'obligation n'est pas sérieusement contestable.",1],["un trouble manifestement illicite.",0],["qu'il dispose d'un titre exécutoire.",0],["qu'aucune instance au fond n'est en cours.",0]],"e":"Article 835 al. 2 : la provision ne requiert pas l'urgence.","r":["CPC art. 835"],"id":"5645e9ed"},{"c":"urg","q":"Sur la matière gracieuse, quelles propositions sont exactes ?","o":[["Le juge statue en l'absence de litige.",1],["La loi exige, en raison de la nature de l'affaire ou de la qualité du requérant, que la demande soit soumise au contrôle du juge.",1],["Le juge peut fonder sa décision sur tous les faits relatifs au cas, même non allégués.",1],["Le délai d'appel est d'un mois.",0],["La décision est toujours rendue après un débat contradictoire entre deux parties.",0]],"e":"Articles 25 et 26 ; délai d'appel de quinze jours (art. 538).","r":["CPC art. 25, 26 et 538"],"id":"594c48be"},{"c":"urg","q":"Sur la procédure accélérée au fond, quelles propositions sont exactes ?","o":[["Elle n'est applicable que lorsque la loi le prévoit.",1],["Le juge est saisi par assignation à une audience tenue aux jour et heure prévus à cet effet.",1],["Le juge rend une décision au fond.",1],["La décision n'a pas autorité de la chose jugée au principal.",0],["Elle se confond avec le référé de l'article 834.",0]],"e":"Article 481-1, issu de la réforme ayant remplacé la procédure dite « en la forme des référés ».","r":["CPC art. 481-1"],"id":"b17c0972"},{"c":"urg","q":"Sur la rétractation d'une ordonnance sur requête, quelles propositions sont exactes ?","o":[["Elle est demandée au juge qui a rendu l'ordonnance.",1],["Elle est ouverte à tout intéressé.",1],["Depuis le décret n° 2026-683, lorsque l'ordonnance rendue sur le fondement de l'article 145 a été signifiée, la rétractation doit être demandée dans le mois de la signification, à peine d'irrecevabilité.",1],["Elle prend la forme d'un appel devant la cour.",0],["Elle n'est ouverte qu'au requérant.",0]],"e":"Articles 496 al. 2 et 497. La rétractation rétablit la contradiction devant le juge qui a statué non contradictoirement.","r":["CPC art. 496 et 497","Décret n° 2026-683"],"id":"13ed308d"},{"c":"vro","q":"Sur l'appel des jugements avant dire droit et des jugements mixtes, quelles propositions sont exactes ?","o":[["Le jugement qui tranche une partie du principal et ordonne une mesure d'instruction peut être immédiatement frappé d'appel.",1],["Le jugement qui statue sur une fin de non recevoir et met fin à l'instance peut être immédiatement frappé d'appel.",1],["Le jugement qui se borne à ordonner une mesure d'instruction ne peut en principe être frappé d'appel qu'avec le jugement sur le fond.",1],["Tous les jugements avant dire droit sont immédiatement susceptibles d'appel.",0],["Le jugement qui statue sur une exception de procédure et met fin à l'instance n'est jamais susceptible d'appel immédiat.",0]],"e":"Articles 544 et 545.","r":["CPC art. 544 et 545"],"id":"43e40cec"},{"c":"vro","q":"Sur l'opposition, quelles propositions sont exactes ?","o":[["Elle n'est ouverte qu'au défaillant.",1],["Elle porte l'affaire devant le juge qui a rendu la décision.",1],["Son délai de droit commun est d'un mois.",1],["Elle est ouverte contre le jugement réputé contradictoire.",0],["Elle est ouverte contre le jugement contradictoire.",0]],"e":"Articles 538, 571 et 572.","r":["CPC art. 538, 571 et 572"],"id":"0194979f"},{"c":"vro","q":"La déclaration d'appel ne mentionne aucun chef de jugement critiqué. Quelles propositions sont exactes ?","o":[["Elle ne produit pas d'effet dévolutif.",1],["L'appelant peut, depuis le 1er septembre 2024, compléter les chefs critiqués dans le dispositif de ses premières conclusions remises dans les délais.",1],["L'appelant peut former une nouvelle déclaration d'appel tant que le délai d'appel n'est pas expiré.",1],["La dévolution s'opère pour le tout.",0],["La cour doit statuer sur l'ensemble du jugement.",0]],"e":"Cass. 2e civ., 2 juill. 2020, n° 19-16.954 ; article 915-2 issu du décret n° 2023-1391. La régularisation par une nouvelle déclaration suppose que le délai d'appel ne soit pas expiré.","r":["Cass. 2e civ., 2 juill. 2020, n° 19-16.954","CPC art. 562 et 915-2"],"id":"fcad709c"},{"c":"vre","q":"Lesquelles de ces causes ouvrent le recours en révision ?","o":[["La fraude de la partie au profit de laquelle le jugement a été rendu.",1],["Le recouvrement, depuis le jugement, de pièces décisives retenues par le fait d'une autre partie.",1],["Un jugement rendu sur des pièces reconnues ou judiciairement déclarées fausses depuis le jugement.",1],["Une erreur de droit commise par le juge.",0],["Un revirement de jurisprudence postérieur au jugement.",0]],"e":"Article 595 ; la liste est limitative. L'erreur de droit relève du pourvoi en cassation.","r":["CPC art. 593 à 595"],"id":"cd9c87ba"},{"c":"vre","q":"Sur les suites de la cassation, quelles propositions sont exactes ?","o":[["En principe, l'affaire est renvoyée devant une autre juridiction de même nature.",1],["La Cour peut casser sans renvoi lorsque la cassation n'implique pas qu'il soit à nouveau statué sur le fond.",1],["La juridiction de renvoi doit se conformer à la décision de l'Assemblée plénière sur les points de droit jugés par celle ci.",1],["La juridiction de renvoi est toujours liée par l'arrêt de la chambre qui a cassé.",0],["La Cour de cassation apprécie souverainement les faits.",0]],"e":"Articles 626 et 627 du CPC ; articles L. 411-3 et L. 431-4 du code de l'organisation judiciaire.","r":["CPC art. 626 et 627","COJ art. L. 411-3 et L. 431-4"],"id":"10426472"},{"c":"juge","q":"Selon l'arrêt Piersack c. Belgique (CEDH, 1er oct. 1982), l'impartialité s'apprécie :","o":[["selon une démarche subjective, recherchant la conviction personnelle du juge.",1],["selon une démarche objective, vérifiant que le juge offrait des garanties suffisantes pour exclure tout doute légitime.",1],["en tenant compte, le cas échéant, des apparences.",1],["uniquement au regard des intentions déclarées du juge.",0],["uniquement pour les juridictions pénales.",0]],"e":"L'impartialité personnelle se présume jusqu'à preuve contraire ; la démarche objective peut faire jouer les apparences.","r":["CEDH, 1er oct. 1982, Piersack c. Belgique","CEDH art. 6 § 1"],"id":"1b18c4a1"},{"c":"juge","q":"Un juge des référés a alloué une provision en estimant la créance non sérieusement contestable. Peut il ensuite statuer au fond sur le même litige ?","o":[["Oui, sans restriction.",0],["Non, il a pris parti et n'est plus impartial au sens fonctionnel.",1],["Oui, si les parties y consentent tacitement.",0],["Non, car un juge des référés ne peut jamais statuer au fond.",0],["Oui, à condition de siéger en formation collégiale.",0]],"e":"Ass. plén., 6 nov. 1998, Bord Na Mona (n° 94-17.709). À l'inverse, le juge qui a seulement ordonné une mesure conservatoire peut statuer au fond (Guillotel, n° 95-11.006).","r":["Ass. plén., 6 nov. 1998, n° 94-17.709 et n° 95-11.006"],"id":"aee95d82"},{"c":"juge","q":"Sur la récusation, quelles propositions sont exactes ?","o":[["Ses causes sont énumérées par l'article L. 111-6 du code de l'organisation judiciaire.",1],["Elle doit être demandée dès que la partie a connaissance de la cause, à peine d'irrecevabilité.",1],["Elle ne peut en aucun cas être demandée après la clôture des débats.",1],["Son rejet expose son auteur à une amende civile d'un maximum de 10 000 euros.",1],["Elle vise une juridiction dans son ensemble.",0]],"e":"Articles 341, 342 et 348. C'est le renvoi pour cause de suspicion légitime qui vise la juridiction entière.","r":["CPC art. 341, 342 et 348","COJ art. L. 111-6"],"id":"da0d1597"},{"c":"juge","q":"Lesquelles de ces situations figurent parmi les causes de récusation de l'article L. 111-6 du COJ ?","o":[["Le juge a précédemment connu de l'affaire comme juge ou comme arbitre.",1],["Il existe une amitié ou une inimitié notoire entre le juge et une partie.",1],["Le juge est parent d'une partie jusqu'au quatrième degré inclusivement.",1],["Le juge a publié un article de doctrine sur la question de droit en litige.",0],["Le juge réside dans la même ville que l'une des parties.",0]],"e":"La liste comprend neuf cas, dont le conflit d'intérêts ; la Cour de cassation admet que d'autres circonstances puissent fonder un doute légitime.","r":["COJ art. L. 111-6"],"id":"aaa21ea5"},{"c":"juge","q":"Sur la publicité des débats en matière civile, quelles propositions sont exactes ?","o":[["Les débats sont publics, sauf les cas où la loi exige ou permet qu'ils aient lieu en chambre du conseil.",1],["Le Conseil constitutionnel a reconnu valeur constitutionnelle à la publicité des audiences civiles.",1],["Des limitations proportionnées, justifiées par l'intérêt général ou la nature de l'instance, sont admises.",1],["La publicité est une garantie absolue, insusceptible de toute limitation.",0],["La matière gracieuse est toujours jugée en audience publique.",0]],"e":"Articles 22 et 434 ; Cons. const., 21 mars 2019, n° 2019-778 DC.","r":["CPC art. 22 et 434","Cons. const., n° 2019-778 DC"],"id":"8d246d5d"},{"c":"juge","q":"Un juge reproduit intégralement les conclusions d'une partie en guise de motivation. Quelle conséquence la Cour de cassation en tire t elle ?","o":[["Aucune, dès lors que les conclusions sont bien rédigées.",0],["Un doute légitime sur l'impartialité du juge, justifiant la censure.",1],["Une simple erreur matérielle rectifiable.",0],["L'inexistence du jugement.",0],["Une omission de statuer.",0]],"e":"Civ. 3e, 28 janv. 2021, n° 19-19.172 (inédit) : la reproduction, sans autre motivation, des conclusions d'une partie constitue une apparence de motivation pouvant faire peser un doute sur l'impartialité de la juridiction (art. 6 § 1 Conv. EDH et art. 455).","r":["Civ. 3e, 28 janv. 2021, n° 19-19.172","CPC art. 455"],"id":"710c3d28"},{"c":"juge","q":"Sur la responsabilité de l'État du fait du service de la justice, quelles propositions sont exactes ?","o":[["Sauf dispositions particulières, elle n'est engagée que par une faute lourde ou un déni de justice.",1],["La faute lourde est toute déficience caractérisée par un fait ou une série de faits traduisant l'inaptitude du service public de la justice à remplir sa mission.",1],["Le dépassement du délai raisonnable peut caractériser un déni de justice.",1],["Le justiciable peut agir directement contre le magistrat fautif.",0],["Elle relève des juridictions administratives.",0]],"e":"Article L. 141-1 COJ ; Ass. plén., 23 févr. 2001, n° 99-16.165. La responsabilité personnelle des magistrats n'est engagée que par l'action récursoire de l'État ; le contentieux relève de l'ordre judiciaire.","r":["COJ art. L. 141-1","Ass. plén., 23 févr. 2001, n° 99-16.165"],"id":"913b316d"},{"c":"frais","q":"Sur les dépens, quelles propositions sont exactes ?","o":[["La partie perdante est en principe condamnée aux dépens.",1],["Le juge peut, par décision motivée, en mettre tout ou partie à la charge d'une autre partie.",1],["Le ministère public ne peut être condamné aux dépens.",1],["Les honoraires d'avocat font toujours partie des dépens.",0],["Le gagnant supporte toujours ses propres dépens.",0]],"e":"Article 696. Les honoraires d'avocat relèvent en principe des frais non compris dans les dépens, régis par l'article 700.","r":["CPC art. 695 et 696"],"id":"0b573959"},{"c":"frais","q":"Pour fixer la somme due au titre de l'article 700, le juge tient compte :","o":[["de l'équité.",1],["de la situation économique de la partie condamnée.",1],["du seul décompte d'honoraires produit par l'avocat, qui le lie.",0],["du taux de ressort.",0],["de la durée de l'instance exclusivement.",0]],"e":"Article 700. Le juge peut aussi, pour des raisons tirées des mêmes considérations, dire n'y avoir lieu à condamnation.","r":["CPC art. 700"],"id":"15d89638"},{"c":"frais","q":"Sur l'aide juridictionnelle et le financement du procès, quelles propositions sont exactes ?","o":[["Elle est régie par la loi du 10 juillet 1991.",1],["Elle suppose notamment l'insuffisance des ressources du demandeur.",1],["Le bénéficiaire choisit librement son avocat.",1],["Un honoraire fixé exclusivement en fonction du résultat judiciaire est licite.",0],["Elle est réservée aux personnes morales.",0]],"e":"Loi n° 91-647 du 10 juillet 1991. L'honoraire de résultat n'est licite qu'en complément d'un honoraire de diligences.","r":["Loi n° 91-647 du 10 juill. 1991","Loi n° 71-1130 du 31 déc. 1971, art. 10"],"id":"bf24f94e"},{"c":"vro","q":"Quel est le taux de ressort des juridictions civiles de première instance ?","o":[["1 500 euros.",0],["4 000 euros.",0],["5 000 euros.",1],["10 000 euros.",0],["Il n'existe pas de taux de ressort.",0]],"e":"Le montant est identique devant toutes les juridictions de première instance. Le jugement qui statue sur une demande indéterminée est, sauf disposition contraire, susceptible d'appel (art. 40).","r":["CPC art. 40","N. Cayrol, Procédure civile, 5e éd., 2025"],"id":"c1e878ab"},{"c":"vro","q":"L'appelant n'a pas exécuté un jugement assorti de l'exécution provisoire. Que peut décider le premier président ou le conseiller de la mise en état ?","o":[["La radiation de l'affaire du rôle, à la demande de l'intimé, sauf conséquences manifestement excessives ou impossibilité d'exécuter.",1],["L'irrecevabilité définitive de l'appel.",0],["La nullité de la déclaration d'appel.",0],["La condamnation d'office de l'appelant à une amende civile.",0],["L'extinction de l'action.",0]],"e":"Article 524. La Cour européenne a admis le dispositif compte tenu du contrôle de proportionnalité exercé par le juge.","r":["CPC art. 524"],"id":"2983df62"},{"c":"jug","q":"Un demandeur, débouté de sa demande d'annulation d'un prêt, saisit ensuite le juge d'une demande en réduction des intérêts au taux légal. Quelle solution ?","o":[["La demande est irrecevable en vertu de la concentration des demandes.",0],["La demande est recevable : il n'existe pas de charge de concentration des demandes.",1],["La demande se heurte nécessairement à l'autorité de la chose jugée, en vertu de l'arrêt Cesareo.",0],["La demande doit être portée devant la Cour de cassation.",0],["La demande est recevable seulement si le premier jugement n'a pas été notifié.",0]],"e":"Le demandeur n'est pas tenu de présenter dans la même instance toutes les demandes fondées sur les mêmes faits ; seuls les moyens doivent être concentrés (Civ. 1re, 30 nov. 2016, n° 15-20.043, cité par N. Cayrol).","r":["Civ. 1re, 30 nov. 2016, n° 15-20.043","Ass. plén., 7 juill. 2006, n° 04-10.672"],"id":"f7dd8241"},{"c":"m1","q":"Sur le principe de coopération issu du décret n° 2025-660, quelles propositions sont exactes ?","o":[["Il figure à l'article 21 du CPC.",1],["Il entre dans la mission du juge de concilier les parties.",1],["Le juge détermine avec les parties le mode de résolution le plus adapté, amiable ou contentieux.",1],["Il oblige les parties à conclure un accord amiable.",0],["Il a été créé par le décret n° 2019-1333.",0]],"e":"Le nouvel article 21 consacre un principe directeur de coopération. Il n'impose aucun accord : l'amiable repose sur le consentement.","r":["CPC art. 21","Décret n° 2025-660"],"id":"fa3cfdd1"},{"c":"m1","q":"Que couvre la confidentialité de l'article 1528-3 ?","o":[["Ce qui est dit, écrit ou fait au cours d'une médiation.",1],["Ce qui est dit, écrit ou fait au cours d'une audience de règlement amiable.",1],["Ce qui est dit, écrit ou fait au cours d'une conciliation confiée à un conciliateur de justice.",1],["Les pièces produites au cours du processus.",0],["La procédure participative aux fins de règlement amiable.",0]],"e":"Seuls les documents élaborés pendant le processus sont couverts ; la procédure participative relève de la déontologie des avocats. Les parties peuvent écarter la confidentialité d'un commun accord.","r":["CPC art. 1528-3"],"id":"996e78d8"},{"c":"m1","q":"Sur la transaction, quelles propositions sont exactes ?","o":[["Elle suppose des concessions réciproques.",1],["Elle peut terminer une contestation née ou prévenir une contestation à naître.",1],["Elle fait obstacle à l'introduction ou à la poursuite entre les parties d'une action ayant le même objet.",1],["Elle ne peut jamais être homologuée si elle n'est pas issue d'une médiation.",0],["C'est un acte juridictionnel.",0]],"e":"Articles 2044 et 2052 du Code civil ; la transaction, même non issue d'un mode amiable, peut être homologuée (art. 1543 CPC).","r":["C. civ. art. 2044 et 2052","CPC art. 1543"],"id":"106eb3fd"},{"c":"m1","q":"Les parties conviennent par écrit, après la naissance d'un litige, de recourir à une médiation. Quel est l'effet sur la prescription ?","o":[["Elle est interrompue.",0],["Elle est suspendue.",1],["Elle continue de courir.",0],["Elle est définitivement acquise.",0],["Elle est éteinte.",0]],"e":"Article 2238 du Code civil : suspension, puis reprise pour une durée qui ne peut être inférieure à six mois à compter de la fin déclarée de la médiation ou de la conciliation.","r":["C. civ. art. 2238"],"id":"2ac84570"},{"c":"m1","q":"Sur les tiers de l'amiable, quelles propositions sont exactes ?","o":[["Le conciliateur de justice est un auxiliaire de justice bénévole.",1],["Le médiateur est en principe rémunéré.",1],["La conciliation peut être menée par le juge lui même.",1],["Le médiateur tranche le litige par une décision qui s'impose aux parties.",0],["Le conciliateur de justice est nécessairement un avocat.",0]],"e":"Le tiers de l'amiable n'a pas de pouvoir de décision ; seul l'arbitre tranche, hors des modes amiables.","r":["CPC livre V","Loi n° 95-125 du 8 févr. 1995, art. 21"],"id":"6dd272f7"},{"c":"m2","q":"Sur l'injonction de rencontrer un médiateur ou un conciliateur, quelles propositions sont exactes ?","o":[["Elle est une mesure d'administration judiciaire, insusceptible de recours.",1],["Le juge peut ordonner la mesure si les parties y consentent ensuite (ordonnance à double détente).",1],["Depuis le 1er octobre 2026, le consentement doit être recueilli dans un délai de trois mois, sauf délai différent fixé par le juge.",1],["Elle oblige les parties à entrer en médiation.",0],["Elle est susceptible d'appel dans les quinze jours.",0]],"e":"Articles 1533 et 1534-1, dans leur rédaction issue des décrets n° 2025-660 et n° 2026-683.","r":["CPC art. 1533 et 1534-1","Décret n° 2026-683"],"id":"8ae74cd9"},{"c":"m2","q":"Une partie ne se présente pas, sans motif légitime, à la réunion d'information ordonnée par le juge. Quelle sanction encourt elle ?","o":[["Aucune.",0],["Une amende civile d'un maximum de 10 000 euros.",1],["L'irrecevabilité de sa demande.",0],["La radiation de l'affaire.",0],["Une condamnation automatique aux dépens.",0]],"e":"Article 1533-3. L'amende sanctionne l'absence injustifiée à la réunion d'information, non le refus de la médiation.","r":["CPC art. 1533-3"],"id":"6810cb6d"},{"c":"m2","q":"Quelle est la durée initiale d'une médiation ou d'une conciliation ordonnée par le juge depuis le 1er septembre 2025 ?","o":[["Trois mois.",0],["Quatre mois.",0],["Cinq mois, suivie le cas échéant d'une période de trois mois.",1],["Six mois, renouvelable une fois.",0],["Un an.",0]],"e":"Article 1534-4 : la durée initiale est passée de quatre à cinq mois.","r":["CPC art. 1534-4"],"id":"b2686a74"},{"c":"m2","q":"Sur les effets de la médiation judiciaire sur l'instance, quelles propositions sont exactes ?","o":[["Elle interrompt la péremption.",1],["Un nouveau délai de péremption court à l'expiration de la durée fixée ou au constat de la fin du processus.",1],["Le technicien désigné par le juge peut désormais concilier les parties.",1],["Elle dessaisit définitivement le juge.",0],["Elle rend l'instance caduque.",0]],"e":"Articles 1534, 1534-4 et 1535-5 ; abrogation de l'ancien article 240.","r":["CPC art. 1534 et 1535-5"],"id":"cf7a3865"},{"c":"m3","q":"Sur l'audience de règlement amiable, quelles propositions sont exactes ?","o":[["Elle a été créée par le décret n° 2023-686 du 29 juillet 2023.",1],["Elle est étendue à toutes les juridictions, sauf le conseil de prud'hommes.",1],["Elle peut être ordonnée à tout stade de la procédure, sauf devant la Cour de cassation.",1],["Elle est tenue par le juge saisi du litige.",0],["Ce qui s'y dit peut être librement invoqué devant le juge du fond.",0]],"e":"Article 1532 ; l'audience est tenue par un autre juge, et elle est couverte par la confidentialité (art. 1528-3).","r":["CPC art. 1528-3 et 1532","Décret n° 2023-686"],"id":"0c30c5c6"},{"c":"m3","q":"En appel, quel est l'effet de la convocation à une audience de règlement amiable ?","o":[["Elle interrompt les délais pour conclure ; un nouveau délai court à compter de la dernière audience de règlement amiable.",1],["Elle suspend le délai d'appel.",0],["Elle est sans effet sur les délais.",0],["Elle entraîne la caducité de la déclaration d'appel.",0],["Elle proroge les délais d'un mois.",0]],"e":"Article 915-3, renvoyant aux articles 906-2 et 908 à 910.","r":["CPC art. 915-3"],"id":"b4a34e24"},{"c":"m4","q":"Sur l'instruction conventionnelle simplifiée, quelles propositions sont exactes ?","o":[["Elle ne requiert pas d'acte contresigné par avocats.",1],["Elle peut être conclue directement entre les parties.",1],["Le juge peut écarter la convention si elle ne préserve pas les principes directeurs du procès.",1],["Elle dessaisit le juge jusqu'au jugement.",0],["Elle prive les parties de tout audiencement prioritaire.",0]],"e":"Articles 127, 129-1, 129-2 et 129-3 ; les affaires instruites conventionnellement bénéficient au contraire d'un audiencement prioritaire.","r":["CPC art. 127 à 129-3"],"id":"b703e85d"},{"c":"m4","q":"Une procédure participative aux fins de règlement amiable conclue hors instance échoue. Quelles propositions sont exactes ?","o":[["Les parties peuvent saisir le juge.",1],["Elles sont en principe dispensées du préalable obligatoire de conciliation ou de médiation.",1],["Cette dispense ne joue pas devant le conseil de prud'hommes ni devant le tribunal paritaire des baux ruraux.",1],["Elles doivent nécessairement recourir à l'arbitrage.",0],["Elles ne peuvent plus agir en justice sur le même litige.",0]],"e":"Article 1540.","r":["CPC art. 1540","C. civ. art. 2062 et s."],"id":"041a9918"},{"c":"m4","q":"Sur l'expertise conventionnelle, quelles propositions sont exactes ?","o":[["Les parties peuvent désigner elles mêmes un technicien, avant ou pendant l'instance.",1],["Lorsque la convention est conclue entre avocats, l'avis du technicien a la même valeur qu'une expertise judiciaire.",1],["Le juge peut intervenir en appui en cas de désaccord sur la désignation.",1],["Elle n'est possible qu'avant tout procès.",0],["L'avis du technicien lie toujours le juge.",0]],"e":"Articles 131 à 131-8 ; assouplissement de l'article 131 par le décret n° 2026-683.","r":["CPC art. 131 à 131-8"],"id":"7d811d49"},{"c":"m5","q":"Quels accords peuvent faire l'objet d'une homologation selon l'article 1543 ?","o":[["L'accord issu d'une médiation.",1],["L'accord issu d'une conciliation.",1],["L'accord issu d'une procédure participative.",1],["La transaction, même non issue d'un mode amiable.",1],["Un accord qui n'est ni une transaction ni issu d'un mode amiable régi par le code.",0]],"e":"Articles 1541-1 et 1543.","r":["CPC art. 1541-1 et 1543"],"id":"b2c2f508"},{"c":"m5","q":"Saisi d'une demande d'homologation, le juge :","o":[["contrôle la licéité de l'objet de l'accord.",1],["vérifie sa conformité à l'ordre public.",1],["peut en modifier les termes s'il les estime déséquilibrés.",0],["doit toujours organiser un débat contradictoire.",0],["statue en principe sans débat, sauf s'il estime nécessaire d'entendre les parties.",1]],"e":"Articles 1544 et 1545.","r":["CPC art. 1544 et 1545"],"id":"5f6d8eac"},{"c":"m5","q":"Comment l'acte contresigné par avocats constatant un accord issu d'une médiation peut il devenir un titre exécutoire sans homologation ?","o":[["Par l'apposition de la formule exécutoire par le greffe.",1],["Par sa seule signature par les parties.",0],["Par son dépôt chez un notaire, sans autre formalité.",0],["Par sa publication au registre des contentieux.",0],["Ce n'est pas possible.",0]],"e":"Article L. 111-3, 7° du code des procédures civiles d'exécution. Pour la transaction, voir la modification issue du décret n° 2026-683.","r":["CPCE art. L. 111-3, 7°"],"id":"e86bfc1d"},{"c":"a1","q":"Sur la nature de l'arbitrage, quelles propositions sont exactes ?","o":[["L'arbitre exerce la jurisdictio.",1],["L'arbitre est dépourvu d'imperium.",1],["L'arbitrage est conventionnel par sa source et juridictionnel par son objet.",1],["La sentence est revêtue de plein droit de la formule exécutoire.",0],["L'arbitre est un fonctionnaire de l'État.",0]],"e":"La sentence ne devient exécutoire qu'après une ordonnance d'exequatur du juge étatique.","r":["CPC art. 1442 et 1487"],"id":"c2624f77"},{"c":"a1","q":"Quel est le critère de l'arbitrage international en droit français ?","o":[["La nationalité étrangère d'au moins une partie.",0],["Le siège de l'arbitrage à l'étranger.",0],["La mise en cause des intérêts du commerce international.",1],["L'application d'une loi étrangère au fond.",0],["Le recours à une institution internationale d'arbitrage.",0]],"e":"Article 1504 : critère économique, tenant à une opération qui ne se dénoue pas économiquement dans un seul État.","r":["CPC art. 1504"],"id":"a422d68b"},{"c":"a1","q":"Sur les formes de la convention d'arbitrage, quelles propositions sont exactes ?","o":[["La clause compromissoire est conclue avant la naissance du litige.",1],["Le compromis porte sur un litige déjà né.",1],["La convention d'arbitrage est indépendante du contrat auquel elle se rapporte.",1],["La nullité du contrat principal entraîne nécessairement celle de la clause compromissoire.",0],["Le compromis désigne, en procédure, l'avant contrat de vente immobilière.",0]],"e":"Articles 1442 et 1447 ; autonomie de la clause (Civ. 1re, 7 mai 1963, Gosset, en matière internationale).","r":["CPC art. 1442 et 1447"],"id":"df7812a9"},{"c":"a1","q":"En arbitrage interne, la clause compromissoire doit :","o":[["être écrite, l'écrit pouvant résulter d'un échange de correspondances.",1],["désigner le ou les arbitres ou prévoir les modalités de leur désignation.",1],["porter sur des droits dont les parties ont la libre disposition.",1],["être homologuée par le juge.",0],["être conclue devant notaire.",0]],"e":"Articles 1443 et 1444 du CPC ; articles 2059 et 2060 du Code civil.","r":["CPC art. 1443 et 1444","C. civ. art. 2059 et 2060"],"id":"fcab10e1"},{"c":"a1","q":"Une clause compromissoire figure dans un contrat conclu entre un professionnel et un consommateur. Quelles propositions sont exactes ?","o":[["Elle ne peut être opposée au consommateur.",1],["Le consommateur peut choisir de s'y soumettre.",1],["Elle est nécessairement nulle.",0],["Elle s'impose au consommateur dès lors qu'elle est écrite.",0],["Elle oblige le juge étatique à se déclarer toujours incompétent.",0]],"e":"Article 2061 du Code civil : la clause n'est pas opposable à la partie qui n'a pas contracté dans le cadre de son activité professionnelle ; elle n'est pas nulle pour autant.","r":["C. civ. art. 2061"],"id":"b9daede7"},{"c":"a1","q":"En arbitrage international, la validité de la clause compromissoire :","o":[["n'est soumise à aucune condition de forme.",1],["s'apprécie d'après la commune volonté des parties, sans référence nécessaire à une loi étatique.",1],["suppose l'application de la loi du siège de l'arbitrage.",0],["suppose un écrit signé par les deux parties.",0],["exige l'intervention d'une institution d'arbitrage.",0]],"e":"Article 1507 ; Civ. 1re, 20 déc. 1993, Dalico.","r":["CPC art. 1507","Civ. 1re, 20 déc. 1993, Dalico"],"id":"71a596d2"},{"c":"a2","q":"Le juge étatique est saisi d'un litige relevant d'une clause compromissoire dont la validité est discutée. Que doit il faire ?","o":[["Se déclarer incompétent, sauf si le tribunal arbitral n'est pas encore saisi et si la convention est manifestement nulle ou manifestement inapplicable.",1],["Statuer sur la validité de la clause dans tous les cas.",0],["Surseoir à statuer jusqu'à la sentence.",0],["Allouer des dommages et intérêts à la partie lésée par la violation de la clause.",0],["Renvoyer l'affaire à la Cour de cassation.",0]],"e":"Article 1448 : effet négatif du principe compétence compétence ; le tribunal arbitral est seul compétent pour statuer sur son pouvoir juridictionnel (art. 1465).","r":["CPC art. 1448 et 1465"],"id":"6d1eab6c"},{"c":"a2","q":"Sur l'arbitre, quelles propositions sont exactes ?","o":[["Il doit révéler, avant d'accepter sa mission, toute circonstance susceptible d'affecter son indépendance ou son impartialité.",1],["Le tribunal arbitral est composé d'un ou de plusieurs arbitres en nombre impair.",1],["Un coarbitre désigné par une partie doit rester indépendant et impartial à l'égard de cette partie.",1],["Un arbitre peut favoriser la partie qui l'a désigné.",0],["Un courant d'affaires avec une partie est sans incidence.",0]],"e":"Articles 1451 et 1456.","r":["CPC art. 1451 et 1456"],"id":"e01ceefa"},{"c":"a2","q":"La convention d'arbitrage ne fixe aucun délai. Quelle est la durée de la mission du tribunal arbitral ?","o":[["Trois mois.",0],["Six mois à compter de sa saisine, sauf prorogation.",1],["Un an.",0],["Elle est illimitée.",0],["Deux ans.",0]],"e":"Article 1463 : prorogation possible par accord des parties ou par le juge d'appui.","r":["CPC art. 1463"],"id":"22455cac"},{"c":"a2","q":"Sur l'instance arbitrale, quelles propositions sont exactes ?","o":[["Le principe de la contradiction s'y applique.",1],["En arbitrage interne, la procédure est en principe confidentielle.",1],["Les parties peuvent confier à l'arbitre la mission de statuer en amiable composition.",1],["Les audiences sont publiques.",0],["L'arbitre doit toujours appliquer la loi française.",0]],"e":"Articles 1464, 1478 et 1512.","r":["CPC art. 1464, 1478 et 1512"],"id":"9eae4119"},{"c":"a3","q":"Sur la sentence arbitrale, quelles propositions sont exactes ?","o":[["Elle doit être motivée.",1],["Elle a l'autorité de la chose jugée dès qu'elle est rendue.",1],["Elle dessaisit le tribunal arbitral de la contestation qu'elle tranche.",1],["Elle est exécutoire sans intervention du juge étatique.",0],["Elle est rendue à l'unanimité obligatoirement.",0]],"e":"Articles 1480, 1482, 1484 et 1485 ; la sentence est rendue à la majorité des voix (art. 1480).","r":["CPC art. 1480, 1482, 1484 et 1485"],"id":"ec113315"},{"c":"a3","q":"Sur le recours contre une sentence rendue en arbitrage interne, quelles propositions sont exactes ?","o":[["L'appel est exclu, sauf volonté contraire des parties.",1],["Le recours en annulation est ouvert dans le mois de la notification de la sentence.",1],["Le délai et l'exercice du recours en annulation sont suspensifs d'exécution.",1],["Après annulation, la cour d'appel statue en principe sur le fond dans les limites de la mission de l'arbitre.",1],["Le recours en annulation est porté devant le tribunal judiciaire.",0]],"e":"Articles 1489, 1491, 1493, 1494 et 1496 ; le recours est porté devant la cour d'appel.","r":["CPC art. 1489 à 1496"],"id":"d2700197"},{"c":"a3","q":"Lesquels de ces griefs ouvrent le recours en annulation d'une sentence en arbitrage interne ?","o":[["Le tribunal arbitral a été irrégulièrement constitué.",1],["Le principe de la contradiction n'a pas été respecté.",1],["La sentence n'est pas motivée.",1],["L'arbitre a mal apprécié les faits.",0],["L'arbitre a commis une erreur de droit non contraire à l'ordre public.",0]],"e":"Article 1492 : la liste des six cas est limitative ; le recours en annulation n'est pas un appel.","r":["CPC art. 1492"],"id":"9a4cc8bd"},{"c":"a3","q":"Sur le recours contre une sentence internationale rendue en France, quelles propositions sont exactes ?","o":[["Seul le recours en annulation est ouvert.",1],["Il est porté devant la cour d'appel de Paris.",1],["Il n'est pas suspensif d'exécution.",1],["La contrariété à l'ordre public international est un cas d'ouverture.",1],["Après annulation, la cour d'appel rejuge toujours le fond.",0]],"e":"Articles 1518, 1519, 1520 et 1526 ; le recours relève de la cour d'appel de Paris (art. 1519).","r":["CPC art. 1518 à 1526"],"id":"bf9b6703"},{"c":"a3","q":"Une sentence internationale a été annulée dans le pays du siège. Peut elle être reconnue en France ?","o":[["Non, jamais.",0],["Oui : n'étant rattachée à aucun ordre juridique étatique, elle peut être reconnue en France.",1],["Oui, mais seulement si le pays du siège est membre de l'Union européenne.",0],["Seulement après un nouvel arbitrage.",0],["Seulement avec l'accord de la partie perdante.",0]],"e":"Civ. 1re, 29 juin 2007, Putrabali.","r":["Civ. 1re, 29 juin 2007, Putrabali","Convention de New York, 10 juin 1958"],"id":"ac441f7e"},{"c":"e1","q":"Pour poursuivre l'exécution forcée sur les biens de son débiteur, le créancier doit disposer :","o":[["d'un titre exécutoire.",1],["d'une créance liquide.",1],["d'une créance exigible.",1],["d'une autorisation préalable du juge de l'exécution dans tous les cas.",0],["d'un acte sous signature privée non contresigné.",0]],"e":"Article L. 111-2 CPCE. L'autorisation du juge n'est requise que pour certaines mesures, notamment conservatoires.","r":["CPCE art. L. 111-2"],"id":"f4b5afb4"},{"c":"e1","q":"Lesquels de ces actes constituent des titres exécutoires ?","o":[["Un acte notarié revêtu de la formule exécutoire.",1],["Une sentence arbitrale déclarée exécutoire.",1],["Un extrait de procès verbal de conciliation signé par le juge et les parties.",1],["Un accord issu d'une médiation contresigné par les avocats de chacune des parties et revêtu de la formule exécutoire par le greffe.",1],["Une simple reconnaissance de dette sous signature privée.",0]],"e":"Article L. 111-3 CPCE.","r":["CPCE art. L. 111-3"],"id":"9493ce97"},{"c":"e1","q":"Pendant quelle durée l'exécution d'un jugement peut elle être poursuivie, en principe ?","o":[["Deux ans.",0],["Cinq ans.",0],["Dix ans, sauf délai de prescription plus long de l'action en recouvrement.",1],["Trente ans.",0],["Sans limite de durée.",0]],"e":"Article L. 111-4 CPCE.","r":["CPCE art. L. 111-4"],"id":"24a4d1f3"},{"c":"e1","q":"Sur les limites de l'exécution forcée, quelles propositions sont exactes ?","o":[["Le créancier choisit les mesures, mais l'exécution ne peut excéder ce qui est nécessaire.",1],["Le juge de l'exécution peut ordonner la mainlevée d'une mesure inutile ou abusive.",1],["Les biens mobiliers nécessaires à la vie et au travail du débiteur sont en principe insaisissables.",1],["Le juge peut accorder des délais de grâce dans la limite de cinq ans.",0],["Un compte bancaire peut être saisi en totalité, sans solde insaisissable.",0]],"e":"Articles L. 111-7, L. 112-2 et L. 121-2 CPCE ; article 1343-5 du Code civil (deux ans) ; solde bancaire insaisissable.","r":["CPCE art. L. 111-7, L. 112-2, L. 121-2","C. civ. art. 1343-5"],"id":"5a6f2302"},{"c":"e1","q":"L'État refuse de prêter le concours de la force publique à l'exécution d'un jugement d'expulsion. Quelle conséquence ?","o":[["Aucune, le refus relève de son pouvoir discrétionnaire sans conséquence.",0],["Le refus ouvre droit à réparation au profit du créancier.",1],["Le jugement devient caduc.",0],["Le créancier doit saisir à nouveau le juge du fond.",0],["Le débiteur est libéré de son obligation.",0]],"e":"Article L. 153-1 CPCE ; l'exécution fait partie du droit au procès équitable (Hornsby c. Grèce).","r":["CPCE art. L. 153-1"],"id":"148bb1f8"},{"c":"e2","q":"Sur les pouvoirs du juge de l'exécution, quelles propositions sont exactes ?","o":[["Il ne peut modifier le dispositif de la décision qui sert de fondement aux poursuites.",1],["Il ne peut en suspendre l'exécution.",1],["Il peut accorder un délai de grâce après signification d'un commandement ou d'un acte de saisie.",1],["Il peut réformer la décision de condamnation s'il l'estime mal fondée.",0],["Il statue toujours en dernier ressort.",0]],"e":"Article R. 121-1 CPCE.","r":["CPCE art. R. 121-1"],"id":"e707edc7"},{"c":"e2","q":"Sur la décision n° 2023-1068 QPC et la compétence du juge de l'exécution, quelles propositions sont exactes ?","o":[["Le Conseil constitutionnel a censuré les mots de l'article L. 213-6 COJ visant les contestations élevées à l'occasion de l'exécution forcée.",1],["La censure était motivée par l'impossibilité pour le débiteur de contester devant un juge la mise à prix des droits incorporels saisis.",1],["L'abrogation a pris effet le 1er décembre 2024.",1],["Par un avis du 13 mars 2025, la Cour de cassation a retenu que le juge de l'exécution demeure compétent pour les contestations relatives aux mesures d'exécution forcée mobilières, dans les limites de la décision.",1],["Depuis la loi n° 2026-403 du 26 mai 2026, le contentieux de l'exécution forcée mobilière relève du tribunal judiciaire statuant au fond.",0]],"e":"Cons. const., 17 nov. 2023, n° 2023-1068 QPC ; Cass. 2e civ., avis, 13 mars 2025, n° 25-70.003 s. ; la loi n° 2026-403 du 26 mai 2026 a rétabli la compétence exclusive du juge de l'exécution et créé un recours contre la mise à prix des droits incorporels saisis.","r":["COJ art. L. 213-6","Cons. const., n° 2023-1068 QPC","Cass. avis, 13 mars 2025","Loi n° 2026-403 du 26 mai 2026"],"id":"5e59c31a"},{"c":"e2","q":"Sur l'astreinte, quelles propositions sont exactes ?","o":[["Elle est indépendante des dommages et intérêts.",1],["Elle est provisoire, sauf si le juge a précisé son caractère définitif.",1],["Elle est supprimée si l'inexécution provient d'une cause étrangère.",1],["Le taux d'une astreinte définitive peut être librement modifié lors de sa liquidation.",0],["Une astreinte définitive peut être prononcée d'emblée, sans astreinte provisoire préalable.",0]],"e":"Articles L. 131-1, L. 131-2 et L. 131-4 CPCE ; tout juge peut ordonner une astreinte ; l'astreinte définitive suppose le prononcé préalable d'une astreinte provisoire.","r":["CPCE art. L. 131-1 à L. 131-4"],"id":"d5731220"},{"c":"e3","q":"Quelles sont les conditions d'une mesure conservatoire ?","o":[["Une créance paraissant fondée en son principe.",1],["Des circonstances susceptibles d'en menacer le recouvrement.",1],["En principe, l'autorisation du juge, sauf dispense légale.",1],["Une créance liquide et exigible constatée par un titre exécutoire, dans tous les cas.",0],["Un commandement de payer préalable.",0]],"e":"Articles L. 511-1 et L. 511-2 CPCE : la mesure est pratiquée sans commandement préalable.","r":["CPCE art. L. 511-1 et L. 511-2"],"id":"5df3bede"},{"c":"e3","q":"Une saisie conservatoire est pratiquée sans titre exécutoire. Dans quel délai le créancier doit il agir pour obtenir un titre ?","o":[["Huit jours.",0],["Un mois suivant l'exécution de la mesure, à peine de caducité.",1],["Trois mois.",0],["Six mois.",0],["Aucun délai n'est imposé.",0]],"e":"Article R. 511-7 CPCE. L'autorisation elle même est caduque si la mesure n'est pas exécutée dans les trois mois (art. R. 511-6).","r":["CPCE art. R. 511-6 et R. 511-7"],"id":"28d041d6"},{"c":"e4","q":"Sur la saisie attribution, quelles propositions sont exactes ?","o":[["Elle emporte attribution immédiate de la créance saisie disponible au profit du saisissant.",1],["Le tiers saisi doit déclarer l'étendue de ses obligations envers le débiteur.",1],["Elle doit être dénoncée au débiteur dans les huit jours, à peine de caducité.",1],["Les contestations sont portées devant le juge de l'exécution dans le délai d'un mois à compter de la dénonciation.",1],["Le premier saisissant subit le concours des créanciers saisissant ultérieurement.",0]],"e":"Articles L. 211-1 à L. 211-3, R. 211-3 et R. 211-11 CPCE.","r":["CPCE art. L. 211-1 à L. 211-3, R. 211-3, R. 211-11"],"id":"2689cc4a"},{"c":"e4","q":"Sur la saisie des rémunérations depuis le 1er juillet 2025, quelles propositions sont exactes ?","o":[["Elle est mise en œuvre par un commissaire de justice.",1],["Elle ne peut être pratiquée qu'un mois après la signification d'un commandement de payer.",1],["Un commissaire de justice répartiteur reçoit et répartit les sommes.",1],["Elle suppose une audience de conciliation préalable devant le juge.",0],["Toute contestation du débiteur devant le juge de l'exécution suspend la procédure, quelle que soit sa date.",0]],"e":"Articles L. 212-2 à L. 212-9 CPCE, issus de la loi n° 2023-1059 du 20 nov. 2023, art. 47 ; décret n° 2025-125 du 12 févr. 2025. La contestation n'est suspensive que si elle est formée dans le mois de la signification du commandement (art. L. 212-4).","r":["CPCE art. L. 212-2 à L. 212-9","Loi n° 2023-1059","Décret n° 2025-125"],"id":"4a9f9b4d"},{"c":"e4","q":"Sur la saisie vente, quelles propositions sont exactes ?","o":[["Elle porte sur les biens meubles corporels du débiteur.",1],["Elle est précédée d'un commandement de payer.",1],["Le débiteur dispose d'un délai d'un mois pour procéder à la vente amiable des biens saisis.",1],["Elle porte sur les créances de sommes d'argent détenues par un tiers.",0],["Elle ne requiert aucun titre exécutoire.",0]],"e":"Articles L. 221-1, L. 221-3 et R. 221-30 CPCE ; la saisie de créances relève de la saisie attribution.","r":["CPCE art. L. 221-1, L. 221-3, R. 221-30"],"id":"cbda04b1"},{"c":"e5","q":"Sur l'expulsion d'un lieu habité, quelles propositions sont exactes ?","o":[["Elle suppose une décision de justice ou un procès verbal de conciliation exécutoire et un commandement de quitter les lieux.",1],["Elle ne peut en principe avoir lieu qu'à l'expiration d'un délai de deux mois suivant le commandement.",1],["Depuis 2023, les délais accordés par le juge sont compris entre un mois et un an.",1],["Elle peut être exécutée à tout moment pendant la trêve hivernale.",0],["Les délais accordés par le juge peuvent atteindre trois ans.",0]],"e":"Articles L. 411-1, L. 412-1, L. 412-3, L. 412-4 et L. 412-6 CPCE, dans leur rédaction issue de la loi n° 2023-668 du 27 juillet 2023.","r":["CPCE art. L. 411-1 à L. 412-6","Loi n° 2023-668"],"id":"cb221901"},{"c":"e5","q":"Quelle est la période de la trêve hivernale ?","o":[["Du 1er octobre au 31 mars.",0],["Du 1er novembre au 31 mars de l'année suivante.",1],["Du 15 novembre au 15 mars.",0],["Du 1er décembre au 28 février.",0],["Du 1er novembre au 30 avril.",0]],"e":"Article L. 412-6 CPCE ; elle ne s'applique pas lorsque l'expulsion a été prononcée en raison d'une introduction sans droit ni titre dans le domicile d'autrui à l'aide de manœuvres, de menaces, de voies de fait ou de contrainte.","r":["CPCE art. L. 412-6"],"id":"ddc1cbe9"},{"c":"e5","q":"Sur la saisie immobilière, quelles propositions sont exactes ?","o":[["Elle tend à la vente forcée de l'immeuble en vue de la distribution de son prix.",1],["Elle débute par un commandement de payer valant saisie, publié au fichier immobilier.",1],["Le juge de l'exécution peut autoriser une vente amiable lors de l'audience d'orientation.",1],["Elle peut être pratiquée sans titre exécutoire.",0],["Elle relève du tribunal de commerce.",0]],"e":"Articles L. 311-1 et suivants CPCE.","r":["CPCE art. L. 311-1 et s."],"id":"61f86a61"},{"c":"l1","q":"Sur les modalités du grand oral du CRFPA, quelles propositions sont exactes ?","o":[["L'exposé dure quinze minutes.",1],["La préparation dure une heure.",1],["L'entretien avec le jury dure trente minutes selon l'arrêté.",1],["L'épreuve se déroule à huis clos.",0],["L'épreuve est affectée du coefficient 2.",0]],"e":"Arrêté du 17 octobre 2016 modifié, art. 7 : exposé de quinze minutes après une heure de préparation, entretien de trente minutes, séance publique ; coefficient 4.","r":["Arrêté du 17 oct. 2016, art. 7"],"id":"d0cb7eb0"},{"c":"l1","q":"Quelles rubriques figurent au programme du grand oral ?","o":[["La culture juridique générale.",1],["L'origine et les sources des libertés et droits fondamentaux.",1],["Le régime juridique des libertés et droits fondamentaux.",1],["Les principales libertés et les principaux droits fondamentaux.",1],["La déontologie notariale.",0]],"e":"Le programme comprend quatre rubriques. La culture juridique générale permet des questions débordant les libertés (TA Paris, 5 mars 2025).","r":["Arrêté du 17 oct. 2016, annexe"],"id":"78cad3e9"},{"c":"l1","q":"Quels termes figurent dans le serment de l'avocat ?","o":[["Dignité.",1],["Indépendance.",1],["Humanité.",1],["Loyauté envers le client en toutes circonstances.",0],["Neutralité.",0]],"e":"« Je jure, comme avocat, d'exercer mes fonctions avec dignité, conscience, indépendance, probité et humanité » (loi n° 71-1130 du 31 déc. 1971, art. 3).","r":["Loi n° 71-1130, art. 3"],"id":"6d45633a"},{"c":"l2","q":"Que comprend le bloc de constitutionnalité ?","o":[["La Déclaration des droits de l'homme et du citoyen de 1789.",1],["Le Préambule de la Constitution de 1946.",1],["La Charte de l'environnement de 2004.",1],["La Convention européenne des droits de l'homme.",0],["Le Code civil.",0]],"e":"Le Préambule de 1958 renvoie à la Déclaration de 1789, au Préambule de 1946 et à la Charte de l'environnement ; s'y ajoutent les principes fondamentaux reconnus par les lois de la République. La Convention européenne n'en fait pas partie (74-54 DC).","r":["Cons. const., 71-44 DC","Cons. const., 74-54 DC"],"id":"74f71524"},{"c":"l2","q":"Quelle est la portée de la décision du Conseil constitutionnel du 16 juillet 1971 ?","o":[["Elle reconnaît la valeur constitutionnelle du Préambule.",1],["Elle consacre la liberté d'association comme principe fondamental reconnu par les lois de la République.",1],["Elle crée la question prioritaire de constitutionnalité.",0],["Elle refuse de contrôler la conformité des lois aux traités.",0],["Elle consacre le principe de fraternité.",0]],"e":"Cons. const., 16 juill. 1971, n° 71-44 DC, Liberté d'association.","r":["Cons. const., 71-44 DC"],"id":"177f6116"},{"c":"l2","q":"Qui contrôle la conformité des lois aux traités en droit français ?","o":[["Le Conseil constitutionnel, dans le cadre du contrôle a priori.",0],["Les juridictions judiciaires, depuis l'arrêt Jacques Vabre.",1],["Les juridictions administratives, depuis l'arrêt Nicolo.",1],["Personne : la loi postérieure l'emporte toujours.",0],["La Cour européenne, sur renvoi préjudiciel.",0]],"e":"74-54 DC (refus du Conseil constitutionnel) ; Ch. mixte, 24 mai 1975, Jacques Vabre ; CE, Ass., 20 oct. 1989, Nicolo.","r":["Cons. const., 74-54 DC","CE, Ass., Nicolo"],"id":"3763c0cc"},{"c":"l2","q":"Sur la Charte des droits fondamentaux de l'Union européenne, quelles propositions sont exactes ?","o":[["Elle a force contraignante depuis le traité de Lisbonne.",1],["Elle a la même valeur juridique que les traités.",1],["Elle s'applique aux États membres lorsqu'ils mettent en œuvre le droit de l'Union.",1],["Elle se substitue à la Convention européenne des droits de l'homme.",0],["Elle est appliquée par la Cour européenne des droits de l'homme.",0]],"e":"Art. 6 TUE ; Charte, art. 51. La CJUE en est l'interprète.","r":["TUE, art. 6"],"id":"4e78c172"},{"c":"l2","q":"Quelles exigences le Conseil constitutionnel a t il dégagées ?","o":[["La sauvegarde de la dignité de la personne humaine.",1],["Le principe de fraternité.",1],["L'objectif de valeur constitutionnelle de protection de l'environnement.",1],["Un droit constitutionnel à l'enfant.",0],["Un droit à la désobéissance civile.",0]],"e":"94-343/344 DC ; 2018-717/718 QPC ; 2019-823 QPC.","r":["Cons. const., 94-343/344 DC","2018-717/718 QPC","2019-823 QPC"],"id":"b314be73"},{"c":"l2","q":"Depuis la loi constitutionnelle du 8 mars 2024, que prévoit l'article 34 de la Constitution ?","o":[["La loi détermine les conditions dans lesquelles s'exerce la liberté garantie à la femme d'avoir recours à une interruption volontaire de grossesse.",1],["Un droit inconditionnel à l'interruption volontaire de grossesse, sans intervention de la loi.",0],["L'interdiction de toute limitation de délai.",0],["La compétence du pouvoir réglementaire autonome.",0],["Le transfert de la matière au référendum.",0]],"e":"Loi constitutionnelle n° 2024-200 du 8 mars 2024.","r":["Constitution, art. 34"],"id":"e2a5a4a6"},{"c":"l3","q":"Sur les régimes juridiques des libertés, quelles propositions sont exactes ?","o":[["Le régime répressif est le plus libéral.",1],["Le régime de la presse issu de la loi de 1881 est répressif.",1],["Les manifestations sur la voie publique relèvent d'un régime de déclaration préalable.",1],["La constitution d'une association suppose une autorisation préfectorale.",0],["Le régime préventif ne laisse aucune place à l'autorisation.",0]],"e":"Loi du 29 juillet 1881 ; loi du 1er juillet 1901 (pas d'autorisation) ; déclaration préalable des manifestations.","r":["Loi du 29 juill. 1881","Loi du 1er juill. 1901"],"id":"abee57a5"},{"c":"l3","q":"Quel est l'apport de l'arrêt Benjamin ?","o":[["Une mesure de police doit être nécessaire et proportionnée à la menace pour l'ordre public.",1],["Il consacre la dignité comme composante de l'ordre public.",0],["Il crée le référé liberté.",0],["Il admet le contrôle de conventionnalité.",0],["Il définit la voie de fait.",0]],"e":"CE, 19 mai 1933, Benjamin, n° 17413 : contrôle approfondi de l'interdiction d'une conférence.","r":["CE, 19 mai 1933, Benjamin"],"id":"f13d0d58"},{"c":"l3","q":"Quels droits de la Convention européenne ne souffrent aucune dérogation au titre de l'article 15 ?","o":[["L'interdiction de la torture et des traitements inhumains ou dégradants.",1],["Le droit à la vie, sauf décès résultant d'actes licites de guerre.",1],["L'interdiction de l'esclavage et de la servitude.",1],["La liberté de réunion.",0],["Le droit au respect de la vie privée.",0]],"e":"Art. 15 § 2 Conv. EDH : articles 2, 3, 4 § 1 et 7 indérogeables.","r":["Conv. EDH, art. 15"],"id":"e1881a6f"},{"c":"l3","q":"Quelles conditions la Cour européenne vérifie t elle pour une ingérence dans les droits des articles 8 à 11 ?","o":[["L'ingérence est prévue par la loi.",1],["Elle poursuit un but légitime.",1],["Elle est nécessaire dans une société démocratique.",1],["Elle a été approuvée par référendum.",0],["Elle est temporaire par nature.",0]],"e":"Paragraphes 2 des articles 8 à 11 de la Convention.","r":["Conv. EDH, art. 8 à 11"],"id":"a8fcb6df"},{"c":"l4","q":"Sur la question prioritaire de constitutionnalité, quelles propositions sont exactes ?","o":[["Elle est entrée en vigueur le 1er mars 2010.",1],["Elle porte sur une disposition législative portant atteinte aux droits et libertés que la Constitution garantit.",1],["Le Conseil d'État ou la Cour de cassation statue sur le renvoi dans un délai de trois mois.",1],["Elle peut viser un décret.",0],["Elle peut être soulevée d'office par le juge.",0]],"e":"Art. 61-1 de la Constitution ; ordonnance n° 58-1067 du 7 nov. 1958 modifiée. Le moyen est soulevé par une partie, non d'office.","r":["Constitution, art. 61-1"],"id":"178780e2"},{"c":"l4","q":"Sur le référé liberté, quelles propositions sont exactes ?","o":[["Il suppose l'urgence.",1],["Il suppose une atteinte grave et manifestement illégale à une liberté fondamentale.",1],["Le juge se prononce dans les quarante huit heures.",1],["Il relève du juge judiciaire.",0],["Il suppose un recours au fond préalablement introduit.",0]],"e":"Art. L. 521-2 CJA. À la différence du référé suspension, aucune requête au fond n'est exigée.","r":["CJA, art. L. 521-2"],"id":"86417e46"},{"c":"l4","q":"Depuis l'arrêt Bergoend, quand y a t il voie de fait ?","o":[["Lorsque l'administration porte une atteinte à la liberté individuelle ou aboutit à l'extinction d'un droit de propriété, par une décision ou une exécution manifestement insusceptible de se rattacher à un pouvoir lui appartenant.",1],["Dès qu'une atteinte quelconque est portée à la propriété privée.",0],["Dès qu'un acte administratif est illégal.",0],["Uniquement en cas d'atteinte à la liberté d'expression.",0],["Lorsque le juge administratif est indisponible.",0]],"e":"TC, 17 juin 2013, Bergoend c. Société ERDF Annecy Léman, n° 3911.","r":["TC, 17 juin 2013, Bergoend"],"id":"1151892f"},{"c":"l4","q":"Sur la saisine de la Cour européenne des droits de l'homme, quelles propositions sont exactes ?","o":[["Le requérant doit avoir épuisé les voies de recours internes.",1],["Le délai est de quatre mois depuis le 1er février 2022.",1],["Le requérant doit se prétendre victime d'une violation.",1],["Le délai est de six mois à compter de la violation.",0],["Seuls les États peuvent la saisir.",0]],"e":"Art. 34 et 35 Conv. EDH, protocole n° 15.","r":["Conv. EDH, art. 34 et 35"],"id":"d6d9af0b"},{"c":"l4","q":"Qu'est ce que le protocole n° 16 à la Convention européenne ?","o":[["Il permet aux plus hautes juridictions de demander un avis consultatif à la Cour européenne.",1],["Il est en vigueur depuis le 1er août 2018.",1],["La Cour de cassation a été la première juridiction à l'utiliser.",1],["Il réduit le délai de saisine à quatre mois.",0],["Il rend les avis contraignants.",0]],"e":"L'avis n'est pas contraignant. La réduction du délai résulte du protocole n° 15.","r":["Protocole n° 16"],"id":"8f53b079"},{"c":"l4","q":"Quelles autorités assurent une protection non juridictionnelle des droits ?","o":[["Le Défenseur des droits.",1],["Le Contrôleur général des lieux de privation de liberté.",1],["La Commission nationale de l'informatique et des libertés.",1],["Le Conseil supérieur de la magistrature, juge des libertés.",0],["Le juge des libertés et de la détention.",0]],"e":"Art. 71-1 de la Constitution ; loi n° 2007-1545 ; loi n° 78-17. Le juge des libertés et de la détention est une juridiction.","r":["Constitution, art. 71-1"],"id":"b100199d"},{"c":"l4","q":"Quel arrêt fonde le droit d'accès à un tribunal au titre de l'article 6 ?","o":[["Golder c. Royaume Uni (1975).",1],["Handyside c. Royaume Uni (1976).",0],["Hornsby c. Grèce (1997).",0],["Bouyid c. Belgique (2015).",0],["S.A.S. c. France (2014).",0]],"e":"CEDH, 21 févr. 1975, Golder. Hornsby concerne l'exécution des décisions.","r":["CEDH, Golder"],"id":"49e69f2a"},{"c":"l5","q":"Sur la dignité de la personne humaine, quelles propositions sont exactes ?","o":[["Le Conseil constitutionnel en a fait un principe à valeur constitutionnelle en 1994.",1],["Le Conseil d'État en a fait une composante de l'ordre public en 1995.",1],["L'article 16 du Code civil interdit toute atteinte à la dignité de la personne.",1],["Elle ne peut jamais justifier une mesure de police.",0],["Elle est consacrée expressément par la Déclaration de 1789.",0]],"e":"94-343/344 DC ; CE, Ass., 27 oct. 1995, Commune de Morsang sur Orge.","r":["94-343/344 DC","CE, Morsang sur Orge"],"id":"26649359"},{"c":"l5","q":"Dans l'affaire Vincent Lambert, quelles propositions sont exactes ?","o":[["Le Conseil d'État a jugé légale la décision d'arrêt des traitements en 2014.",1],["La Cour européenne n'a pas constaté de violation de l'article 2.",1],["La Cour européenne a statué en Grande Chambre en 2015.",1],["La Cour européenne a condamné la France pour violation de l'article 3.",0],["L'affaire a été tranchée par le Conseil constitutionnel.",0]],"e":"CE, Ass., 24 juin 2014, n° 375081 ; CEDH, GC, 5 juin 2015, Lambert et autres c. France.","r":["CE, Ass., 24 juin 2014","CEDH, GC, Lambert"],"id":"4ce08b90"},{"c":"l5","q":"Qu'a jugé la Cour européenne dans l'arrêt J.M.B. c. France ?","o":[["Les conditions de détention dans plusieurs établissements violaient l'article 3.",1],["La France ne disposait pas d'un recours préventif effectif contre ces conditions.",1],["L'arrêt a conduit à la création d'un recours devant le juge judiciaire en 2021.",1],["La surpopulation carcérale ne relève pas de la Convention.",0],["La France a été condamnée pour violation de l'article 10.",0]],"e":"CEDH, 30 janv. 2020, n° 9671/15 ; loi n° 2021-403 du 8 avril 2021, art. 803-8 CPP.","r":["CEDH, J.M.B. c. France"],"id":"0065e16f"},{"c":"l5","q":"Que prévoit la loi Claeys Leonetti du 2 février 2016 ?","o":[["L'interdiction de l'obstination déraisonnable.",1],["Un droit à la sédation profonde et continue dans certaines conditions.",1],["La légalisation du suicide assisté.",0],["La suppression des directives anticipées.",0],["L'interdiction de tout arrêt des traitements.",0]],"e":"Loi n° 2016-87 du 2 février 2016.","r":["Loi n° 2016-87"],"id":"2027476d"},{"c":"l6","q":"Sur la garde à vue, quelles propositions sont exactes ?","o":[["Le Conseil constitutionnel a censuré le régime de droit commun en 2010.",1],["Il a différé dans le temps l'effet de l'abrogation.",1],["La Cour européenne a condamné la France dans l'arrêt Brusco.",1],["La réforme est intervenue par la loi du 14 avril 2011.",1],["Le Conseil constitutionnel a jugé la présence de l'avocat inutile.",0]],"e":"Cons. const., 30 juill. 2010, n° 2010-14/22 QPC ; CEDH, 14 oct. 2010, Brusco c. France ; loi n° 2011-392.","r":["2010-14/22 QPC","CEDH, Brusco"],"id":"17accdf1"},{"c":"l6","q":"À quel texte le Conseil constitutionnel rattache t il le droit au respect de la vie privée ?","o":[["L'article 2 de la Déclaration de 1789.",1],["L'article 66 de la Constitution.",0],["L'alinéa 11 du Préambule de 1946.",0],["L'article 9 du Code civil.",0],["L'article 8 de la Convention européenne.",0]],"e":"Cons. const., 23 juill. 1999, n° 99-416 DC.","r":["99-416 DC"],"id":"f308b7dc"},{"c":"l6","q":"Qu'a jugé la Cour européenne dans l'arrêt Mennesson c. France ?","o":[["Le refus de reconnaître la filiation d'enfants nés par gestation pour autrui à l'égard de leur père biologique violait le droit des enfants au respect de leur vie privée.",1],["La France doit autoriser la gestation pour autrui sur son territoire.",0],["Le droit des parents au respect de leur vie familiale a été violé.",0],["La gestation pour autrui est contraire à l'article 3.",0],["L'affaire relevait de l'article 14 seul.",0]],"e":"CEDH, 26 juin 2014, n° 65192/11 : violation de l'article 8 dans le chef des enfants.","r":["CEDH, Mennesson"],"id":"21178995"},{"c":"l6","q":"Qu'a jugé la Cour européenne dans l'affaire KlimaSeniorinnen ?","o":[["L'article 8 comprend un droit à une protection effective contre les effets graves du changement climatique.",1],["La Suisse a manqué à ses obligations positives.",1],["L'arrêt a été rendu en Grande Chambre le 9 avril 2024.",1],["Toute personne peut agir sans démontrer d'atteinte particulière.",0],["La Cour a fixé elle même un budget carbone à la Suisse.",0]],"e":"CEDH, GC, 9 avr. 2024, Verein KlimaSeniorinnen Schweiz et autres c. Suisse, n° 53600/20.","r":["CEDH, GC, KlimaSeniorinnen"],"id":"e0e50d33"},{"c":"l7","q":"Sur la liberté d'expression, quelles propositions sont exactes ?","o":[["Elle protège aussi les idées qui heurtent, choquent ou inquiètent.",1],["L'article 11 de la Déclaration de 1789 la qualifie de droit des plus précieux.",1],["La liberté d'expression de l'avocat bénéficie d'une protection renforcée.",1],["Elle est un droit absolu insusceptible de restriction.",0],["Le régime de la presse est un régime d'autorisation.",0]],"e":"CEDH, Handyside (1976) ; Morice c. France (2015) ; art. 10 § 2 Conv. EDH.","r":["CEDH, Handyside","CEDH, Morice"],"id":"c4a7171e"},{"c":"l7","q":"Dans l'ordonnance Dieudonné du 9 janvier 2014, sur quoi le juge des référés s'est il fondé ?","o":[["L'atteinte à la dignité de la personne humaine.",1],["Le risque de commission d'infractions pénales.",1],["L'absence totale de liberté d'expression des humoristes.",0],["Le défaut de déclaration préalable du spectacle.",0],["La violation du droit de propriété.",0]],"e":"CE, ord., 9 janv. 2014, n° 374508, décision discutée en doctrine.","r":["CE, ord., 9 janv. 2014"],"id":"04994c00"},{"c":"l7","q":"Sur la laïcité et la liberté religieuse, quelles propositions sont exactes ?","o":[["La Cour européenne a admis l'interdiction de la dissimulation du visage dans l'espace public.",1],["Le juge des référés a suspendu un arrêté municipal dit anti burkini en 2016.",1],["La laïcité figure à l'article 1er de la Constitution.",1],["La loi de 1905 interdit tout signe religieux dans l'espace public.",0],["La liberté de manifester sa religion est absolue.",0]],"e":"CEDH, GC, S.A.S. c. France (2014) ; CE, ord., 26 août 2016, n° 402742.","r":["CEDH, S.A.S. c. France","CE, ord., 26 août 2016"],"id":"26a1b8c3"},{"c":"l7","q":"Quel est le régime de la liberté d'association ?","o":[["Un principe fondamental reconnu par les lois de la République.",1],["La constitution est libre, sans autorisation préalable.",1],["La capacité juridique suppose une déclaration en préfecture.",1],["Toute association doit être autorisée par le juge judiciaire.",0],["Elle relève exclusivement du droit de l'Union.",0]],"e":"71-44 DC ; loi du 1er juillet 1901.","r":["71-44 DC","Loi de 1901"],"id":"47db3d4e"},{"c":"l8","q":"Sur le principe d'égalité, quelles propositions sont exactes ?","o":[["Il ne s'oppose pas à ce que des situations différentes soient réglées différemment.",1],["Une dérogation pour motif d'intérêt général est possible.",1],["La différence de traitement doit être en rapport direct avec l'objet de la loi.",1],["Il interdit toute différence de traitement.",0],["La France a ratifié le protocole n° 12 sur l'interdiction générale de la discrimination.",0]],"e":"Jurisprudence constante du Conseil constitutionnel ; art. 6 DDHC. La France n'a pas ratifié le protocole n° 12.","r":["DDHC, art. 6"],"id":"b3cf0891"},{"c":"l8","q":"Quelle décision consacre la liberté d'entreprendre et la pleine valeur du droit de propriété ?","o":[["La décision Nationalisations du 16 janvier 1982.",1],["La décision Liberté d'association de 1971.",0],["La décision IVG de 1975.",0],["La décision Bioéthique de 1994.",0],["La décision Fraternité de 2018.",0]],"e":"Cons. const., 16 janv. 1982, n° 81-132 DC.","r":["81-132 DC"],"id":"832ef4fb"},{"c":"l8","q":"Quels droits figurent au Préambule de 1946 ?","o":[["Le droit de grève, dans le cadre des lois qui le réglementent.",1],["La liberté syndicale.",1],["La protection de la santé.",1],["Le droit au respect de la vie privée.",0],["La liberté d'entreprendre.",0]],"e":"Préambule de 1946, al. 6, 7 et 11.","r":["Préambule 1946"],"id":"2a3ec6ae"},{"c":"l8","q":"Sur la protection de l'environnement, quelles propositions sont exactes ?","o":[["La Charte de l'environnement a valeur constitutionnelle.",1],["Le Conseil d'État l'a affirmé dans l'arrêt Commune d'Annecy de 2008.",1],["Le Conseil constitutionnel a reconnu un objectif de valeur constitutionnelle de protection de l'environnement en 2020.",1],["Le contentieux climatique est irrecevable devant le Conseil d'État.",0],["La Charte n'a qu'une valeur législative.",0]],"e":"CE, Ass., 3 oct. 2008, n° 297931 ; Cons. const., 31 janv. 2020, n° 2019-823 QPC ; CE, 19 nov. 2020, Grande Synthe.","r":["CE, Commune d'Annecy","2019-823 QPC"],"id":"d272b49b"},{"c":"l8","q":"Quel statut a la possibilité de disposer d'un logement décent ?","o":[["Un objectif de valeur constitutionnelle.",1],["Un droit fondamental absolu et directement exigible devant tout juge.",0],["Un principe fondamental reconnu par les lois de la République.",0],["Une simple recommandation.",0],["Un droit garanti par l'article 3 de la Convention.",0]],"e":"Cons. const., 19 janv. 1995, n° 94-359 DC.","r":["94-359 DC"],"id":"637c3b32"},{"c":"p1","q":"Sur la composition des formations du conseil de prud'hommes, quelles propositions sont exactes ?","o":[["Le bureau de jugement comprend deux conseillers employeurs et deux conseillers salariés.",1],["Le bureau de conciliation et d'orientation comprend un conseiller de chaque collège.",1],["La formation de référé est commune à toutes les sections.",1],["Le bureau de jugement est présidé par un magistrat professionnel.",0],["La formation restreinte comprend trois conseillers.",0]],"e":"Art. L. 1423-1, L. 1423-12 et L. 1423-13 C. trav.","r":["C. trav., art. L. 1423-1, L. 1423-12, L. 1423-13"],"id":"5230efe4"},{"c":"p1","q":"Qui est le juge départiteur ?","o":[["Un juge du tribunal judiciaire dans le ressort duquel siège le conseil.",1],["Il est désigné chaque année par le président du tribunal judiciaire.",1],["Il préside la formation en cas de partage des voix.",1],["Un conseiller prud'homme désigné par le sort.",0],["Un conseiller de la cour d'appel désigné par le premier président.",0]],"e":"Art. L. 1454-2 C. trav.","r":["C. trav., art. L. 1454-2"],"id":"cd1ab2d7"},{"c":"p1","q":"Sur les conseillers prud'hommes, quelles propositions sont exactes ?","o":[["Ils sont nommés tous les quatre ans.",1],["Ils doivent être âgés de vingt et un ans au moins.",1],["Le conseiller qui ne suit pas la formation initiale dans le délai fixé est réputé démissionnaire.",1],["Ils sont élus au suffrage universel direct par les salariés.",0],["Ils ne sont pas tenus au secret des délibérations.",0]],"e":"Art. L. 1441-1, L. 1441-7, L. 1442-1 et L. 1421-2 C. trav.","r":["C. trav., art. L. 1441-1, L. 1441-7, L. 1442-1"],"id":"f755672c"},{"c":"p1","q":"Comment sont tranchées les difficultés de répartition d'une affaire entre sections ?","o":[["Par une ordonnance du président du conseil, après avis du vice président.",1],["L'ordonnance est une mesure d'administration judiciaire insusceptible de recours.",1],["La contestation est formée devant le bureau de conciliation et d'orientation.",1],["Par un jugement susceptible d'appel dans les quinze jours.",0],["Par le juge départiteur.",0]],"e":"Art. R. 1423-7 C. trav.","r":["C. trav., art. R. 1423-7"],"id":"2b5d8784"},{"c":"p2","q":"Sur la compétence d'attribution du conseil de prud'hommes, quelles propositions sont exactes ?","o":[["Elle est exclusive, quel que soit le montant de la demande.",1],["Toute convention contraire est réputée non écrite.",1],["Les litiges relatifs aux accidents du travail relèvent du pôle social du tribunal judiciaire.",1],["Le contentieux des élections professionnelles relève du conseil.",0],["Le conseil ne peut statuer au delà de 10 000 euros.",0]],"e":"Art. L. 1411-4 C. trav.","r":["C. trav., art. L. 1411-4"],"id":"9abffb7d"},{"c":"p2","q":"Quel juge connaît du litige relatif au refus d'homologation d'une rupture conventionnelle ?","o":[["Le conseil de prud'hommes, dans les douze mois de la date d'homologation.",1],["Le tribunal administratif.",0],["Le tribunal judiciaire.",0],["Le juge des référés administratif.",0],["L'inspection du travail sur recours gracieux uniquement.",0]],"e":"Art. L. 1237-14 C. trav. : tout litige concernant la convention, l'homologation ou le refus d'homologation relève du conseil de prud'hommes.","r":["C. trav., art. L. 1237-14"],"id":"31b5734b"},{"c":"p2","q":"Quels conseils le salarié peut il saisir ?","o":[["Celui du lieu de l'établissement où le travail est accompli.",1],["Celui du lieu où l'engagement a été contracté.",1],["Celui du lieu où l'employeur est établi.",1],["Celui de son domicile, même s'il travaille dans un établissement fixe.",0],["Celui désigné par une clause du contrat de travail.",0]],"e":"Art. R. 1412-1 C. trav. Le domicile n'est retenu que pour le travail à domicile ou hors établissement.","r":["C. trav., art. R. 1412-1"],"id":"a90701dd"},{"c":"p2","q":"Un salarié invoque l'encombrement du conseil territorialement compétent pour en saisir un autre. Que décide la Cour de cassation ?","o":[["Les parties ne peuvent écarter les règles de compétence territoriale prud'homales, d'ordre public.",1],["Le droit au délai raisonnable permet de saisir le conseil le moins encombré.",0],["Le salarié peut saisir le conseil de son choix.",0],["L'employeur peut accepter la compétence d'un autre conseil par avenant.",0],["Le juge départiteur choisit le conseil compétent.",0]],"e":"Cass. 2e civ., 3 oct. 2024, n° 22-14.853.","r":["Cass. 2e civ., 3 oct. 2024"],"id":"e417e39c"},{"c":"p3","q":"Sur la requête introductive, quelles propositions sont exactes ?","o":[["Elle comporte les mentions prescrites à peine de nullité par l'article 57 du code de procédure civile.",1],["Elle contient un exposé sommaire des motifs et chacun des chefs de demande.",1],["La saisine du conseil, même incompétent, interrompt la prescription.",1],["Elle doit être signifiée par commissaire de justice.",0],["Elle ne peut être adressée par voie postale.",0]],"e":"Art. R. 1452-1 et R. 1452-2 C. trav.","r":["C. trav., art. R. 1452-1, R. 1452-2"],"id":"fb8bd49f"},{"c":"p3","q":"Pour une instance introduite le 15 octobre 2026, que doit joindre le salarié à sa requête ?","o":[["Le bordereau des pièces.",1],["Son dernier bulletin de salaire ou toute pièce permettant d'identifier l'activité de l'employeur.",1],["L'intégralité des pièces invoquées.",0],["Une attestation de tentative de médiation.",0],["Un certificat de l'inspection du travail.",0]],"e":"Décret n° 2026-683, art. 10, applicable aux instances introduites à compter du 1er octobre 2026 (art. R. 1452-2 C. trav.).","r":["Décret n° 2026-683"],"id":"06d1d3c6"},{"c":"p3","q":"Sur la contribution pour l'aide juridique, quelles propositions sont exactes ?","o":[["Elle s'élève à 50 euros.",1],["Elle s'applique aux instances introduites depuis le 1er mars 2026 devant le conseil de prud'hommes.",1],["Les bénéficiaires de l'aide juridictionnelle en sont exonérés.",1],["Elle est due par le défendeur.",0],["Elle s'élève à 225 euros.",0]],"e":"Art. 1635 bis Q CGI, issu de la loi de finances pour 2026.","r":["CGI, art. 1635 bis Q"],"id":"4595ea89"},{"c":"p3","q":"Quels délais de prescription sont exacts ?","o":[["Deux ans pour une action portant sur l'exécution du contrat.",1],["Douze mois pour une action portant sur la rupture, à compter de sa notification.",1],["Trois ans pour l'action en paiement du salaire.",1],["Cinq ans pour l'action en réparation d'une discrimination, à compter de sa révélation.",1],["Trente ans pour l'action en paiement d'heures supplémentaires.",0]],"e":"Art. L. 1471-1, L. 3245-1 et L. 1134-5 C. trav.","r":["C. trav., art. L. 1471-1, L. 3245-1, L. 1134-5"],"id":"21065d98"},{"c":"p3","q":"Qu'est devenue la règle de l'unicité de l'instance ?","o":[["Elle a été supprimée pour les instances introduites à compter du 1er août 2016.",1],["Elle est remplacée par l'autorité de la chose jugée de droit commun et la concentration des moyens.",1],["Elle impose toujours de présenter toutes les demandes dans une seule instance.",0],["Elle a été étendue à l'appel.",0],["Elle a été consacrée par le décret n° 2026-683.",0]],"e":"Décret n° 2016-660 du 20 mai 2016 ; Ass. plén., 7 juill. 2006, Cesareo.","r":["Décret n° 2016-660"],"id":"5441fb72"},{"c":"p4","q":"Qui peut représenter une partie devant le conseil de prud'hommes ?","o":[["Un avocat.",1],["Un défenseur syndical.",1],["Le conjoint, le partenaire de pacte civil de solidarité ou le concubin.",1],["Un salarié ou un employeur de la même branche d'activité.",1],["Un ami sans lien avec la branche, muni d'un simple mandat verbal.",0]],"e":"Art. R. 1453-2 C. trav. ; le représentant non avocat justifie d'un pouvoir spécial.","r":["C. trav., art. R. 1453-2"],"id":"e16c9895"},{"c":"p4","q":"Sur la représentation en appel en matière prud'homale, quelles propositions sont exactes ?","o":[["La procédure est avec représentation obligatoire.",1],["Le défenseur syndical peut représenter les parties.",1],["À défaut de défenseur syndical, les parties constituent avocat.",1],["Les parties peuvent comparaître seules.",0],["L'appel est porté devant la chambre commerciale de la cour d'appel.",0]],"e":"Art. R. 1461-1 et R. 1461-2 C. trav.","r":["C. trav., art. R. 1461-1, R. 1461-2"],"id":"e7a9006c"},{"c":"p5","q":"Dans quels cas l'affaire est elle portée directement devant le bureau de jugement, qui statue dans le mois ?","o":[["Requalification d'un contrat à durée déterminée en contrat à durée indéterminée.",1],["Prise d'acte de la rupture par le salarié.",1],["Requalification d'une convention de stage en contrat de travail.",1],["Contestation d'un licenciement pour motif personnel.",0],["Demande de rappel de salaire.",0]],"e":"Art. L. 1245-2, L. 1451-1 et L. 1454-5 C. trav.","r":["C. trav., art. L. 1245-2, L. 1451-1, L. 1454-5"],"id":"9a7c7ee8"},{"c":"p5","q":"Quelles mesures le bureau de conciliation et d'orientation peut il ordonner, même si le défendeur ne comparaît pas ?","o":[["La remise sous astreinte d'un certificat de travail.",1],["Une provision sur salaires, si l'obligation n'est pas sérieusement contestable.",1],["Une provision sur l'indemnité de préavis.",1],["Des dommages et intérêts pour licenciement sans cause réelle et sérieuse.",0],["Une provision totale de douze mois de salaire.",0]],"e":"Art. R. 1454-14 et R. 1454-15 C. trav. : provisions plafonnées à six mois de salaire.","r":["C. trav., art. R. 1454-14, R. 1454-15"],"id":"c1ab9f8c"},{"c":"p5","q":"Quel est le régime des décisions provisoires du bureau de conciliation et d'orientation ?","o":[["Elles n'ont pas autorité de la chose jugée au principal.",1],["Elles sont exécutoires par provision.",1],["Elles ne peuvent être frappées d'appel qu'avec le jugement sur le fond.",1],["Elles sont susceptibles d'opposition.",0],["Elles sont susceptibles d'appel immédiat dans les quinze jours.",0]],"e":"Art. R. 1454-16 C. trav.","r":["C. trav., art. R. 1454-16"],"id":"fdf2bd33"},{"c":"p5","q":"Le demandeur ne se présente pas à la séance de conciliation, sans motif légitime. Que peut faire le bureau ?","o":[["Déclarer la requête caduque si le défendeur ne sollicite pas un jugement sur le fond.",1],["Juger l'affaire en l'état des pièces contradictoirement communiquées.",1],["Renvoyer l'affaire à une audience ultérieure du bureau de jugement.",1],["Condamner le demandeur à une amende civile automatique.",0],["Radier définitivement l'action.",0]],"e":"Art. R. 1454-12 et L. 1454-1-3 C. trav. ; la caducité peut être rapportée dans les quinze jours (art. 468 CPC).","r":["C. trav., art. R. 1454-12, L. 1454-1-3"],"id":"f753df0d"},{"c":"p5","q":"Sur l'orientation de l'affaire après échec de la conciliation, quelles propositions sont exactes ?","o":[["La formation restreinte peut être saisie, avec l'accord des parties, d'un litige de licenciement ou de résiliation judiciaire.",1],["La formation restreinte statue dans les trois mois.",1],["Le renvoi direct devant le bureau de jugement présidé par le juge départiteur est possible.",1],["L'orientation est une décision susceptible d'appel.",0],["La formation restreinte peut être imposée sans l'accord des parties.",0]],"e":"Art. L. 1454-1-1 C. trav. : mesure d'administration judiciaire.","r":["C. trav., art. L. 1454-1-1"],"id":"f8b3b386"},{"c":"p5","q":"Quelle indemnité les parties peuvent elles convenir lors de la conciliation en matière de licenciement ?","o":[["Une indemnité forfaitaire fixée par un barème selon l'ancienneté.",1],["Le procès verbal vaut renonciation à toute réclamation relative à la rupture.",1],["Elle s'ajoute aux indemnités légales, conventionnelles ou contractuelles.",1],["Elle est fixée librement par le juge départiteur.",0],["Elle exclut tout procès verbal.",0]],"e":"Art. L. 1235-1 et D. 1235-21 C. trav.","r":["C. trav., art. L. 1235-1, D. 1235-21"],"id":"036fd1a1"},{"c":"p6","q":"Sur la preuve en matière prud'homale, quelles propositions sont exactes ?","o":[["En matière de discrimination, le salarié présente des éléments de fait laissant supposer son existence.",1],["En matière d'heures de travail, la preuve est partagée entre les parties.",1],["Une preuve déloyale peut être admise si elle est indispensable et proportionnée.",1],["Le salarié doit toujours prouver seul ses heures supplémentaires.",0],["L'employeur n'a jamais à justifier ses décisions.",0]],"e":"Art. L. 1134-1, L. 1154-1 et L. 3171-4 C. trav. ; Ass. plén., 22 déc. 2023.","r":["C. trav., art. L. 1134-1, L. 3171-4"],"id":"5d83771d"},{"c":"p6","q":"Sur le départage, quelles propositions sont exactes ?","o":[["L'audience de départage est tenue dans le mois du renvoi devant le bureau de jugement.",1],["En référé, elle est tenue au plus tard dans les quinze jours.",1],["Si la formation n'est pas complète, le juge départiteur statue seul après avis des conseillers présents.",1],["Le juge départiteur ne peut jamais statuer seul.",0],["Le partage entraîne le renvoi devant la cour d'appel.",0]],"e":"Art. R. 1454-29 et R. 1454-31 C. trav.","r":["C. trav., art. R. 1454-29, R. 1454-31"],"id":"81834e04"},{"c":"p6","q":"Quels jugements prud'homaux sont de droit exécutoires à titre provisoire ?","o":[["Celui qui ordonne la remise d'un certificat de travail ou de bulletins de paie.",1],["Celui qui ordonne le paiement de salaires, dans la limite de neuf mois de salaire.",1],["Celui qui n'est susceptible d'appel que par suite d'une demande reconventionnelle.",1],["Tout jugement de première instance, comme en droit commun.",0],["Celui qui alloue des dommages et intérêts pour licenciement abusif, sans limite.",0]],"e":"Art. R. 1454-28 C. trav. : le principe est l'absence d'exécution provisoire de droit, sauf exceptions.","r":["C. trav., art. R. 1454-28"],"id":"47691f45"},{"c":"p6","q":"Quand le conseil de prud'hommes statue t il en dernier ressort ?","o":[["Lorsque la valeur totale des prétentions d'aucune des parties ne dépasse 5 000 euros.",1],["Lorsque la demande tend seulement à la remise de documents que l'employeur doit délivrer.",1],["Lorsque la demande excède 10 000 euros.",0],["Toujours en matière de licenciement.",0],["Lorsque le juge départiteur préside.",0]],"e":"Art. R. 1462-1 et D. 1462-3 C. trav.","r":["C. trav., art. R. 1462-1, D. 1462-3"],"id":"3a2c75ce"},{"c":"p6","q":"La procédure d'admission rapide de l'article 472, alinéa 3, du code de procédure civile s'applique t elle devant le conseil de prud'hommes ?","o":[["Non, les juridictions statuant en matière prud'homale en sont exclues.",1],["Oui, pour toutes les instances introduites depuis le 1er octobre 2026.",0],["Oui, mais seulement devant la formation restreinte.",0],["Oui, en référé uniquement.",0],["Seulement en appel.",0]],"e":"Circulaire du 29 juillet 2026 sur le décret n° 2026-683.","r":["Décret n° 2026-683 ; circulaire du 29 juill. 2026"],"id":"12a9486c"},{"c":"p7","q":"Sur le référé prud'homal, quelles propositions sont exactes ?","o":[["La formation peut faire cesser un trouble manifestement illicite, même en présence d'une contestation sérieuse.",1],["Elle peut accorder une provision si l'obligation n'est pas sérieusement contestable.",1],["Le délai d'appel est de quinze jours.",1],["La conciliation préalable est obligatoire.",0],["L'ordonnance a autorité de la chose jugée au principal.",0]],"e":"Art. R. 1455-5 à R. 1455-11 C. trav.","r":["C. trav., art. R. 1455-5 à R. 1455-11"],"id":"7b3ff882"},{"c":"p7","q":"À quelles conditions la formation de référé peut elle renvoyer l'affaire au bureau de jugement ?","o":[["La demande excède ses pouvoirs et présente une particulière urgence.",1],["L'accord de toutes les parties est nécessaire.",1],["Une tentative de conciliation en audience non publique doit avoir eu lieu.",1],["Le renvoi est automatique en cas de contestation sérieuse.",0],["Le juge départiteur doit l'autoriser.",0]],"e":"Art. R. 1455-8 C. trav.","r":["C. trav., art. R. 1455-8"],"id":"24df64ee"},{"c":"p7","q":"Comment contester l'avis d'inaptitude du médecin du travail ?","o":[["Devant le conseil de prud'hommes selon la procédure accélérée au fond.",1],["Dans les quinze jours de la notification de l'avis.",1],["Le médecin du travail n'est pas partie au litige.",1],["Devant le tribunal administratif dans les deux mois.",0],["Par un recours hiérarchique à l'inspecteur du travail.",0]],"e":"Art. L. 4624-7 et R. 4624-45 C. trav.","r":["C. trav., art. L. 4624-7, R. 4624-45"],"id":"7e1ee25a"},{"c":"p8","q":"Sur les voies de recours en matière prud'homale, quelles propositions sont exactes ?","o":[["Le délai d'appel d'un jugement est d'un mois.",1],["L'appel est porté devant la chambre sociale de la cour d'appel.",1],["Le pourvoi est formé dans les deux mois de la notification.",1],["L'opposition est la voie de recours de principe.",0],["L'appel d'une ordonnance de référé est d'un mois.",0]],"e":"Art. R. 1461-1, R. 1461-2, R. 1455-11 C. trav. ; art. 612 CPC.","r":["C. trav., art. R. 1461-1, R. 1461-2"],"id":"c4f26692"},{"c":"p8","q":"Le conseil se déclare incompétent au profit du tribunal judiciaire. Comment contester cette décision ?","o":[["Par l'appel des articles 83 et suivants du code de procédure civile.",1],["Dans un délai de quinze jours à compter de la notification.",1],["Par contredit.",0],["Par opposition.",0],["Par pourvoi immédiat.",0]],"e":"Art. 83 et 84 CPC ; le contredit a été supprimé en 2017.","r":["CPC, art. 83 et 84"],"id":"a0c95080"},{"c":"p4","q":"Sur le pouvoir du représentant devant le conseil de prud'hommes, quelles propositions sont exactes ?","o":[["Le représentant qui n'est pas avocat doit justifier d'un pouvoir spécial.",1],["Devant le bureau de conciliation et d'orientation, le pouvoir doit permettre au mandataire de concilier.",1],["L'avocat n'a pas à justifier d'un pouvoir spécial.",1],["Un pouvoir général donné pour toutes les affaires de l'entreprise suffit pour tout représentant.",0],["Le défenseur syndical ne peut pas représenter une partie.",0]],"e":"Art. R. 1453-2 C. trav.","r":["C. trav., art. R. 1453-2"],"id":"365bb678"},{"c":"p4","q":"Quelle est la règle de principe devant le conseil de prud'hommes ?","o":[["Les parties se défendent elles mêmes.",1],["Elles ont la faculté de se faire assister ou représenter.",1],["La constitution d'avocat est obligatoire.",0],["Seul un avocat peut représenter l'employeur.",0],["La représentation par un défenseur syndical suppose l'autorisation du président.",0]],"e":"Art. R. 1453-1 C. trav.","r":["C. trav., art. R. 1453-1"],"id":"568d2eef"},{"c":"p4","q":"Où le défenseur syndical peut il exercer ses fonctions ?","o":[["Devant les conseils de prud'hommes.",1],["Devant les cours d'appel en matière prud'homale.",1],["Dans le périmètre d'une région.",1],["Devant la Cour de cassation, en représentation obligatoire.",0],["Devant toutes les juridictions de l'ordre judiciaire.",0]],"e":"Art. L. 1453-4 C. trav.","r":["C. trav., art. L. 1453-4"],"id":"1d54c848"},{"c":"p6","q":"Sur l'oralité de la procédure prud'homale, quelles propositions sont exactes ?","o":[["La procédure prud'homale est orale.",1],["Les parties peuvent se référer à leurs écritures.",1],["Lorsque toutes les parties sont représentées par avocat et concluent par écrit, le juge ne statue que sur les prétentions énoncées au dispositif.",1],["La procédure prud'homale est exclusivement écrite.",0],["Les conclusions écrites lient toujours le juge, même non soutenues.",0]],"e":"Art. R. 1453-3 à R. 1453-5 C. trav.","r":["C. trav., art. R. 1453-3, R. 1453-4, R. 1453-5"],"id":"b604bb92"},{"c":"p6","q":"Sur l'indemnité pour licenciement sans cause réelle et sérieuse, quelles propositions sont exactes ?","o":[["Le juge peut proposer la réintégration du salarié.",1],["En cas de refus, l'indemnité est comprise entre des montants minimaux et maximaux fixés par un barème.",1],["La Cour de cassation a jugé le barème compatible avec la convention n° 158 de l'OIT.",1],["Le juge peut écarter le barème au cas par cas au titre de la réparation adéquate.",0],["L'indemnité est librement fixée sans plancher ni plafond.",0]],"e":"Art. L. 1235-3 C. trav. ; Cass. soc., 11 mai 2022, n° 21-14.490.","r":["C. trav., art. L. 1235-3","Cass. soc., 11 mai 2022"],"id":"15b05180"},{"c":"p5","q":"Sur le conseiller rapporteur, quelles propositions sont exactes ?","o":[["Il peut faire partie de la formation de jugement.",1],["Lorsque deux rapporteurs sont désignés, l'un est employeur, l'autre salarié.",1],["Il peut ordonner toutes mesures d'instruction.",1],["Il est un magistrat professionnel du tribunal judiciaire.",0],["Ses décisions ont autorité de la chose jugée au principal.",0]],"e":"Art. R. 1454-4 et R. 1454-6 C. trav.","r":["C. trav., art. R. 1454-4, R. 1454-6"],"id":"43c75b39"},{"c":"p5","q":"Un salarié justifie de quatre ans d'ancienneté. Quel est le montant de l'indemnité forfaitaire de conciliation prévue par le barème ?","o":[["Six mois de salaire.",1],["Quatre mois de salaire.",0],["Trois mois de salaire.",0],["Dix mois de salaire.",0],["Deux mois de salaire.",0]],"e":"Art. D. 1235-21 C. trav. : trois mois pour un an d'ancienneté, plus un mois par année supplémentaire jusqu'à huit ans.","r":["C. trav., art. D. 1235-21"],"id":"bc9fb09d"},{"c":"p7","q":"Sur l'appel des ordonnances de référé prud'homales, quelles propositions sont exactes ?","o":[["Le délai d'appel est de quinze jours.",1],["L'ordonnance rendue en dernier ressort en raison du montant ou de l'objet de la demande n'est pas susceptible d'appel.",1],["L'ordonnance rendue en dernier ressort par défaut est susceptible d'opposition.",1],["Le délai d'appel est d'un mois.",0],["L'appel est porté devant le juge départiteur.",0]],"e":"Art. R. 1455-11 C. trav. ; art. 490 CPC, applicable par l'article R. 1455-10.","r":["C. trav., art. R. 1455-10, R. 1455-11","CPC, art. 490"],"id":"b7fd80b9"},{"c":"p7","q":"Comment la demande en référé prud'homal est elle formée ?","o":[["Par acte de commissaire de justice.",1],["Par requête, dans les conditions de l'article R. 1452-1.",1],["En cas d'assignation, une copie est remise au greffe au plus tard la veille de l'audience.",1],["Exclusivement par lettre recommandée adressée à l'employeur.",0],["Par déclaration orale au bureau de jugement.",0]],"e":"Art. R. 1455-9 C. trav.","r":["C. trav., art. R. 1455-9"],"id":"619d745b"},{"c":"p8","q":"Un jugement prud'homal est notifié par le greffe le 20 octobre 2026. Jusqu'à quand l'appel peut il être formé ?","o":[["Jusqu'au 20 novembre 2026 à vingt quatre heures.",1],["Jusqu'au 4 novembre 2026.",0],["Jusqu'au 20 décembre 2026.",0],["Jusqu'au 19 novembre 2026.",0],["Jusqu'au 20 janvier 2027.",0]],"e":"Art. R. 1461-1 C. trav. ; art. 641 et 642 CPC. Le 20 novembre 2026 est un vendredi.","r":["C. trav., art. R. 1461-1","CPC, art. 641, 642"],"id":"ae62d77f"},{"c":"p8","q":"Le jugement prud'homal alloue 38 000 euros de dommages et intérêts pour licenciement sans cause réelle et sérieuse, sans ordonner l'exécution provisoire. L'employeur fait appel. Quelles propositions sont exactes ?","o":[["La condamnation n'est pas exécutoire de droit à titre provisoire.",1],["L'appel en suspend l'exécution.",1],["La radiation de l'article 524 du code de procédure civile ne peut être demandée pour cette condamnation.",1],["La condamnation est exécutoire de droit, comme en droit commun.",0],["La condamnation est exécutoire dans la limite de neuf mois de salaire.",0]],"e":"Art. R. 1454-28 C. trav. : les dommages et intérêts ne figurent pas parmi les sommes de l'article R. 1454-14 ; art. 524 CPC.","r":["C. trav., art. R. 1454-28","CPC, art. 524"],"id":"c78dc150"},{"c":"p8","q":"Qui peut représenter les parties devant la chambre sociale de la cour d'appel ?","o":[["Un avocat.",1],["Un défenseur syndical.",1],["La partie elle même, sans représentant.",0],["Un salarié de la même branche d'activité.",0],["Le conjoint de la partie.",0]],"e":"Art. R. 1461-1 et R. 1461-2 C. trav. : représentation obligatoire.","r":["C. trav., art. R. 1461-1, R. 1461-2"],"id":"69668e1d"},{"c":"p9","q":"Quelles différences opposent la procédure prud'homale à la procédure ordinaire devant le tribunal judiciaire ?","o":[["La saisine se fait en principe par requête et non par assignation.",1],["La représentation n'est pas obligatoire en première instance.",1],["Les jugements ne sont pas, en principe, exécutoires de droit à titre provisoire.",1],["Le délai d'appel est de deux mois.",0],["Le taux du dernier ressort est de 10 000 euros.",0]],"e":"Art. R. 1452-1, R. 1453-1, R. 1454-28, R. 1461-1, D. 1462-3 C. trav. ; art. 514, 750 et 760 CPC.","r":["C. trav., art. R. 1452-1, R. 1454-28","CPC, art. 514, 750, 760"],"id":"030091f8"},{"c":"p9","q":"Quels points sont communs à la procédure prud'homale et au droit commun ?","o":[["Le délai d'appel d'un mois.",1],["Le taux du dernier ressort de 5 000 euros.",1],["Le livre premier du code de procédure civile s'applique, sauf dispositions contraires.",1],["La présence d'un juge départiteur.",0],["La conciliation obligatoire devant une formation distincte.",0]],"e":"Art. R. 1451-1, R. 1461-1 et D. 1462-3 C. trav. ; art. 538 CPC.","r":["C. trav., art. R. 1451-1"],"id":"bf701a37"},{"c":"k1","q":"Quelles directions figurent dans l'organigramme du ministère de la Justice de mars 2026 ?","o":[["La direction des services judiciaires.",1],["La direction des affaires civiles et du Sceau.",1],["La direction générale de l'administration pénitentiaire.",1],["La direction générale des collectivités locales.",0],["La direction générale de la police nationale.",0]],"e":"Organigramme du ministère, mars 2026 : DSJ, DACS, DACG, DGAP, DPJJ, DNUM, autour du secrétariat général.","r":["Ministère de la Justice, organigramme, mars 2026"],"id":"e987d2ed"},{"c":"k1","q":"Depuis quand l'administration pénitentiaire est elle une direction générale ?","o":[["Depuis le 1er février 2026.",1],["Depuis le 1er janvier 2020.",0],["Depuis 1958.",0],["Depuis le 1er octobre 2026.",0],["Elle ne l'est pas.",0]],"e":"Décret n° 2025-1275 du 22 décembre 2025 ; DGAP effective au 1er février 2026.","r":["Décret n° 2025-1275"],"id":"e82e6653"},{"c":"k1","q":"Où se situent les écoles du ministère de la Justice ?","o":[["L'École nationale des greffes à Dijon.",1],["L'École nationale d'administration pénitentiaire à Agen.",1],["L'École nationale de la magistrature à Bordeaux et à Paris.",1],["L'École nationale des greffes à Bordeaux.",0],["L'École nationale de protection judiciaire de la jeunesse à Dijon.",0]],"e":"Organigramme du ministère, mars 2026 ; l'ENPJJ est à Roubaix.","r":["Ministère de la Justice, organigramme, mars 2026"],"id":"86f1b17b"},{"c":"k1","q":"Pourquoi le ministère de la Justice est il appelé la « Chancellerie » ou la « place Vendôme » ?","o":[["Il siège place Vendôme, à Paris.",1],["Le ministre porte le titre de garde des Sceaux.",1],["Il siège au Palais de justice de l'île de la Cité.",0],["Le ministre est élu par les magistrats.",0],["Le ministre préside la Cour de cassation.",0]],"e":"Le garde des Sceaux conserve les sceaux de la République ; le ministère est installé place Vendôme.","r":["Ministère de la Justice"],"id":"cdaaca30"},{"c":"k2","q":"Selon l'article R. 123-13 du code de l'organisation judiciaire, que font les greffiers ?","o":[["Ils assistent les magistrats à l'audience.",1],["Ils dressent les actes de greffe, notes et procès verbaux.",1],["Ils interviennent dans les cas prévus par les lois et règlements.",1],["Ils rendent les décisions en cas d'absence du juge.",0],["Ils représentent les parties à l'audience.",0]],"e":"Art. R. 123-13 COJ.","r":["COJ, art. R. 123-13"],"id":"b7e1a921"},{"c":"k2","q":"Sur le corps des cadres greffiers, quelles propositions sont exactes ?","o":[["Il relève de la catégorie A.",1],["Il a été créé au 1er janvier 2025.",1],["Il résulte du décret n° 2024-1089 du 3 décembre 2024.",1],["Il a remplacé les magistrats de l'ordre judiciaire.",0],["Il est recruté exclusivement par concours externe depuis 2025.",0]],"e":"Décret n° 2024-1089 ; sélections professionnelles en 2025 et 2026, concours à partir de 2027.","r":["Décret n° 2024-1089"],"id":"83dd2221"},{"c":"k2","q":"Sur les attachés de justice, quelles propositions sont exactes ?","o":[["Ils assistent les magistrats du siège et du parquet.",1],["Ils prêtent serment.",1],["Ils sont tenus au secret professionnel.",1],["Ils peuvent présider une audience.",0],["Ils sont nécessairement fonctionnaires.",0]],"e":"Art. L. 123-4 COJ : fonctionnaires ou agents contractuels.","r":["COJ, art. L. 123-4"],"id":"86a27f4a"},{"c":"k2","q":"Quels objectifs de recrutement fixe la loi d'orientation et de programmation de la justice 2023-2027 ?","o":[["1 500 magistrats.",1],["1 800 greffiers.",1],["1 100 attachés de justice.",1],["10 000 magistrats.",0],["500 greffiers.",0]],"e":"Loi n° 2023-1059 du 20 novembre 2023 ; communiqué du ministère du 12 janvier 2026.","r":["Loi n° 2023-1059"],"id":"4a582aab"},{"c":"k3","q":"Quand le tribunal judiciaire a t il remplacé les tribunaux d'instance et de grande instance ?","o":[["Le 1er janvier 2020.",1],["Le 1er janvier 2019.",0],["Le 1er septembre 2024.",0],["Le 1er octobre 2026.",0],["Le 1er janvier 2008.",0]],"e":"Loi n° 2019-222 du 23 mars 2019.","r":["Loi n° 2019-222"],"id":"0a7fef67"},{"c":"k3","q":"Sur les cours criminelles départementales, quelles propositions sont exactes ?","o":[["Elles sont généralisées depuis le 1er janvier 2023.",1],["Elles sont composées de cinq magistrats.",1],["Elles jugent les crimes punis de quinze ou vingt ans de réclusion commis par des majeurs, hors récidive.",1],["Elles comprennent un jury de six citoyens.",0],["Elles jugent les mineurs.",0]],"e":"Loi n° 2021-1729 du 22 décembre 2021.","r":["Loi n° 2021-1729"],"id":"1972d3a9"},{"c":"k3","q":"Quand le code de la justice pénale des mineurs est il entré en vigueur ?","o":[["Le 30 septembre 2021.",1],["Le 2 février 1945.",0],["Le 1er janvier 2020.",0],["Le 1er janvier 2023.",0],["Le 11 septembre 2019.",0]],"e":"Ordonnance n° 2019-950 du 11 septembre 2019 ; entrée en vigueur le 30 septembre 2021.","r":["Ordonnance n° 2019-950"],"id":"e70bd81b"},{"c":"k3","q":"Qui fut la première femme magistrate en France ?","o":[["Charlotte Béquignon-Lagarde, en 1946.",1],["Simone Rozès, en 1946.",0],["Jeanne Chauvin, en 1900.",0],["Élisabeth Guigou, en 1997.",0],["Olga Petit, en 1900.",0]],"e":"Loi du 11 avril 1946 ; installation à la Cour de cassation en 1946.","r":["Ministère de la Justice, « 1946 : la magistrature s'ouvre aux femmes »"],"id":"931b58fe"},{"c":"k4","q":"Sur l'épreuve orale du concours externe de greffier (session 2027), quelles propositions sont exactes ?","o":[["Elle dure vingt cinq minutes au plus.",1],["L'exposé initial dure cinq minutes au plus.",1],["Elle est affectée du coefficient 4.",1],["Elle comporte un programme limitatif de procédure pénale.",0],["Une note de 8 sur 20 est éliminatoire.",0]],"e":"Notice du concours G2027 : note inférieure à 5 éliminatoire.","r":["Notice du concours de greffier, session 2027"],"id":"56fcbae3"},{"c":"k9","q":"Que symbolise le chêne de Saint Louis ?","o":[["Une justice accessible, rendue directement par le souverain à ses sujets.",1],["L'image est rapportée par Joinville.",1],["Elle se situe dans le bois de Vincennes.",1],["Le chêne symbolise la fonction répressive de la justice.",0],["Saint Louis jugeait seul toutes les affaires du royaume.",0]],"e":"Récit de Joinville ; les historiens soulignent que le roi jugeait rarement lui même et confiait la justice à des légistes.","r":["Actu-Juridique, « Histoire du droit : la Sainte Chapelle »"],"id":"cf26f06d"},{"c":"k9","q":"Quelles significations des symboles de la justice sont exactes ?","o":[["Le bandeau exprime l'impartialité.",1],["La balance figure l'équité.",1],["Le glaive représente la fonction répressive.",1],["La main de justice exprime la clémence.",0],["Le marteau est utilisé par les juges français à l'audience.",0]],"e":"Ministère de la Justice, « Les symboles de la justice » : la main de justice est l'attribut du pouvoir royal ; le marteau est réservé aux commissaires priseurs.","r":["Ministère de la Justice, « Les symboles de la justice »"],"id":"1f499cc4"},{"c":"k9","q":"Quelle est la trajectoire de recrutement de la loi de programmation 2023-2027 ?","o":[["10 000 créations nettes d'emplois.",1],["Dont 1 500 magistrats.",1],["Dont 1 800 greffiers.",1],["Dont 5 000 greffiers.",0],["Elle a été abandonnée en 2025.",0]],"e":"Loi n° 2023-1059 ; rapport du Sénat sur le projet de loi de finances pour 2026.","r":["Loi n° 2023-1059","Sénat, rapport PLF 2026, mission Justice"],"id":"ec507d0e"},{"c":"k9","q":"Selon le ministère, où en était le recrutement des greffiers au 1er décembre 2025 ?","o":[["571 greffiers supplémentaires étaient arrivés en juridiction.",1],["833 greffiers stagiaires étaient en formation.",1],["Plus de la moitié de l'objectif était atteinte en comptant les stagiaires.",1],["L'objectif de 1 800 était entièrement atteint.",0],["Aucun greffier n'avait été recruté.",0]],"e":"Communiqué du ministère de la Justice du 12 janvier 2026.","r":["Ministère de la Justice, communiqué du 12 janvier 2026"],"id":"ef40c1b8"},{"c":"k9","q":"Pourquoi le Sénat relève t il des retards dans le recrutement des greffiers ?","o":[["L'objectif dépend largement de la requalification d'adjoints administratifs faisant fonction de greffier.",1],["Une partie du corps rejoint celui des cadres greffiers.",1],["Les départs en retraite accentuent la tension.",1],["Le concours de greffier a été supprimé.",0],["Les greffiers sont désormais recrutés par l'ENM.",0]],"e":"Sénat, avis sur le projet de loi de finances pour 2026, justice judiciaire.","r":["Sénat, avis PLF 2026, justice judiciaire"],"id":"a7af2872"},{"c":"k9","q":"Que prévoit le projet de loi de finances pour 2027 pour la justice ?","o":[["Des crédits de près de 11 milliards d'euros.",1],["334 emplois de greffiers.",1],["287 emplois de magistrats.",1],["Une baisse des crédits de 20 %.",0],["La suppression de la loi de programmation.",0]],"e":"Présentation du 1er octobre 2026 ; texte en discussion au Parlement.","r":["JSS, 1er octobre 2026"],"id":"bbb07f06"},{"c":"k9","q":"Sur la loi n° 2026-651 du 23 juillet 2026, dite loi « SURE », quelles propositions sont exactes ?","o":[["Le plaider coupable criminel en a été retiré avant l'adoption.",1],["Elle réduit le délai pour soulever les nullités de l'instruction.",1],["Le Conseil constitutionnel a censuré le recours à la généalogie génétique dans des bases privées étrangères.",1],["Elle supprime les cours d'assises.",0],["Elle a été déclarée entièrement conforme sans réserve.",0]],"e":"Loi n° 2026-651 ; décision n° 2026-909 DC du 23 juillet 2026.","r":["Loi n° 2026-651","Cons. const., n° 2026-909 DC"],"id":"332bb2ca"},{"c":"k5","q":"Sur l'abolition de la peine de mort, quelles propositions sont exactes ?","o":[["La loi d'abolition date du 9 octobre 1981.",1],["Robert Badinter prononce son discours le 17 septembre 1981.",1],["L'abolition est inscrite à l'article 66-1 de la Constitution depuis 2007.",1],["La dernière exécution a eu lieu en 1981.",0],["L'abolition résulte d'un référendum.",0]],"e":"Dernière exécution le 10 septembre 1977 ; loi constitutionnelle du 23 février 2007.","r":["Constitution, art. 66-1"],"id":"e8662eaa"},{"c":"k5","q":"Qui fut la première femme à prêter serment comme avocate ?","o":[["Olga Petit.",1],["Jeanne Chauvin.",0],["Gisèle Halimi.",0],["Simone Rozès.",0],["Dominique de La Garanderie.",0]],"e":"Loi du 1er décembre 1900 ; Jeanne Chauvin est la deuxième et plaide la première en janvier 1901.","r":["Loi du 1er décembre 1900"],"id":"4df82e63"},{"c":"k5","q":"Quelles « premières » sont exactes ?","o":[["Simone Rozès, première femme première présidente de la Cour de cassation, en 1984.",1],["Élisabeth Guigou, première femme garde des Sceaux, en 1997.",1],["Dominique de La Garanderie, première femme bâtonnier de Paris, élue en 1997.",1],["Charlotte Béquignon-Lagarde, première femme avocate, en 1900.",0],["Olga Petit, première femme magistrate, en 1946.",0]],"e":"Sources : ministère de la Justice, Ordre des avocats de Paris, Fondation Jean Jaurès.","r":["Ministère de la Justice","Ordre des avocats de Paris"],"id":"d10c95cd"},{"c":"k5","q":"Quand Robert Badinter est il entré au Panthéon ?","o":[["Le 9 octobre 2025.",1],["Le 9 octobre 1981.",0],["Le 17 septembre 2024.",0],["Le 23 février 2007.",0],["Il n'y est pas entré.",0]],"e":"Date choisie pour l'anniversaire de la loi d'abolition.","r":["Ministère de la Culture"],"id":"70cee8ca"},{"c":"k6","q":"Quels termes figurent dans le serment prêté par l'avocat (art. 3 de la loi de 1971) ?","o":[["Dignité.",1],["Conscience.",1],["Indépendance.",1],["Probité et humanité.",1],["Loyauté envers l'État.",0]],"e":"Art. 3 de la loi n° 71-1130 du 31 décembre 1971.","r":["Loi n° 71-1130, art. 3"],"id":"ac1ebd23"},{"c":"k6","q":"Sur le secret professionnel de l'avocat, quelles propositions sont exactes ?","o":[["Il s'applique en toutes matières, conseil comme défense.",1],["Il couvre les correspondances entre l'avocat et son client.",1],["Les correspondances entre confrères portant la mention « officielle » n'en relèvent pas.",1],["Il ne couvre que l'activité de défense pénale.",0],["Il ne couvre pas les notes d'entretien.",0]],"e":"Art. 66-5 de la loi du 31 décembre 1971.","r":["Loi n° 71-1130, art. 66-5"],"id":"9864923f"},{"c":"k6","q":"Quelles réformes ont façonné la profession d'avocat ?","o":[["La fusion avec les conseils juridiques par la loi du 31 décembre 1990.",1],["L'intégration des avoués près les cours d'appel au 1er janvier 2012.",1],["La loi du 31 décembre 1971.",1],["La fusion avec les notaires en 2016.",0],["La suppression des avocats au Conseil d'État et à la Cour de cassation.",0]],"e":"Loi n° 90-1259 ; loi n° 2011-94 du 25 janvier 2011.","r":["Loi n° 71-1130, art. 1er","Loi n° 2011-94"],"id":"839e7cc6"},{"c":"k6","q":"Sur l'organisation de la profession, quelles propositions sont exactes ?","o":[["Chaque barreau est administré par un conseil de l'ordre élu pour trois ans.",1],["Le Conseil national des barreaux représente la profession auprès des pouvoirs publics.",1],["Le conseil de l'ordre statue sur l'inscription au tableau.",1],["Le bâtonnier est nommé par le garde des Sceaux.",0],["Le Conseil national des barreaux est une juridiction.",0]],"e":"Art. 15, 17 et 21-1 de la loi du 31 décembre 1971.","r":["Loi n° 71-1130, art. 15, 17, 21-1"],"id":"3c350010"},{"c":"k7","q":"Quelle direction du ministère est chargée des professions du droit, dont la profession d'avocat ?","o":[["La direction des affaires civiles et du Sceau.",1],["La direction des affaires criminelles et des grâces.",0],["La direction des services judiciaires.",0],["La direction du numérique.",0],["L'inspection générale de la justice.",0]],"e":"La DACS est chargée du droit civil, de la procédure civile et des professions du droit.","r":["Ministère de la Justice"],"id":"857e371b"},{"c":"k7","q":"La contribution pour l'aide juridique relance le débat sur la gratuité de la justice. Quelles propositions sont exactes ?","o":[["Elle s'élève à 50 euros.",1],["Elle s'applique depuis le 1er mars 2026.",1],["Elle concerne le tribunal judiciaire et le conseil de prud'hommes.",1],["Elle est due par le défendeur.",0],["Elle bénéficie aux avocats personnellement.",0]],"e":"Art. 1635 bis Q CGI.","r":["CGI, art. 1635 bis Q"],"id":"36560444"},{"c":"k8","q":"Sur l'entretien du grand oral, quelles propositions sont exactes ?","o":[["Il dure trente minutes.",1],["Il peut porter sur la culture juridique générale.",1],["Il suit un exposé de quinze minutes.",1],["Il est interdit d'y aborder la déontologie de l'avocat.",0],["Il se déroule à huis clos.",0]],"e":"Arrêté du 17 octobre 2016 modifié, art. 7 : séance publique.","r":["Arrêté du 17 oct. 2016, art. 7"],"id":"986e0ce1"}],"fiches":[{"c":"pd","q":"Que pose l'article 1er du CPC ?","a":"Seules les parties introduisent l'instance, hors les cas où la loi en dispose autrement. Elles ont la liberté d'y mettre fin avant qu'elle ne s'éteigne par l'effet du jugement ou en vertu de la loi.","r":"CPC art. 1","id":"0a8c06fc"},{"c":"pd","q":"Comment est déterminé l'objet du litige ?","a":"Par les prétentions respectives des parties, fixées par l'acte introductif d'instance et par les conclusions en défense. Il peut être modifié par des demandes incidentes présentant un lien suffisant avec les prétentions originaires.","r":"CPC art. 4","id":"31405472"},{"c":"pd","q":"Quelle règle interdit au juge de statuer ultra ou infra petita ?","a":"Le juge doit se prononcer sur tout ce qui est demandé et seulement sur ce qui est demandé. Le vice se répare par la procédure des articles 463 et 464.","r":"CPC art. 5, 463, 464","id":"f6b8d468"},{"c":"pd","q":"Qui a la charge d'alléguer les faits ?","a":"Les parties : à l'appui de leurs prétentions, elles ont la charge d'alléguer les faits propres à les fonder.","r":"CPC art. 6","id":"8591c367"},{"c":"pd","q":"Que sont les faits adventices ?","a":"Les faits qui sont dans le débat mais que les parties n'ont pas spécialement invoqués au soutien de leurs prétentions. Le juge peut les prendre en considération ; il ne peut en revanche fonder sa décision sur des faits qui ne sont pas dans le débat.","r":"CPC art. 7","id":"ce4973df"},{"c":"pd","q":"Que prévoit l'article 12 quant à la qualification ?","a":"Le juge tranche le litige conformément aux règles de droit et doit donner ou restituer leur exacte qualification aux faits et actes litigieux. Les parties peuvent, par accord exprès et pour des droits disponibles, le lier par les qualifications et points de droit qu'elles retiennent.","r":"CPC art. 12","id":"cc99a797"},{"c":"pd","q":"Quelle est la portée de l'arrêt Dauvin, dit aussi Carteret (Ass. plén., 21 décembre 2007) ?","a":"Le juge n'est pas tenu, sauf règles particulières, de changer la dénomination ou le fondement juridique des demandes. La requalification est une faculté.","r":"Ass. plén. 21 déc. 2007, n° 06-11.343","id":"d4b745f3"},{"c":"pd","q":"Que pose l'article 14 ?","a":"Nulle partie ne peut être jugée sans avoir été entendue ou appelée.","r":"CPC art. 14","id":"7b4dfce8"},{"c":"pd","q":"Quelle obligation pèse sur le juge qui relève un moyen de droit d'office ?","a":"Il doit au préalable inviter les parties à présenter leurs observations.","r":"CPC art. 16 al. 3","id":"c3de09dc"},{"c":"pd","q":"Quel principe directeur le décret n° 2025-660 a t il consacré à l'article 21 ?","a":"Un principe directeur de coopération entre le juge et les parties, destiné à renforcer le recours aux modes amiables de règlement des différends.","r":"CPC art. 21","id":"ce6db68e"},{"c":"act","q":"Définition de l'action en justice ?","a":"Le droit, pour l'auteur d'une prétention, d'être entendu sur le fond de celle ci afin que le juge la dise bien ou mal fondée ; pour l'adversaire, le droit de discuter le bien fondé de cette prétention.","r":"CPC art. 30","id":"8da4a9cc"},{"c":"act","q":"Conditions générales du droit d'agir ?","a":"Un intérêt légitime au succès ou au rejet d'une prétention, sous réserve des cas où la loi attribue le droit d'agir aux seules personnes qu'elle qualifie (actions attitrées).","r":"CPC art. 31","id":"3def2c26"},{"c":"act","q":"Quelle sanction pour une action en justice dilatoire ou abusive ?","a":"Une amende civile d'un maximum de 10 000 euros, sans préjudice des dommages et intérêts qui seraient réclamés.","r":"CPC art. 32-1","id":"602f8a97"},{"c":"intro","q":"Quelles sont les demandes incidentes ?","a":"La demande reconventionnelle, la demande additionnelle et l'intervention. Elles ne sont recevables que si elles se rattachent aux prétentions originaires par un lien suffisant.","r":"CPC art. 63 et 70","id":"67d0d2e1"},{"c":"def","q":"Définition de la défense au fond ?","a":"Tout moyen qui tend à faire rejeter comme non justifiée, après examen au fond du droit, la prétention de l'adversaire. Elle peut être proposée en tout état de cause.","r":"CPC art. 71 et 72","id":"25762a65"},{"c":"def","q":"Définition de l'exception de procédure ?","a":"Tout moyen qui tend soit à faire déclarer la procédure irrégulière ou éteinte, soit à en suspendre le cours.","r":"CPC art. 73","id":"0bb3de54"},{"c":"def","q":"Moment pour soulever les exceptions de procédure ?","a":"Simultanément et avant toute défense au fond ou fin de non recevoir, même si les règles invoquées sont d'ordre public.","r":"CPC art. 74","id":"547122df"},{"c":"def","q":"Définition de la fin de non recevoir ?","a":"Tout moyen qui tend à faire déclarer l'adversaire irrecevable en sa demande, sans examen au fond, pour défaut de droit d'agir : défaut de qualité, défaut d'intérêt, prescription, délai préfix, chose jugée.","r":"CPC art. 122","id":"ea8a801e"},{"c":"def","q":"Régime des fins de non recevoir ?","a":"Proposables en tout état de cause (article 123), sans justification d'un grief (article 124). Relevé d'office obligatoire si elles sont d'ordre public, facultatif pour le défaut d'intérêt, de qualité et la chose jugée (article 125).","r":"CPC art. 123 à 125","id":"f5abe86d"},{"c":"def","q":"Le juge peut il relever d'office la prescription ?","a":"Non : les juges ne peuvent pas suppléer d'office le moyen résultant de la prescription.","r":"C. civ. art. 2247","id":"07d7e483"},{"c":"def","q":"Conditions de la nullité pour vice de forme ?","a":"Un texte la prévoyant, ou l'inobservation d'une formalité substantielle ou d'ordre public, et dans tous les cas la preuve d'un grief. Elle est couverte par une défense au fond ou une fin de non recevoir présentée sans la soulever.","r":"CPC art. 112 et 114","id":"36ecca95"},{"c":"def","q":"Quelles sont les irrégularités de fond ?","a":"Le défaut de capacité d'ester en justice ; le défaut de pouvoir d'une personne figurant au procès comme représentant d'une personne morale ou d'une personne atteinte d'une incapacité d'exercice ; le défaut de capacité ou de pouvoir d'une personne assurant la représentation d'une partie en justice. Liste limitative (Ch. mixte 7 juillet 2006).","r":"CPC art. 117","id":"a5ec82f3"},{"c":"def","q":"Régime des nullités pour irrégularité de fond ?","a":"Elles peuvent être proposées en tout état de cause et doivent être accueillies sans que celui qui les invoque ait à justifier d'un grief.","r":"CPC art. 118 et 119","id":"ceaf6770"},{"c":"comp","q":"Règle de principe de compétence territoriale ?","a":"La juridiction du lieu où demeure le défendeur ; s'il y a plusieurs défendeurs, le demandeur saisit à son choix celle du lieu où demeure l'un d'eux.","r":"CPC art. 42","id":"dff3bc3b"},{"c":"comp","q":"Options de compétence en matière contractuelle et délictuelle ?","a":"Contrat : lieu de la livraison effective de la chose ou de l'exécution de la prestation de service. Délit : lieu du fait dommageable ou celui dans le ressort duquel le dommage a été subi.","r":"CPC art. 46","id":"a4d4efe5"},{"c":"comp","q":"Validité d'une clause attributive de compétence territoriale ?","a":"Réputée non écrite, sauf si elle a été convenue entre personnes ayant toutes contracté en qualité de commerçant et spécifiée de façon très apparente.","r":"CPC art. 48","id":"ab68df37"},{"c":"comp","q":"Litispendance : quelle juridiction se dessaisit ?","a":"La juridiction saisie en second lieu, si l'une des parties le demande ; à défaut, elle peut le faire d'office.","r":"CPC art. 100","id":"2b715a9d"},{"c":"inst","q":"Délai et effet de la péremption ?","a":"Deux ans sans diligence d'aucune partie. Elle éteint l'instance mais non l'action.","r":"CPC art. 386 et 389","id":"3b0b17f2"},{"c":"inst","q":"Quand le désistement d'instance exige t il l'acceptation du défendeur ?","a":"Lorsque le défendeur a présenté une défense au fond ou une fin de non recevoir au moment où le demandeur se désiste. Le refus doit reposer sur un motif légitime.","r":"CPC art. 395 et 396","id":"c41f5133"},{"c":"jug","q":"À quelle partie du jugement s'attache l'autorité de la chose jugée ?","a":"Au dispositif : le jugement qui tranche tout ou partie du principal a, dès son prononcé, l'autorité de la chose jugée relativement à la contestation qu'il tranche.","r":"CPC art. 480","id":"eda4ec55"},{"c":"jug","q":"Conditions de l'autorité de la chose jugée ?","a":"Même chose demandée, même cause, mêmes parties, formée par elles et contre elles en la même qualité.","r":"C. civ. art. 1355","id":"9cf21269"},{"c":"jug","q":"Que décide l'arrêt Cesareo ?","a":"Il incombe au demandeur de présenter dès l'instance relative à la première demande l'ensemble des moyens qu'il estime de nature à fonder celle ci (concentration des moyens).","r":"Ass. plén. 7 juill. 2006, n° 04-10.672","id":"d3ee54ac"},{"c":"jug","q":"Principe de l'exécution provisoire ?","a":"Les décisions de première instance sont de droit exécutoires à titre provisoire, à moins que la loi ou la décision n'en dispose autrement. En appel, l'arrêt suppose un moyen sérieux et des conséquences manifestement excessives.","r":"CPC art. 514 et 514-3","id":"dadf4d9a"},{"c":"urg","q":"Conditions du référé de l'article 834 ?","a":"L'urgence, et des mesures qui ne se heurtent à aucune contestation sérieuse ou que justifie l'existence d'un différend.","r":"CPC art. 834","id":"c114eb82"},{"c":"urg","q":"Conditions du référé de l'article 835 ?","a":"Alinéa 1 : même en présence d'une contestation sérieuse, mesures conservatoires ou de remise en état pour prévenir un dommage imminent ou faire cesser un trouble manifestement illicite. Alinéa 2 : provision lorsque l'existence de l'obligation n'est pas sérieusement contestable.","r":"CPC art. 835","id":"4cac8344"},{"c":"urg","q":"Définition de l'ordonnance sur requête ?","a":"Une décision provisoire rendue non contradictoirement dans les cas où le requérant est fondé à ne pas appeler de partie adverse.","r":"CPC art. 493","id":"b026d0c4"},{"c":"pre","q":"Conditions de la mesure d'instruction in futurum ?","a":"Un motif légitime de conserver ou d'établir, avant tout procès, la preuve de faits dont pourrait dépendre la solution d'un litige. Sur requête ou en référé.","r":"CPC art. 145","id":"41c44aeb"},{"c":"pre","q":"Une mesure d'instruction peut elle pallier la carence d'une partie ?","a":"Non : elle ne peut en aucun cas être ordonnée en vue de suppléer la carence de la partie dans l'administration de la preuve.","r":"CPC art. 146","id":"96cc8207"},{"c":"vro","q":"Quelle est l'étendue de l'effet dévolutif de l'appel ?","a":"Les chefs de dispositif critiqués expressément et ceux qui en dépendent ; la dévolution opère pour le tout lorsque l'appel tend à l'annulation du jugement.","r":"CPC art. 562","id":"fc6b6f0e"},{"c":"vro","q":"Les prétentions nouvelles sont elles recevables en appel ?","a":"Non, à peine d'irrecevabilité relevée d'office, sauf compensation, rejet des prétentions adverses, intervention d'un tiers, survenance ou révélation d'un fait. Ne sont pas nouvelles celles qui tendent aux mêmes fins ; les moyens nouveaux sont recevables.","r":"CPC art. 563 à 566","id":"0c928700"},{"c":"vre","q":"Quelles sont les voies extraordinaires de recours ?","a":"La tierce opposition, le recours en révision et le pourvoi en cassation.","r":"CPC art. 580","id":"4b081b35"},{"c":"vre","q":"Objet du pourvoi en cassation ?","a":"Faire censurer par la Cour de cassation la non conformité du jugement qu'il attaque aux règles de droit.","r":"CPC art. 604","id":"185c4490"},{"c":"pd","q":"Que prévoit l'article 15 du CPC ?","a":"Les parties doivent se faire connaître mutuellement en temps utile les moyens de fait sur lesquels elles fondent leurs prétentions, les éléments de preuve qu'elles produisent et les moyens de droit qu'elles invoquent.","r":"CPC art. 15","id":"2eeb7734"},{"c":"pd","q":"Que retenir de l'arrêt Golder ?","a":"La Cour européenne déduit de l'article 6 § 1 un droit d'accès à un tribunal.","r":"CEDH, 21 févr. 1975, Golder c. Royaume Uni","id":"4bc4b2e4"},{"c":"pd","q":"Que retenir de l'arrêt Hornsby ?","a":"L'exécution d'une décision de justice fait partie intégrante du procès au sens de l'article 6 § 1.","r":"CEDH, 19 mars 1997, Hornsby c. Grèce","id":"47ad15ed"},{"c":"pd","q":"Quel est le principe de l'instruction des affaires depuis le 1er septembre 2025 ?","a":"L'instruction conventionnelle est le principe ; la mise en état par le juge devient l'exception.","r":"CPC art. 127 (décret n° 2025-660)","id":"59c53475"},{"c":"comp","q":"Compétence territoriale en matière réelle immobilière ?","a":"La juridiction du lieu où est situé l'immeuble est seule compétente.","r":"CPC art. 44","id":"1e158699"},{"c":"comp","q":"Quand le juge peut il relever d'office son incompétence territoriale en matière contentieuse ?","a":"Dans les litiges relatifs à l'état des personnes, lorsque la loi attribue compétence exclusive à une autre juridiction, ou si le défendeur ne comparaît pas.","r":"CPC art. 77","id":"3f55159f"},{"c":"comp","q":"Délai et voie de recours contre un jugement statuant sur la compétence ?","a":"L'appel, dans les quinze jours de la notification du jugement. Le contredit a été supprimé en 2017.","r":"CPC art. 83 et 84","id":"ee7757bc"},{"c":"intro","q":"Effets de la demande en justice sur la prescription ?","a":"Elle interrompt la prescription et la forclusion, même en référé, même devant une juridiction incompétente ou si l'acte est annulé pour vice de procédure. L'interruption dure jusqu'à l'extinction de l'instance et est non avenue en cas de désistement, de péremption ou de rejet définitif.","r":"C. civ. art. 2241 à 2243","id":"2fc83b64"},{"c":"intro","q":"Quel est le champ du préalable amiable obligatoire ?","a":"Les demandes en paiement n'excédant pas 5 000 euros et certaines actions énumérées, à peine d'irrecevabilité que le juge peut prononcer d'office, sauf dispenses. Il ne s'applique pas à la requête en injonction de payer.","r":"CPC art. 750-1 ; Cass., avis, 25 sept. 2025, n° 25-70.013","id":"8da1a837"},{"c":"intro","q":"Ordre des modes de signification ?","a":"À personne d'abord ; à défaut, à domicile ou à résidence ; si le destinataire n'a ni domicile, ni résidence, ni lieu de travail connus, procès verbal de recherches.","r":"CPC art. 654 à 659","id":"f46c9ce8"},{"c":"del","q":"Comment se calcule un délai exprimé en mois lorsque le quantième n'existe pas ?","a":"Le délai expire le dernier jour du mois.","r":"CPC art. 641 al. 2","id":"a731f355"},{"c":"del","q":"Que prévoit l'article 528-1 ?","a":"La partie qui a comparu ne peut plus exercer de recours à titre principal contre un jugement non notifié après un délai de deux ans à compter de son prononcé (jugements tranchant tout le principal ou mettant fin à l'instance). Ce délai ne s'applique pas au recours en révision.","r":"CPC art. 528-1 ; Cass. 2e civ., 23 mars 2023, n° 21-18.252","id":"35e26ad1"},{"c":"def","q":"Régularisation d'un acte nul pour vice de forme ?","a":"La nullité est couverte par la régularisation ultérieure si aucune forclusion n'est intervenue et si elle ne laisse subsister aucun grief.","r":"CPC art. 115","id":"99efc9b2"},{"c":"def","q":"Quelles sont les exceptions dilatoires ?","a":"Le délai pour faire inventaire et délibérer, le bénéfice de discussion ou de division, tout autre délai d'attente légal, et le délai pour appeler un garant.","r":"CPC art. 108 et 109","id":"eb8cde85"},{"c":"def","q":"Qualification du défaut de mise en œuvre d'une clause de conciliation préalable ?","a":"Une fin de non recevoir, qui s'impose au juge si les parties l'invoquent.","r":"Ch. mixte, 14 févr. 2003, n° 00-19.423","id":"2c1896f1"},{"c":"inst","q":"Causes d'interruption de l'instance ?","a":"La majorité d'une partie, la cessation des fonctions de l'avocat lorsque la représentation est obligatoire, l'effet de certains jugements de procédure collective ; et, à compter de la notification, le décès d'une partie dans les actions transmissibles.","r":"CPC art. 369 et 370","id":"7689bc1f"},{"c":"inst","q":"Effets de l'acquiescement ?","a":"À la demande : reconnaissance du bien fondé des prétentions adverses et renonciation à l'action. Au jugement : soumission à ses chefs et renonciation aux voies de recours. Il n'est admis que pour les droits disponibles.","r":"CPC art. 408 et 409","id":"1394a05d"},{"c":"inst","q":"À quelle condition l'ordonnance de clôture peut elle être révoquée ?","a":"S'il se révèle une cause grave depuis qu'elle a été rendue.","r":"CPC art. 803","id":"04661185"},{"c":"pre","q":"Régime de la preuve déloyale depuis 2023 ?","a":"Elle n'est plus irrecevable par principe : le juge vérifie qu'elle est indispensable à l'exercice du droit à la preuve et que l'atteinte aux droits antinomiques est strictement proportionnée au but poursuivi.","r":"Ass. plén., 22 déc. 2023, n° 20-20.648","id":"61564cda"},{"c":"pre","q":"Caractère subsidiaire de l'expertise ?","a":"Elle n'a lieu d'être ordonnée que si des constatations ou une consultation ne suffisent pas à éclairer le juge.","r":"CPC art. 263","id":"36ac92c8"},{"c":"pre","q":"Seuil de la preuve écrite des actes juridiques ?","a":"1 500 euros. Les faits juridiques se prouvent par tout moyen.","r":"C. civ. art. 1358 et 1359","id":"d1eebc3d"},{"c":"jug","q":"Différence entre autorité et force de chose jugée ?","a":"L'autorité de la chose jugée s'attache au jugement qui tranche le principal dès son prononcé. La force de chose jugée qualifie le jugement qui n'est plus susceptible d'aucun recours suspensif d'exécution.","r":"CPC art. 480 et 500","id":"0e7999bc"},{"c":"jug","q":"Exécution d'un jugement non notifié ?","a":"Impossible contre celui auquel il est opposé, sauf exécution volontaire.","r":"CPC art. 503","id":"b355ec43"},{"c":"urg","q":"Définition de la matière gracieuse ?","a":"Le juge statue en l'absence de litige, sur une demande dont la loi exige, en raison de la nature de l'affaire ou de la qualité du requérant, qu'elle soit soumise à son contrôle.","r":"CPC art. 25","id":"3d6dd6ee"},{"c":"urg","q":"Qu'est ce que la procédure accélérée au fond ?","a":"Lorsque la loi le prévoit, la demande est portée par voie d'assignation à une audience tenue aux jour et heure prévus à cet effet, et le juge statue au fond.","r":"CPC art. 481-1","id":"ba90db57"},{"c":"vro","q":"Appel des jugements avant dire droit ?","a":"Les jugements mixtes et ceux qui mettent fin à l'instance sur une exception, une fin de non recevoir ou un incident sont immédiatement susceptibles d'appel ; les autres jugements avant dire droit ne le sont qu'avec le jugement sur le fond, sauf texte.","r":"CPC art. 544 et 545","id":"81994b8e"},{"c":"vro","q":"Effet d'une déclaration d'appel sans chefs critiqués ?","a":"Pas d'effet dévolutif. Depuis 2024, l'appelant peut compléter les chefs critiqués dans ses premières conclusions remises dans les délais.","r":"Cass. 2e civ., 2 juill. 2020, n° 19-16.954 ; CPC art. 915-2","id":"26de4fcc"},{"c":"vre","q":"Causes du recours en révision ?","a":"Fraude de la partie gagnante, recouvrement de pièces décisives retenues, pièces reconnues ou déclarées fausses, attestations, témoignages ou serments déclarés faux. Délai : deux mois à compter de la connaissance de la cause.","r":"CPC art. 595 et 596","id":"2e7b3b54"},{"c":"vre","q":"Autorité de l'arrêt d'Assemblée plénière sur la juridiction de renvoi ?","a":"La juridiction de renvoi doit se conformer à la décision de l'Assemblée plénière sur les points de droit jugés par celle ci.","r":"COJ art. L. 431-4","id":"1b1e6db7"},{"c":"juge","q":"Deux démarches d'appréciation de l'impartialité selon l'arrêt Piersack ?","a":"Subjective : la conviction personnelle du juge, présumée. Objective : les garanties suffisantes pour exclure tout doute légitime, les apparences pouvant compter.","r":"CEDH, 1er oct. 1982, Piersack c. Belgique","id":"d4194080"},{"c":"juge","q":"Que jugent les arrêts Bord Na Mona et Guillotel ?","a":"Le juge des référés qui a alloué une provision ne peut statuer au fond ; celui qui a seulement ordonné une mesure conservatoire le peut.","r":"Ass. plén., 6 nov. 1998, n° 94-17.709 et n° 95-11.006","id":"da891dc3"},{"c":"juge","q":"Délai pour récuser un juge ?","a":"Dès que la partie a connaissance de la cause de récusation, à peine d'irrecevabilité, et jamais après la clôture des débats.","r":"CPC art. 342","id":"fbe89482"},{"c":"juge","q":"Différence entre récusation et renvoi pour cause de suspicion légitime ?","a":"La récusation vise un juge ; le renvoi pour suspicion légitime vise la juridiction dans son ensemble.","r":"CPC art. 341 et s.","id":"54e09c47"},{"c":"juge","q":"Valeur de la publicité des audiences civiles ?","a":"Principe à valeur constitutionnelle, susceptible de limitations proportionnées justifiées par l'intérêt général ou la nature de l'instance.","r":"Cons. const., 21 mars 2019, n° 2019-778 DC","id":"0761343d"},{"c":"juge","q":"Définition de la faute lourde du service de la justice ?","a":"Toute déficience caractérisée par un fait ou une série de faits traduisant l'inaptitude du service public de la justice à remplir la mission dont il est investi.","r":"Ass. plén., 23 févr. 2001, n° 99-16.165 ; COJ art. L. 141-1","id":"d3735050"},{"c":"juge","q":"Un justiciable peut il agir en responsabilité contre son juge ?","a":"Non : la responsabilité du magistrat pour faute personnelle se rattachant au service n'est engagée que par l'action récursoire de l'État.","r":"Ord. n° 58-1270 du 22 déc. 1958, art. 11-1","id":"fc0cae16"},{"c":"frais","q":"Qui supporte les dépens ?","a":"La partie perdante, sauf décision motivée du juge les mettant à la charge d'une autre partie. Le ministère public ne peut y être condamné.","r":"CPC art. 696","id":"fa5ef014"},{"c":"frais","q":"Critères de l'article 700 ?","a":"L'équité et la situation économique de la partie condamnée.","r":"CPC art. 700","id":"64315621"},{"c":"frais","q":"L'honoraire de résultat est il licite ?","a":"Oui, en complément d'un honoraire de diligences ; un honoraire fixé exclusivement en fonction du résultat est interdit.","r":"Loi du 31 déc. 1971, art. 10","id":"b53a035d"},{"c":"vro","q":"Taux de ressort en première instance ?","a":"5 000 euros devant toutes les juridictions de première instance ; la demande indéterminée est susceptible d'appel, sauf disposition contraire.","r":"CPC art. 40","id":"8fab1636"},{"c":"vro","q":"Sanction de l'inexécution du jugement exécutoire par l'appelant ?","a":"La radiation de l'affaire du rôle, à la demande de l'intimé, sauf conséquences manifestement excessives ou impossibilité d'exécuter.","r":"CPC art. 524","id":"07af0ec9"},{"c":"jug","q":"Existe t il une charge de concentration des demandes ?","a":"Non : seule la concentration des moyens est exigée ; le demandeur n'est pas tenu de présenter dans la même instance toutes les demandes fondées sur les mêmes faits.","r":"Civ. 1re, 30 nov. 2016, n° 15-20.043","id":"cee6b9fc"},{"c":"m1","q":"Que consacre le nouvel article 21 du CPC ?","a":"Un principe directeur de coopération : il entre dans la mission du juge de concilier les parties et de déterminer avec elles le mode de résolution le plus adapté.","r":"CPC art. 21 (décret n° 2025-660)","id":"2997aa83"},{"c":"m1","q":"Définition de la médiation ?","a":"Tout processus structuré par lequel deux ou plusieurs parties tentent de parvenir à un accord avec l'aide d'un tiers, le médiateur, choisi par elles ou désigné avec leur accord par le juge.","r":"Loi n° 95-125 du 8 févr. 1995, art. 21","id":"7eeac5a8"},{"c":"m1","q":"Définition de la transaction ?","a":"Contrat par lequel les parties, par des concessions réciproques, terminent une contestation née ou préviennent une contestation à naître.","r":"C. civ. art. 2044","id":"313e73bd"},{"c":"m1","q":"Périmètre de la confidentialité légale ?","a":"Médiation, conciliation par un conciliateur de justice, audience de règlement amiable ; sauf accord contraire. Les pièces produites ne sont pas couvertes ; la procédure participative et la conciliation par le juge hors audience de règlement amiable sont exclues.","r":"CPC art. 1528-3","id":"6bc1ea7f"},{"c":"m1","q":"Effet d'une médiation sur la prescription ?","a":"Suspension à compter de l'accord ou de la première réunion ; reprise pour au moins six mois à compter de la fin déclarée.","r":"C. civ. art. 2238","id":"dedbdfa8"},{"c":"m2","q":"Nature de l'injonction de rencontrer un médiateur ?","a":"Mesure d'administration judiciaire, insusceptible de recours.","r":"CPC art. 1533 (décret n° 2026-683)","id":"bb975c6c"},{"c":"m2","q":"Sanction de l'absence injustifiée à la réunion d'information ?","a":"Amende civile d'un maximum de 10 000 euros, sauf motif légitime.","r":"CPC art. 1533-3","id":"bb1c7af3"},{"c":"m2","q":"Délai pour recueillir le consentement à la médiation ordonnée à double détente ?","a":"Trois mois depuis le 1er octobre 2026 (un mois auparavant), sauf délai différent fixé par le juge.","r":"CPC art. 1534-1","id":"6908cdf0"},{"c":"m2","q":"Durée de la médiation ou de la conciliation judiciaire ?","a":"Cinq mois, suivie le cas échéant d'une période de trois mois.","r":"CPC art. 1534-4","id":"2903af0f"},{"c":"m2","q":"Le technicien peut il concilier les parties ?","a":"Oui, depuis l'abrogation de l'ancien article 240 par le décret n° 2025-660.","r":"Décret n° 2025-660","id":"f272db2e"},{"c":"m3","q":"Qui tient l'audience de règlement amiable ?","a":"Un autre juge que celui saisi du litige, sur convocation du juge saisi ou chargé de l'instruction, à tout stade sauf devant la Cour de cassation.","r":"CPC art. 1532","id":"77b73dca"},{"c":"m3","q":"Devant quelle juridiction l'audience de règlement amiable est elle exclue ?","a":"Le conseil de prud'hommes.","r":"CPC art. 1532","id":"ffec2db5"},{"c":"m4","q":"Forme de l'instruction conventionnelle simplifiée ?","a":"Pas d'acte contresigné par avocats ; elle peut être conclue directement entre les parties.","r":"CPC art. 129-1","id":"db3291f1"},{"c":"m4","q":"Effet de l'échec d'une procédure participative conclue hors instance ?","a":"Saisine du juge avec dispense du préalable obligatoire de conciliation ou de médiation, sauf devant le conseil de prud'hommes et le tribunal paritaire des baux ruraux.","r":"CPC art. 1540","id":"bf8388d9"},{"c":"m4","q":"Valeur de l'avis du technicien désigné conventionnellement entre avocats ?","a":"La même valeur qu'une expertise ordonnée par le juge.","r":"CPC art. 131-8","id":"45e55d1b"},{"c":"m5","q":"Pouvoirs du juge de l'homologation ?","a":"Contrôle de la licéité de l'objet et de la conformité à l'ordre public, sans pouvoir modifier les termes de l'accord.","r":"CPC art. 1544","id":"b6be9f8a"},{"c":"m5","q":"Quels accords sont homologables ?","a":"Ceux issus d'une conciliation, d'une médiation ou d'une procédure participative, et les transactions, même non issues d'un mode amiable.","r":"CPC art. 1541-1 et 1543","id":"3616cbec"},{"c":"a1","q":"Jurisdictio et imperium de l'arbitre ?","a":"L'arbitre dit le droit (jurisdictio) mais n'a pas d'imperium : l'exécution forcée de la sentence suppose l'exequatur du juge étatique.","r":"CPC art. 1487","id":"6ff800fe"},{"c":"a1","q":"Critère de l'arbitrage international ?","a":"Il met en cause des intérêts du commerce international (critère économique).","r":"CPC art. 1504","id":"e66daa56"},{"c":"a1","q":"Clause compromissoire et compromis ?","a":"La clause porte sur des litiges futurs relatifs à un contrat ; le compromis, sur un litige né.","r":"CPC art. 1442","id":"a6416a7d"},{"c":"a1","q":"Principe d'autonomie de la convention d'arbitrage ?","a":"Elle est indépendante du contrat auquel elle se rapporte et n'est pas affectée par son inefficacité.","r":"CPC art. 1447 ; Civ. 1re, 7 mai 1963, Gosset","id":"000e30e3"},{"c":"a1","q":"Opposabilité de la clause compromissoire ?","a":"Elle doit avoir été acceptée par la partie à qui on l'oppose, sauf succession ; elle n'est pas opposable à celui qui n'a pas contracté dans le cadre de son activité professionnelle.","r":"C. civ. art. 2061","id":"bc129f8c"},{"c":"a1","q":"Matières non arbitrables ?","a":"Notamment l'état et la capacité des personnes et le divorce ; la seule présence d'ordre public ne suffit pas à exclure l'arbitrage.","r":"C. civ. art. 2059 et 2060","id":"03d4656f"},{"c":"a2","q":"Effet négatif du principe compétence compétence ?","a":"Le juge étatique saisi se déclare incompétent, sauf si le tribunal arbitral n'est pas encore saisi et si la convention est manifestement nulle ou inapplicable.","r":"CPC art. 1448","id":"a0ba2e68"},{"c":"a2","q":"Effet positif du principe compétence compétence ?","a":"Le tribunal arbitral est seul compétent pour statuer sur les contestations relatives à son pouvoir juridictionnel.","r":"CPC art. 1465","id":"faf6a6ae"},{"c":"a2","q":"Obligation de révélation de l'arbitre ?","a":"Révéler, avant d'accepter et pendant la mission, toute circonstance susceptible d'affecter son indépendance ou son impartialité.","r":"CPC art. 1456","id":"1ca317d2"},{"c":"a2","q":"Durée de la mission de l'arbitre à défaut de stipulation ?","a":"Six mois à compter de la saisine, prorogeable par accord ou par le juge d'appui.","r":"CPC art. 1463","id":"05064474"},{"c":"a2","q":"Qu'est ce que l'amiable composition ?","a":"La mission donnée à l'arbitre de statuer en équité et non en droit ; à ne pas confondre avec les modes amiables.","r":"CPC art. 1478 et 1512","id":"bdafcb0e"},{"c":"a3","q":"Autorité de la sentence ?","a":"Autorité de la chose jugée dès qu'elle est rendue ; elle dessaisit le tribunal arbitral.","r":"CPC art. 1484 et 1485","id":"3739a6b5"},{"c":"a3","q":"Cas d'ouverture du recours en annulation en arbitrage interne ?","a":"Compétence ou incompétence retenue à tort, constitution irrégulière, non respect de la mission, violation de la contradiction, contrariété à l'ordre public, défauts formels de la sentence.","r":"CPC art. 1492","id":"ab3367d3"},{"c":"a3","q":"Délai du recours en annulation ?","a":"Un mois à compter de la notification de la sentence, en arbitrage interne comme international.","r":"CPC art. 1494 et 1519","id":"23d05a20"},{"c":"a3","q":"Effet suspensif du recours en annulation ?","a":"Suspensif en arbitrage interne ; non suspensif en arbitrage international.","r":"CPC art. 1496 et 1526","id":"45c234ee"},{"c":"a3","q":"Portée de l'arrêt Putrabali ?","a":"Une sentence internationale, non rattachée à un ordre juridique étatique, peut être reconnue en France même annulée au siège.","r":"Civ. 1re, 29 juin 2007","id":"3c47a567"},{"c":"e1","q":"Condition de l'exécution forcée ?","a":"Un titre exécutoire constatant une créance liquide et exigible.","r":"CPCE art. L. 111-2","id":"9cbe155f"},{"c":"e1","q":"Durée de l'exécution d'un titre exécutoire juridictionnel ?","a":"Dix ans, sauf prescription plus longue de l'action en recouvrement.","r":"CPCE art. L. 111-4","id":"69d28d35"},{"c":"e1","q":"Principe de proportionnalité de l'exécution ?","a":"Le créancier choisit les mesures, mais l'exécution ne peut excéder ce qui est nécessaire ; mainlevée des mesures inutiles ou abusives.","r":"CPCE art. L. 111-7 et L. 121-2","id":"98f85135"},{"c":"e1","q":"Refus du concours de la force publique ?","a":"L'État est tenu de prêter son concours ; son refus ouvre droit à réparation.","r":"CPCE art. L. 153-1","id":"706b7eed"},{"c":"e1","q":"Qu'est ce que le solde bancaire insaisissable ?","a":"Une somme laissée en toute hypothèse au débiteur sur son compte, égale au montant forfaitaire du RSA pour un allocataire seul, dans la limite du solde créditeur.","r":"CPCE art. L. 162-2","id":"aa8da166"},{"c":"e2","q":"Limites des pouvoirs du juge de l'exécution ?","a":"Il ne peut ni modifier le dispositif du titre, ni en suspendre l'exécution ; il peut accorder un délai de grâce après commandement ou saisie.","r":"CPCE art. R. 121-1","id":"acf9efa4"},{"c":"e2","q":"Portée de la décision n° 2023-1068 QPC ?","a":"Censure des mots de l'article L. 213-6 COJ visant les contestations de l'exécution forcée, effet au 1er décembre 2024 ; l'avis du 13 mars 2025 maintient la compétence du JEX pour les mesures mobilières dans les limites de la décision ; la loi n° 2026-403 du 26 mai 2026 rétablit sa compétence exclusive et crée un recours contre la mise à prix des droits incorporels.","r":"Cons. const., 17 nov. 2023 ; Cass. avis, 13 mars 2025 ; loi n° 2026-403","id":"e45b4775"},{"c":"e2","q":"Astreinte provisoire et définitive ?","a":"Provisoire sauf précision contraire ; liquidée selon le comportement du débiteur ; l'astreinte définitive suppose une astreinte provisoire préalable et son taux ne peut être modifié ; suppression en cas de cause étrangère.","r":"CPCE art. L. 131-2 et L. 131-4","id":"869eac33"},{"c":"e3","q":"Conditions d'une mesure conservatoire ?","a":"Une créance paraissant fondée en son principe et des circonstances menaçant son recouvrement ; autorisation du juge sauf dispense.","r":"CPCE art. L. 511-1 et L. 511-2","id":"578090b4"},{"c":"e3","q":"Délais de caducité des mesures conservatoires ?","a":"Trois mois pour exécuter l'autorisation ; un mois après l'exécution pour engager la procédure d'obtention d'un titre.","r":"CPCE art. R. 511-6 et R. 511-7","id":"80aa1704"},{"c":"e4","q":"Effet de la saisie attribution ?","a":"Attribution immédiate de la créance saisie disponible au profit du saisissant.","r":"CPCE art. L. 211-2","id":"fb34a901"},{"c":"e4","q":"Délais de la saisie attribution ?","a":"Dénonciation au débiteur dans les huit jours à peine de caducité ; contestation devant le JEX dans le mois de la dénonciation, à peine d'irrecevabilité.","r":"CPCE art. R. 211-3 et R. 211-11","id":"3b54442d"},{"c":"e4","q":"Qui met en œuvre la saisie des rémunérations depuis le 1er juillet 2025 ?","a":"Un commissaire de justice, au moins un mois après la signification d'un commandement de payer invitant à un accord, sous le contrôle du juge de l'exécution ; procès verbal de saisie dans les trois mois du commandement ; répartiteur désigné par la chambre nationale des commissaires de justice.","r":"CPCE art. L. 212-2 à L. 212-9 ; loi n° 2023-1059 ; décret n° 2025-125","id":"332ff775"},{"c":"e5","q":"Délai suivant le commandement de quitter les lieux ?","a":"Deux mois lorsque l'expulsion porte sur un lieu habité par la personne expulsée ou par tout occupant de son chef, sauf réduction ou suppression par le juge.","r":"CPCE art. L. 412-1","id":"1f4c2b76"},{"c":"e5","q":"Délais que le juge peut accorder à l'occupant ?","a":"Entre un mois et un an depuis la loi du 27 juillet 2023 (auparavant trois mois à trois ans).","r":"CPCE art. L. 412-4","id":"82eed76a"},{"c":"e5","q":"Trêve hivernale ?","a":"Du 1er novembre au 31 mars de l'année suivante, sauf relogement suffisant et sauf introduction dans le domicile d'autrui par manœuvres, menaces, voies de fait ou contrainte.","r":"CPCE art. L. 412-6","id":"6eb50e28"},{"c":"l1","q":"Durées du grand oral ?","a":"Préparation d'une heure, exposé de quinze minutes, entretien de trente minutes ; séance publique ; coefficient 4.","r":"Arrêté du 17 oct. 2016, art. 7","id":"1aa961a2"},{"c":"l1","q":"Structure d'une introduction de grand oral ?","a":"Accroche, définitions, contexte normatif et jurisprudentiel, intérêt, problématique, annonce du plan ; environ trois minutes.","r":"Méthode","id":"ca0b8a06"},{"c":"l1","q":"Serment de l'avocat ?","a":"« Je jure, comme avocat, d'exercer mes fonctions avec dignité, conscience, indépendance, probité et humanité. »","r":"Loi n° 71-1130, art. 3","id":"ccd23abe"},{"c":"l2","q":"Composantes du bloc de constitutionnalité ?","a":"Constitution de 1958, Déclaration de 1789, Préambule de 1946, principes fondamentaux reconnus par les lois de la République, Charte de l'environnement.","r":"Cons. const., 71-44 DC","id":"e3e5c607"},{"c":"l2","q":"Décision Liberté d'association ?","a":"16 juillet 1971, n° 71-44 DC : valeur constitutionnelle du Préambule ; liberté d'association, principe fondamental reconnu par les lois de la République.","r":"71-44 DC","id":"cd27c847"},{"c":"l2","q":"Contrôle de conventionnalité des lois ?","a":"Refusé par le Conseil constitutionnel (74-54 DC) ; exercé par le juge judiciaire (Jacques Vabre, 1975) et le juge administratif (Nicolo, 1989).","r":"Art. 55 de la Constitution","id":"ecfed28e"},{"c":"l2","q":"Principe de fraternité ?","a":"Principe à valeur constitutionnelle dont découle la liberté d'aider autrui dans un but humanitaire, sans condition de régularité du séjour (6 juill. 2018).","r":"2018-717/718 QPC","id":"1033e469"},{"c":"l2","q":"Charte des droits fondamentaux de l'Union ?","a":"Valeur des traités depuis le 1er décembre 2009 (art. 6 TUE) ; applicable aux États membres lorsqu'ils mettent en œuvre le droit de l'Union.","r":"TUE, art. 6","id":"d54f689d"},{"c":"l3","q":"Les trois régimes d'exercice des libertés ?","a":"Répressif (presse, 1881), déclaratif (manifestations), préventif (autorisation).","r":"Loi du 29 juill. 1881","id":"35344289"},{"c":"l3","q":"Contrôle de la mesure de police ?","a":"Nécessaire, adaptée et proportionnée à la menace pour l'ordre public (Benjamin, 1933) ; la dignité est une composante de l'ordre public (Morsang sur Orge, 1995).","r":"CE, Benjamin ; CE, Morsang sur Orge","id":"9e603d8a"},{"c":"l3","q":"Ingérence admise par les articles 8 à 11 de la Convention ?","a":"Prévue par la loi, poursuivant un but légitime, nécessaire dans une société démocratique.","r":"Conv. EDH, art. 8 à 11 § 2","id":"ccbe5ad2"},{"c":"l3","q":"Droits indérogeables (art. 15 Conv. EDH) ?","a":"Vie (sauf actes licites de guerre), interdiction de la torture, de l'esclavage, principe de légalité des peines.","r":"Conv. EDH, art. 15 § 2","id":"9af192ba"},{"c":"l4","q":"Conditions de transmission d'une QPC ?","a":"Disposition législative applicable au litige ; non déjà déclarée conforme, sauf changement des circonstances ; question non dépourvue de caractère sérieux. Renvoi au Conseil si nouvelle ou sérieuse, dans les trois mois.","r":"Constitution, art. 61-1","id":"323bc449"},{"c":"l4","q":"Conditions du référé liberté ?","a":"Urgence ; atteinte grave et manifestement illégale à une liberté fondamentale par une personne publique ; décision dans les quarante huit heures.","r":"CJA, art. L. 521-2","id":"4f02167d"},{"c":"l4","q":"Voie de fait depuis 2013 ?","a":"Décision ou exécution manifestement insusceptible de se rattacher à un pouvoir de l'administration, portant atteinte à la liberté individuelle ou éteignant un droit de propriété.","r":"TC, 17 juin 2013, Bergoend","id":"f409dc5c"},{"c":"l4","q":"Délai et conditions de saisine de la CEDH ?","a":"Qualité de victime, épuisement des voies internes, quatre mois depuis la décision interne définitive (depuis le 1er février 2022).","r":"Conv. EDH, art. 34 et 35","id":"be1076e5"},{"c":"l4","q":"Fondement constitutionnel du droit au recours et des droits de la défense ?","a":"Article 16 de la Déclaration de 1789.","r":"Cons. const., 96-373 DC","id":"24affad3"},{"c":"l4","q":"Missions du Défenseur des droits ?","a":"Droits des usagers des services publics, droits de l'enfant, lutte contre les discriminations, déontologie des forces de sécurité, orientation des lanceurs d'alerte.","r":"Constitution, art. 71-1 ; LO n° 2011-333","id":"bd23edd2"},{"c":"l5","q":"Valeur constitutionnelle de la dignité ?","a":"Principe à valeur constitutionnelle depuis les décisions bioéthique du 27 juillet 1994.","r":"94-343/344 DC","id":"ace5b81a"},{"c":"l5","q":"Affaire Vincent Lambert ?","a":"CE, Ass., 24 juin 2014 : arrêt des traitements légal ; CEDH, GC, 5 juin 2015 : pas de violation de l'article 2.","r":"CE, n° 375081 ; CEDH, n° 46043/14","id":"1ec1c66c"},{"c":"l5","q":"Arrêt J.M.B. c. France ?","a":"30 janvier 2020 : conditions de détention contraires à l'article 3 et absence de recours préventif effectif ; recours créé par la loi du 8 avril 2021 (art. 803-8 CPP).","r":"CEDH, n° 9671/15","id":"3a5ced5e"},{"c":"l5","q":"Arrêt Bouyid c. Belgique ?","a":"GC, 28 septembre 2015 : une gifle infligée par un policier à une personne sous son contrôle peut constituer un traitement dégradant.","r":"CEDH, n° 23380/09","id":"6efd2f70"},{"c":"l6","q":"Décision garde à vue de 2010 ?","a":"30 juillet 2010, n° 2010-14/22 QPC : régime de droit commun contraire à la Constitution, abrogation différée ; réforme par la loi du 14 avril 2011.","r":"2010-14/22 QPC","id":"ac4616bc"},{"c":"l6","q":"Fondement constitutionnel de la vie privée ?","a":"Article 2 de la Déclaration de 1789 (liberté).","r":"99-416 DC","id":"16b2a839"},{"c":"l6","q":"Arrêt Mennesson ?","a":"CEDH, 26 juin 2014 : violation du droit des enfants nés par gestation pour autrui au respect de leur vie privée, faute de reconnaissance de la filiation paternelle biologique.","r":"CEDH, n° 65192/11","id":"648b9975"},{"c":"l6","q":"Arrêt KlimaSeniorinnen ?","a":"CEDH, GC, 9 avril 2024 : l'article 8 implique une protection effective contre les effets graves du changement climatique ; violation par la Suisse.","r":"CEDH, n° 53600/20","id":"5660f30c"},{"c":"l7","q":"Formule de l'arrêt Handyside ?","a":"La liberté d'expression vaut aussi pour les idées qui heurtent, choquent ou inquiètent (7 déc. 1976).","r":"CEDH, Handyside","id":"c8c93d36"},{"c":"l7","q":"Arrêt Morice c. France ?","a":"GC, 23 avril 2015 : protection renforcée de la liberté d'expression de l'avocat ; critique des magistrats admise sur une base factuelle suffisante.","r":"CEDH, n° 29369/10","id":"e6a30bc7"},{"c":"l7","q":"Arrêt S.A.S. c. France ?","a":"GC, 1er juillet 2014 : l'interdiction de la dissimulation du visage dans l'espace public ne viole pas la Convention (« vivre ensemble »).","r":"CEDH, n° 43835/11","id":"203f8233"},{"c":"l7","q":"Ordonnance du 26 août 2016 ?","a":"Suspension d'un arrêté interdisant les tenues manifestant une appartenance religieuse sur les plages, faute de risque avéré pour l'ordre public.","r":"CE, ord., n° 402742","id":"1cc06d53"},{"c":"l8","q":"Test d'égalité du Conseil constitutionnel ?","a":"Différence de situation ou motif d'intérêt général, la différence de traitement devant être en rapport direct avec l'objet de la loi.","r":"DDHC, art. 6","id":"6e4123f1"},{"c":"l8","q":"Décision Nationalisations ?","a":"16 janvier 1982, n° 81-132 DC : pleine valeur constitutionnelle du droit de propriété ; liberté d'entreprendre tirée de l'article 4 de la Déclaration.","r":"81-132 DC","id":"3dec4195"},{"c":"l8","q":"Logement décent ?","a":"Objectif de valeur constitutionnelle (19 janv. 1995).","r":"94-359 DC","id":"5b94a6a5"},{"c":"l8","q":"Valeur de la Charte de l'environnement ?","a":"Valeur constitutionnelle ; ses droits et devoirs s'imposent aux pouvoirs publics (CE, Ass., 3 oct. 2008, Commune d'Annecy).","r":"CE, n° 297931","id":"6fe888a9"},{"c":"p1","q":"Mission du conseil de prud'hommes ?","a":"Concilier les différends nés du contrat de travail de droit privé et juger ceux qui n'ont pas été conciliés.","r":"C. trav., art. L. 1411-1","id":"5e3691cf"},{"c":"p1","q":"Composition des formations ?","a":"Bureau de jugement : 2 + 2 ; bureau de conciliation et d'orientation, référé et formation restreinte : 1 + 1 ; départage : formation présidée par un juge du tribunal judiciaire.","r":"C. trav., art. L. 1423-12, L. 1423-13, L. 1454-2","id":"a9735fb6"},{"c":"p1","q":"Les cinq sections ?","a":"Encadrement, industrie, commerce et services commerciaux, agriculture, activités diverses ; plus une formation commune de référé.","r":"C. trav., art. L. 1423-1","id":"9e2c0527"},{"c":"p1","q":"Désignation du juge départiteur ?","a":"Juge du tribunal judiciaire du ressort, désigné chaque année par le président du tribunal judiciaire ; reprise de l'affaire dans le mois.","r":"C. trav., art. L. 1454-2","id":"7b8bacc3"},{"c":"p1","q":"Conditions pour être conseiller prud'homme ?","a":"Nationalité française, 21 ans au moins, casier compatible, deux ans d'activité ou mandat prud'homal dans les dix ans ; nomination tous les quatre ans.","r":"C. trav., art. L. 1441-1 et L. 1441-7","id":"3e0e76f6"},{"c":"p1","q":"Sanction du défaut de formation initiale ?","a":"Le conseiller est réputé démissionnaire.","r":"C. trav., art. L. 1442-1","id":"0c787f65"},{"c":"p2","q":"Compétence d'attribution ?","a":"Exclusive quel que soit le montant ; convention contraire réputée non écrite ; exclusion des litiges attribués à une autre juridiction (accidents du travail).","r":"C. trav., art. L. 1411-4","id":"0799237e"},{"c":"p2","q":"Litige sur une rupture conventionnelle ?","a":"Conseil de prud'hommes pour la convention, l'homologation ou son refus ; recours dans les douze mois de l'homologation.","r":"C. trav., art. L. 1237-14","id":"32c38c1f"},{"c":"p2","q":"Compétence territoriale ?","a":"Lieu de l'établissement où le travail est accompli ; domicile du salarié si travail à domicile ou hors établissement ; option du salarié : lieu d'engagement ou siège de l'employeur.","r":"C. trav., art. R. 1412-1","id":"017f6fd6"},{"c":"p3","q":"Effet de la saisine ?","a":"La requête saisit le conseil et interrompt la prescription, même devant un conseil incompétent.","r":"C. trav., art. R. 1452-1","id":"ee6f74e7"},{"c":"p3","q":"Pièces jointes à la requête depuis le 1er octobre 2026 ?","a":"Bordereau des pièces et dernier bulletin de salaire (ou pièce identifiant l'activité de l'employeur), pour l'orientation vers la section.","r":"C. trav., art. R. 1452-2 ; décret n° 2026-683","id":"d7abcd4d"},{"c":"p3","q":"Contribution pour l'aide juridique ?","a":"50 euros depuis le 1er mars 2026, due par la partie qui introduit l'instance ; exonération des bénéficiaires de l'aide juridictionnelle.","r":"CGI, art. 1635 bis Q","id":"a0517998"},{"c":"p3","q":"Prescriptions prud'homales ?","a":"Exécution : 2 ans ; rupture : 12 mois ; salaire : 3 ans ; discrimination : 5 ans à compter de la révélation.","r":"C. trav., art. L. 1471-1, L. 3245-1, L. 1134-5","id":"c5520d4c"},{"c":"p3","q":"Unicité de l'instance ?","a":"Supprimée pour les instances introduites à compter du 1er août 2016 ; autorité de la chose jugée et concentration des moyens.","r":"Décret n° 2016-660","id":"888e0613"},{"c":"p4","q":"Personnes habilitées à représenter une partie ?","a":"Salarié ou employeur de la même branche, défenseur syndical, conjoint, partenaire ou concubin, avocat ; membre de l'entreprise pour l'employeur ; pouvoir spécial sauf avocat.","r":"C. trav., art. R. 1453-2","id":"47fe1156"},{"c":"p4","q":"Défenseur syndical ?","a":"Assiste ou représente devant le conseil et la cour d'appel ; inscrit sur une liste administrative ; intervient dans une région.","r":"C. trav., art. L. 1453-4","id":"f4e2911c"},{"c":"p5","q":"Saisines directes du bureau de jugement ?","a":"Requalification de CDD, prise d'acte, requalification de stage : jugement dans le mois ; relevé des créances en procédure collective.","r":"C. trav., art. L. 1245-2, L. 1451-1, L. 1454-5 ; C. com., art. L. 625-5","id":"c493fb17"},{"c":"p5","q":"Plafond des provisions du bureau de conciliation et d'orientation ?","a":"Six mois de salaire calculés sur la moyenne des trois derniers mois.","r":"C. trav., art. R. 1454-15","id":"b8fa750f"},{"c":"p5","q":"Voies de recours contre les mesures provisoires du bureau ?","a":"Ni opposition, ni appel immédiat : appel ou pourvoi seulement avec le jugement sur le fond.","r":"C. trav., art. R. 1454-16","id":"7d1fb35a"},{"c":"p5","q":"Formation restreinte ?","a":"Un conseiller de chaque collège ; saisie avec l'accord des parties pour un licenciement ou une résiliation judiciaire ; statue dans les trois mois.","r":"C. trav., art. L. 1454-1-1","id":"9155f8d0"},{"c":"p5","q":"Non comparution du demandeur à la conciliation ?","a":"Jugement en l'état, renvoi au bureau de jugement ou caducité si le défendeur ne demande pas un jugement au fond ; caducité rapportée sur motif légitime dans les quinze jours.","r":"C. trav., art. R. 1454-12 ; CPC, art. 468","id":"c128d197"},{"c":"p6","q":"Délai de l'audience de départage ?","a":"Dans le mois du renvoi ; quinze jours au plus en référé.","r":"C. trav., art. R. 1454-29","id":"a95e2027"},{"c":"p6","q":"Exécution provisoire des jugements prud'homaux ?","a":"Pas de droit en principe ; de droit pour la remise de documents, les salaires dans la limite de neuf mois, et le jugement appelable par suite d'une seule demande reconventionnelle.","r":"C. trav., art. R. 1454-28","id":"79295b69"},{"c":"p6","q":"Taux de ressort ?","a":"5 000 euros ; dernier ressort aussi pour la seule remise de documents.","r":"C. trav., art. R. 1462-1, D. 1462-3","id":"a163fb1f"},{"c":"p7","q":"Délai d'appel en référé prud'homal ?","a":"Quinze jours.","r":"C. trav., art. R. 1455-11","id":"9fd7f1ce"},{"c":"p7","q":"Contestation de l'avis du médecin du travail ?","a":"Procédure accélérée au fond devant le conseil, dans les quinze jours de la notification de l'avis.","r":"C. trav., art. L. 4624-7, R. 4624-45","id":"14f1aae4"},{"c":"p8","q":"Délai et juridiction d'appel ?","a":"Un mois ; chambre sociale de la cour d'appel ; représentation obligatoire par avocat ou défenseur syndical.","r":"C. trav., art. R. 1461-1, R. 1461-2","id":"b2d11d8d"},{"c":"p4","q":"Principe de la représentation devant le conseil ?","a":"Les parties se défendent elles mêmes et peuvent se faire assister ou représenter ; pouvoir spécial pour le non avocat.","r":"C. trav., art. R. 1453-1, R. 1453-2","id":"e20e9277"},{"c":"p5","q":"Pouvoirs du conseiller rapporteur ?","a":"Pouvoirs de mise en état du bureau, audition de toute personne, mesures d'instruction et de conservation des preuves ; constat de la conciliation par procès verbal.","r":"C. trav., art. R. 1454-4, R. 1454-5","id":"9c132258"},{"c":"p5","q":"Barème de l'indemnité forfaitaire de conciliation ?","a":"2 mois (moins d'un an) ; 3 mois à un an, plus 1 mois par an jusqu'à 8 ans ; puis 10, 12, 14, 16, 18, 20 et 24 mois selon les tranches d'ancienneté.","r":"C. trav., art. D. 1235-21","id":"14d1f93c"},{"c":"p6","q":"Caractère de la procédure prud'homale ?","a":"Orale ; renvoi possible aux écritures ; conclusions récapitulatives avec dispositif si toutes les parties sont représentées par avocat et concluent par écrit.","r":"C. trav., art. R. 1453-3 à R. 1453-5","id":"78037936"},{"c":"p6","q":"Indemnité pour licenciement sans cause réelle et sérieuse ?","a":"Proposition de réintégration ; à défaut, indemnité encadrée par un barème selon l'ancienneté, jugé conforme à la convention n° 158 de l'OIT.","r":"C. trav., art. L. 1235-3 ; Cass. soc., 11 mai 2022, n° 21-14.490","id":"d38918c4"},{"c":"p7","q":"Formes de la demande en référé prud'homal ?","a":"Acte de commissaire de justice (copie au greffe la veille de l'audience au plus tard) ou requête.","r":"C. trav., art. R. 1455-9","id":"0e2b2394"},{"c":"p8","q":"Exécution du jugement prud'homal frappé d'appel ?","a":"Seules les condamnations exécutoires de droit (documents, salaires et indemnités dans la limite de neuf mois) ou expressément assorties de l'exécution provisoire s'exécutent ; radiation possible en cas d'inexécution.","r":"C. trav., art. R. 1454-28 ; CPC, art. 524","id":"1a780b7f"},{"c":"p9","q":"Trois différences majeures avec le tribunal judiciaire ?","a":"Saisine par requête ; représentation facultative en première instance ; absence d'exécution provisoire de droit, sauf exceptions.","r":"C. trav., art. R. 1452-1, R. 1453-1, R. 1454-28 ; CPC, art. 514, 750, 760","id":"22aba600"},{"c":"k1","q":"Directions du ministère (mars 2026) ?","a":"Secrétariat général ; DSJ, DACS, DACG, DGAP, DPJJ, DNUM ; inspection générale de la justice.","r":"Organigramme du ministère, mars 2026","id":"40d59120"},{"c":"k1","q":"Écoles du ministère ?","a":"ENM (Bordeaux, Paris), ENG (Dijon), ENAP (Agen), ENPJJ (Roubaix).","r":"Organigramme du ministère, mars 2026","id":"33df05f2"},{"c":"k1","q":"Garde des Sceaux ?","a":"Gérald Darmanin, en fonctions depuis décembre 2024 ; nomination renouvelée par décret du 12 octobre 2025.","r":"Ministère de la Justice","id":"a76c7775"},{"c":"k1","q":"DGAP ?","a":"Direction générale de l'administration pénitentiaire, effective le 1er février 2026 (décret n° 2025-1275 du 22 décembre 2025).","r":"Ministère de la Justice, dossier de presse du 2 février 2026","id":"7bb77556"},{"c":"k2","q":"Missions du greffier ?","a":"Assister le magistrat à l'audience, dresser les actes de greffe, notes et procès verbaux, authentifier les actes ; accueil et information des justiciables.","r":"COJ, art. R. 123-13","id":"1ef88c4a"},{"c":"k2","q":"Cadres greffiers ?","a":"Corps de catégorie A créé au 1er janvier 2025 (décret n° 2024-1089) : encadrement de premier niveau, expertise procédurale.","r":"Décret n° 2024-1089","id":"ae9210a0"},{"c":"k2","q":"Attachés de justice ?","a":"Assistance et aide à la décision auprès des magistrats ; serment et secret professionnel ; objectif de 1 100 atteint fin 2025.","r":"COJ, art. L. 123-4 ; loi n° 2023-1059","id":"b2b563be"},{"c":"k3","q":"Ouverture de la magistrature aux femmes ?","a":"Loi du 11 avril 1946 ; Charlotte Béquignon-Lagarde, première magistrate, à la Cour de cassation.","r":"Ministère de la Justice","id":"bb7573b5"},{"c":"k3","q":"Création de l'ENM ?","a":"Centre national d'études judiciaires créé en 1958, devenu École nationale de la magistrature en 1970.","r":"ENM, « Genèse de l'école »","id":"d7af7ec0"},{"c":"k3","q":"Tribunaux des activités économiques ?","a":"Expérimentation de quatre ans depuis le 1er janvier 2025 dans douze tribunaux (art. 26 de la loi n° 2023-1059).","r":"Loi n° 2023-1059, art. 26","id":"a3f07000"},{"c":"k4","q":"Oral du concours externe de greffier ?","a":"Entretien de 25 minutes au plus dont 5 minutes d'exposé sur le parcours et la motivation ; mise en situation ; coefficient 4 ; note inférieure à 5 éliminatoire.","r":"Notice du concours de greffier, session 2027","id":"f01c19fd"},{"c":"k9","q":"Le chêne de Saint Louis ?","a":"Louis IX rendant la justice sous un chêne de Vincennes (récit de Joinville) : justice accessible et directe ; en réalité, le roi confiait l'essentiel de la justice à des légistes. Hommage dans le tribunal de Paris (terrasses arborées).","r":"Actu-Juridique ; Aleteia, 2018","id":"13bbf06b"},{"c":"k9","q":"Symboles de la justice ?","a":"Thémis ; bandeau (impartialité) ; balance (équité) ; glaive (répression, force) ; tables de la Loi (primauté du droit) ; main de justice (pouvoir royal jusqu'en 1792) ; robe ; pas de marteau en France.","r":"Ministère de la Justice, « Les symboles de la justice »","id":"20d5db50"},{"c":"k9","q":"Budget de la justice ?","a":"2026 : 13,06 Md€ en CP (+3 %), 10,63 Md€ hors pensions ; PLF 2027 : près de 11 Md€, 621 emplois judiciaires dont 334 greffiers et 287 magistrats.","r":"Sénat, rapport PLF 2026 ; JSS, 1er oct. 2026","id":"8d91b594"},{"c":"k9","q":"Promesse de recrutement de la LOPJ ?","a":"10 000 emplois dont 1 500 magistrats et 1 800 greffiers d'ici 2027 ; au 1er décembre 2025, 571 greffiers arrivés et 833 en formation ; retards relevés par le Sénat.","r":"Loi n° 2023-1059 ; ministère, 12 janv. 2026 ; Sénat","id":"05fcaf41"},{"c":"k9","q":"Loi « SURE » ?","a":"Loi n° 2026-651 du 23 juillet 2026 sur la justice criminelle et le respect des victimes : sans plaider coupable criminel ; délai des nullités réduit ; censure partielle (n° 2026-909 DC).","r":"Loi n° 2026-651","id":"91f17c2f"},{"c":"k9","q":"Question d'oral : « Que pensez vous des moyens de la justice ? »","a":"Rappeler la hausse continue des crédits et la LOPJ ; nuancer par les retards de recrutement des greffiers, les requalifications et les départs en retraite ; montrer l'enjeu des délais de jugement ; rester mesuré et institutionnel.","r":"Synthèse des sources du chapitre","id":"39369434"},{"c":"k5","q":"Abolition de la peine de mort ?","a":"Discours de Robert Badinter le 17 septembre 1981 ; loi du 9 octobre 1981 ; art. 66-1 de la Constitution depuis le 23 février 2007 ; dernière exécution le 10 septembre 1977.","r":"Constitution, art. 66-1","id":"88381583"},{"c":"k5","q":"Premières avocates ?","a":"Loi du 1er décembre 1900 ; Olga Petit prête serment la première ; Jeanne Chauvin, deuxième, plaide la première en janvier 1901.","r":"Loi du 1er décembre 1900","id":"8745dc4c"},{"c":"k5","q":"Pionnières de la justice ?","a":"Charlotte Béquignon-Lagarde (1946, magistrate) ; Simone Rozès (1984, première présidente de la Cour de cassation) ; Élisabeth Guigou (1997, garde des Sceaux) ; Dominique de La Garanderie (1997, bâtonnier de Paris).","r":"Ministère de la Justice ; Ordre des avocats de Paris","id":"cd7e681d"},{"c":"k6","q":"Serment de l'avocat ?","a":"« Je jure, comme avocat, d'exercer mes fonctions avec dignité, conscience, indépendance, probité et humanité ».","r":"Loi n° 71-1130, art. 3","id":"ccd23abe"},{"c":"k6","q":"Étendue du secret professionnel ?","a":"Toutes matières, conseil et défense : consultations, correspondances (sauf mention « officielle » entre confrères), notes d'entretien, pièces du dossier.","r":"Loi n° 71-1130, art. 66-5","id":"54756ac2"},{"c":"k6","q":"Grandes étapes de la profession ?","a":"Loi du 31 décembre 1971 ; fusion avec les conseils juridiques (loi du 31 décembre 1990) ; intégration des avoués au 1er janvier 2012 (loi du 25 janvier 2011).","r":"Loi n° 71-1130 ; loi n° 2011-94","id":"d39caa3a"},{"c":"k6","q":"Conseil national des barreaux ?","a":"Établissement d'utilité publique : représente la profession, unifie ses règles et usages.","r":"Loi n° 71-1130, art. 21-1","id":"3b6c1afc"},{"c":"k7","q":"Cours criminelles départementales ?","a":"Cinq magistrats ; crimes punis de quinze ou vingt ans commis par des majeurs hors récidive ; généralisées le 1er janvier 2023.","r":"Loi n° 2021-1729","id":"804b546c"},{"c":"k8","q":"Entretien du grand oral ?","a":"Trente minutes après un exposé de quinze minutes ; questions sur le sujet puis culture juridique générale ; séance publique.","r":"Arrêté du 17 oct. 2016, art. 7","id":"98c7e6ac"}],"juris":[{"c":"pd","nom":"Golder c. Royaume Uni","ref":"CEDH, 21 févr. 1975","sol":"L'article 6 § 1 de la Convention garantit le droit d'accès à un tribunal.","portee":"Fondement du contrôle des obstacles excessifs à l'accès au juge."},{"c":"pd","nom":"Hornsby c. Grèce","ref":"CEDH, 19 mars 1997","sol":"L'exécution d'une décision de justice fait partie intégrante du procès au sens de l'article 6.","portee":"Rattache les voies d'exécution au droit au procès équitable."},{"c":"pd","nom":"Dauvin, dit aussi Carteret","ref":"Ass. plén., 21 déc. 2007, n° 06-11.343","sol":"Le juge n'est pas tenu, sauf règles particulières, de changer la dénomination ou le fondement juridique des demandes.","portee":"La requalification de l'article 12 est une faculté, non une obligation."},{"c":"jug","nom":"Cesareo","ref":"Ass. plén., 7 juill. 2006, n° 04-10.672","sol":"Il incombe au demandeur de présenter dès l'instance relative à la première demande l'ensemble des moyens de nature à la fonder.","portee":"Principe de concentration des moyens : une même demande ne peut être rejugée sur un autre fondement."},{"c":"def","nom":"Liste limitative de l'article 117","ref":"Ch. mixte, 7 juill. 2006, n° 03-20.026","sol":"Seules les irrégularités énumérées par l'article 117 constituent des irrégularités de fond.","portee":"Toute autre irrégularité relève du régime des vices de forme, avec exigence d'un grief."},{"c":"def","nom":"Clause de conciliation préalable","ref":"Ch. mixte, 14 févr. 2003, n° 00-19.423","sol":"La clause instituant une procédure de conciliation obligatoire et préalable constitue une fin de non recevoir qui s'impose au juge si les parties l'invoquent.","portee":"Illustration du caractère non limitatif de l'article 122."},{"c":"pre","nom":"Preuve déloyale","ref":"Ass. plén., 22 déc. 2023, n° 20-20.648","sol":"Une preuve illicite ou déloyale n'est pas nécessairement écartée : le juge apprécie si elle est indispensable au droit à la preuve et si l'atteinte est strictement proportionnée.","portee":"Abandon de l'irrecevabilité de principe des preuves déloyales en matière civile."},{"c":"vro","nom":"Effet dévolutif et chefs critiqués","ref":"Cass. 2e civ., 2 juill. 2020, n° 19-16.954","sol":"La déclaration d'appel qui ne mentionne pas les chefs du jugement critiqués n'opère pas d'effet dévolutif.","portee":"Assouplie par l'article 915-2 issu du décret n° 2023-1391 pour les appels formés depuis le 1er septembre 2024."},{"c":"vre","nom":"Révision et article 528-1","ref":"Cass. 2e civ., 23 mars 2023, n° 21-18.252","sol":"Le délai de deux ans de l'article 528-1 ne s'applique pas au recours en révision.","portee":"Seul compte le délai de deux mois à compter de la connaissance de la cause de révision (art. 596)."},{"c":"intro","nom":"Annulation de l'article 750-1","ref":"CE, 22 sept. 2022, n° 436939","sol":"Le Conseil d'État annule l'article 750-1 dans sa rédaction de 2019, en modulant les effets dans le temps de l'annulation.","portee":"Le texte a été rétabli par le décret n° 2023-357 pour les instances introduites à compter du 1er octobre 2023."},{"c":"intro","nom":"Instances en cours et article 750-1","ref":"Cass. 2e civ., 6 févr. 2025, n° 22-20.070","sol":"Les instances engagées à la date de la décision du Conseil d'État sont atteintes par l'effet rétroactif de l'annulation : l'article 750-1 ne leur est pas applicable.","portee":"Précise la portée temporelle de l'annulation."},{"c":"intro","nom":"Injonction de payer et préalable amiable","ref":"Cass., avis, 25 sept. 2025, n° 25-70.013","sol":"L'obligation de tentative préalable de résolution amiable ne s'applique pas à la requête en injonction de payer.","portee":"Exclut la procédure non contradictoire d'injonction de payer du champ de l'article 750-1."},{"c":"juge","nom":"Piersack c. Belgique","ref":"CEDH, 1er oct. 1982","sol":"L'impartialité s'apprécie selon une démarche subjective et une démarche objective.","portee":"Fonde l'appréciation de l'impartialité par les apparences et les garanties offertes."},{"c":"juge","nom":"Bord Na Mona et Guillotel","ref":"Ass. plén., 6 nov. 1998, n° 94-17.709 et n° 95-11.006","sol":"Le juge des référés qui a alloué une provision ne peut statuer au fond ; celui qui n'a ordonné qu'une mesure conservatoire le peut.","portee":"Illustration de l'impartialité fonctionnelle : seul le juge qui a pris parti est empêché."},{"c":"juge","nom":"Publicité des audiences civiles","ref":"Cons. const., 21 mars 2019, n° 2019-778 DC","sol":"La publicité des audiences devant les juridictions civiles a valeur constitutionnelle, sous réserve de limitations proportionnées.","portee":"Élève la publicité au rang de principe constitutionnel en matière civile."},{"c":"juge","nom":"Motivation par reproduction des conclusions","ref":"Civ. 3e, 28 janv. 2021, n° 19-19.172","sol":"Le juge qui se borne à reproduire les conclusions d'une partie fait naître un doute légitime sur son impartialité.","portee":"La motivation est aussi une garantie d'impartialité."},{"c":"juge","nom":"Définition de la faute lourde","ref":"Ass. plén., 23 févr. 2001, n° 99-16.165","sol":"Constitue une faute lourde toute déficience caractérisée par un fait ou une série de faits traduisant l'inaptitude du service public de la justice à remplir sa mission.","portee":"Objectivation de la faute lourde de l'article L. 141-1 COJ."},{"c":"jug","nom":"Absence de concentration des demandes","ref":"Civ. 1re, 30 nov. 2016, n° 15-20.043","sol":"Est recevable la demande en réduction des intérêts d'un prêt formée après le rejet d'une demande en annulation de ce prêt.","portee":"Le demandeur n'est pas tenu de présenter dans la même instance toutes les demandes fondées sur les mêmes faits."},{"c":"m1","nom":"Clause de conciliation préalable","ref":"Ch. mixte, 14 févr. 2003, n° 00-19.423","sol":"Le défaut de mise en œuvre d'une clause instituant une conciliation obligatoire et préalable constitue une fin de non recevoir qui s'impose au juge si les parties l'invoquent.","portee":"Fondement de l'efficacité procédurale des clauses d'amiable."},{"c":"a1","nom":"Gosset","ref":"Civ. 1re, 7 mai 1963","sol":"En matière d'arbitrage international, la clause compromissoire présente une complète autonomie juridique à l'égard du contrat principal.","portee":"Consacre l'autonomie de la convention d'arbitrage, aujourd'hui inscrite à l'article 1447 pour l'arbitrage interne."},{"c":"a1","nom":"Dalico","ref":"Civ. 1re, 20 déc. 1993","sol":"L'existence et l'efficacité de la clause compromissoire s'apprécient d'après la commune volonté des parties, sans qu'il soit nécessaire de se référer à une loi étatique, sous réserve des règles impératives et de l'ordre public international.","portee":"Méthode des règles matérielles en arbitrage international."},{"c":"a1","nom":"Validité de principe de la clause internationale","ref":"Civ. 1re, 5 janv. 1999, n° 96-21.430","sol":"En matière d'arbitrage international, la clause compromissoire est en principe valable.","portee":"Cité par N. Cayrol pour illustrer la faveur du droit français envers l'arbitrage international."},{"c":"a3","nom":"Putrabali","ref":"Civ. 1re, 29 juin 2007","sol":"La sentence internationale, qui n'est rattachée à aucun ordre juridique étatique, est une décision de justice internationale dont la régularité est examinée au regard des règles du pays où sa reconnaissance est demandée.","portee":"Une sentence annulée au siège peut être reconnue en France."},{"c":"a3","nom":"Annulation et inopposabilité de la convention","ref":"Civ. 1re, 6 mars 2013, n° 12-15.375","sol":"Lorsque la convention d'arbitrage est inopposable à certaines parties, la cour d'appel qui annule la sentence doit s'abstenir de statuer au fond et renvoyer les parties à mieux se pourvoir.","portee":"Limite à la dévolution au fond de l'article 1493."},{"c":"e2","nom":"Juge de l'exécution et contestations de l'exécution forcée","ref":"Cons. const., 17 nov. 2023, n° 2023-1068 QPC","sol":"Les mots de l'article L. 213-6 COJ visant les contestations élevées à l'occasion de l'exécution forcée sont déclarés contraires à la Constitution, faute de recours contre la mise à prix des droits incorporels saisis ; abrogation différée au 1er décembre 2024.","portee":"A ouvert une incertitude sur la compétence du juge de l'exécution en matière mobilière, close par la loi n° 2026-403 du 26 mai 2026."},{"c":"e2","nom":"Maintien de la compétence du JEX","ref":"Cass. 2e civ., avis, 13 mars 2025, n° 25-70.003 à 25-70.006","sol":"Le juge de l'exécution demeure compétent pour statuer sur les contestations relatives aux mesures d'exécution forcée mobilières, dans les limites de la décision du Conseil constitutionnel.","portee":"Tempère la lecture de la circulaire du 28 novembre 2024 qui orientait ce contentieux vers le tribunal judiciaire ; solution consacrée et étendue par la loi n° 2026-403 du 26 mai 2026, qui rétablit la compétence exclusive du juge de l'exécution."},{"c":"l2","nom":"Liberté d'association","ref":"Cons. const., 16 juill. 1971, n° 71-44 DC","sol":"La liberté d'association est un principe fondamental reconnu par les lois de la République ; le Préambule a valeur constitutionnelle.","portee":"Fonde le bloc de constitutionnalité et le contrôle du respect des droits par la loi."},{"c":"l2","nom":"IVG","ref":"Cons. const., 15 janv. 1975, n° 74-54 DC","sol":"Le Conseil constitutionnel refuse de contrôler la conformité des lois aux traités.","portee":"Le contrôle de conventionnalité revient aux juges ordinaires."},{"c":"l2","nom":"Nicolo","ref":"CE, Ass., 20 oct. 1989, n° 108243","sol":"Le juge administratif écarte une loi, même postérieure, contraire à un traité.","portee":"Aligne le Conseil d'État sur la Cour de cassation (Jacques Vabre, 1975)."},{"c":"l2","nom":"Fraternité","ref":"Cons. const., 6 juill. 2018, n° 2018-717/718 QPC","sol":"Le principe de fraternité a valeur constitutionnelle ; il en découle la liberté d'aider autrui, dans un but humanitaire, sans considération de la régularité de son séjour.","portee":"Censure partielle du délit d'aide au séjour irrégulier."},{"c":"l3","nom":"Benjamin","ref":"CE, 19 mai 1933, n° 17413","sol":"Une mesure de police restreignant une liberté doit être nécessaire et proportionnée aux risques de troubles.","portee":"Fondement du contrôle de proportionnalité des mesures de police."},{"c":"l3","nom":"Commune de Morsang sur Orge","ref":"CE, Ass., 27 oct. 1995, n° 136727","sol":"Le respect de la dignité de la personne humaine est une composante de l'ordre public ; le maire peut interdire un spectacle qui y porte atteinte.","portee":"Ordre public immatériel ; débat sur le consentement de l'intéressé."},{"c":"l4","nom":"Bergoend","ref":"TC, 17 juin 2013, n° 3911","sol":"La voie de fait suppose une atteinte à la liberté individuelle ou l'extinction d'un droit de propriété par une décision ou une exécution manifestement insusceptible de se rattacher à un pouvoir de l'administration.","portee":"Restreint la compétence du juge judiciaire au profit du référé liberté."},{"c":"l4","nom":"Droits de la défense","ref":"Cons. const., 9 avr. 1996, n° 96-373 DC","sol":"L'article 16 de la Déclaration de 1789 garantit le droit des personnes à exercer un recours effectif devant une juridiction et les droits de la défense.","portee":"Fondement constitutionnel du droit au recours."},{"c":"l4","nom":"Golder c. Royaume Uni","ref":"CEDH, 21 févr. 1975","sol":"L'article 6 § 1 garantit le droit d'accès à un tribunal.","portee":"Le procès équitable suppose d'abord l'accès au juge."},{"c":"l4","nom":"Michaud c. France","ref":"CEDH, 6 déc. 2012, n° 12323/11","sol":"L'obligation de déclaration de soupçon imposée aux avocats ne porte pas une atteinte disproportionnée au secret professionnel, protégé par l'article 8, eu égard au filtre du bâtonnier.","portee":"Le secret professionnel de l'avocat est protégé mais non absolu."},{"c":"l5","nom":"Bioéthique","ref":"Cons. const., 27 juill. 1994, n° 94-343/344 DC","sol":"La sauvegarde de la dignité de la personne humaine contre toute forme d'asservissement et de dégradation est un principe à valeur constitutionnelle.","portee":"Consécration constitutionnelle de la dignité."},{"c":"l5","nom":"Lambert et autres c. France","ref":"CEDH, GC, 5 juin 2015, n° 46043/14","sol":"La mise en œuvre de la décision d'arrêt des traitements n'emporte pas violation de l'article 2.","portee":"Marge d'appréciation des États en matière de fin de vie ; prolonge CE, Ass., 24 juin 2014, n° 375081."},{"c":"l5","nom":"J.M.B. et autres c. France","ref":"CEDH, 30 janv. 2020, n° 9671/15","sol":"Conditions de détention contraires à l'article 3 et absence de recours préventif effectif (art. 13).","portee":"Loi du 8 avril 2021 créant le recours de l'article 803-8 CPP."},{"c":"l5","nom":"Bouyid c. Belgique","ref":"CEDH, GC, 28 sept. 2015, n° 23380/09","sol":"Une gifle infligée par un policier à une personne entièrement sous son contrôle porte atteinte à la dignité et constitue un traitement dégradant.","portee":"Lien entre dignité et article 3."},{"c":"l6","nom":"Garde à vue","ref":"Cons. const., 30 juill. 2010, n° 2010-14/22 QPC","sol":"Le régime de la garde à vue de droit commun est contraire à la Constitution, faute de garanties appropriées, notamment l'assistance effective d'un avocat ; abrogation différée au 1er juillet 2011.","portee":"Première grande QPC ; réforme du 14 avril 2011."},{"c":"l6","nom":"Brusco c. France","ref":"CEDH, 14 oct. 2010, n° 1466/07","sol":"Violation du droit de ne pas contribuer à sa propre incrimination et de garder le silence, faute d'information et d'assistance d'un avocat.","portee":"Convergence avec la décision du 30 juillet 2010."},{"c":"l6","nom":"Mennesson c. France","ref":"CEDH, 26 juin 2014, n° 65192/11","sol":"Le refus de reconnaître la filiation paternelle biologique d'enfants nés par gestation pour autrui à l'étranger viole leur droit au respect de la vie privée.","portee":"Premier avis consultatif du protocole n° 16, demandé par la Cour de cassation en 2018."},{"c":"l6","nom":"Verein KlimaSeniorinnen Schweiz et autres c. Suisse","ref":"CEDH, GC, 9 avr. 2024, n° 53600/20","sol":"L'article 8 consacre un droit à une protection effective par les autorités contre les effets néfastes graves du changement climatique ; violation par la Suisse.","portee":"Contentieux climatique européen ; qualité pour agir des associations."},{"c":"l7","nom":"Handyside c. Royaume Uni","ref":"CEDH, 7 déc. 1976","sol":"La liberté d'expression vaut aussi pour les idées qui heurtent, choquent ou inquiètent.","portee":"Pluralisme, tolérance et esprit d'ouverture, conditions d'une société démocratique."},{"c":"l7","nom":"Morice c. France","ref":"CEDH, GC, 23 avr. 2015, n° 29369/10","sol":"La condamnation d'un avocat pour diffamation envers des magistrats viole l'article 10 ; la critique reposait sur une base factuelle suffisante.","portee":"Liberté d'expression renforcée de l'avocat."},{"c":"l7","nom":"Dieudonné","ref":"CE, ord., 9 janv. 2014, n° 374508","sol":"L'interdiction d'un spectacle est justifiée par l'atteinte à la dignité de la personne humaine et le risque d'infractions pénales.","portee":"Exception notable à la jurisprudence Benjamin, critiquée."},{"c":"l7","nom":"S.A.S. c. France","ref":"CEDH, GC, 1er juill. 2014, n° 43835/11","sol":"L'interdiction de la dissimulation du visage dans l'espace public ne viole ni l'article 8 ni l'article 9, au regard de l'objectif du « vivre ensemble ».","portee":"Large marge d'appréciation reconnue à l'État."},{"c":"l7","nom":"Ligue des droits de l'homme (arrêtés anti burkini)","ref":"CE, ord., 26 août 2016, n° 402742","sol":"L'arrêté interdisant les tenues manifestant une appartenance religieuse sur les plages porte une atteinte grave et manifestement illégale aux libertés, faute de risque avéré.","portee":"Application de Benjamin à la liberté religieuse."},{"c":"l8","nom":"Nationalisations","ref":"Cons. const., 16 janv. 1982, n° 81-132 DC","sol":"Pleine valeur constitutionnelle du droit de propriété ; liberté d'entreprendre tirée de l'article 4 de la Déclaration.","portee":"Protection constitutionnelle des droits économiques."},{"c":"l8","nom":"Logement décent","ref":"Cons. const., 19 janv. 1995, n° 94-359 DC","sol":"La possibilité pour toute personne de disposer d'un logement décent est un objectif de valeur constitutionnelle.","portee":"Les droits sociaux comme objectifs guidant le législateur."},{"c":"l8","nom":"Commune d'Annecy","ref":"CE, Ass., 3 oct. 2008, n° 297931","sol":"L'ensemble des droits et devoirs définis par la Charte de l'environnement a valeur constitutionnelle et s'impose aux pouvoirs publics.","portee":"Invocabilité de la Charte devant le juge administratif."},{"c":"l8","nom":"Protection de l'environnement","ref":"Cons. const., 31 janv. 2020, n° 2019-823 QPC","sol":"La protection de l'environnement, patrimoine commun des êtres humains, constitue un objectif de valeur constitutionnelle pouvant justifier des atteintes à la liberté d'entreprendre.","portee":"Conciliation entre environnement et libertés économiques."},{"c":"l8","nom":"Commune de Grande Synthe","ref":"CE, 19 nov. 2020, n° 427301","sol":"Le Conseil d'État contrôle la trajectoire de réduction des émissions de gaz à effet de serre au regard des engagements de la France.","portee":"Premier grand contentieux climatique en France."},{"c":"p2","nom":"Société générale","ref":"Cass. soc., 13 nov. 1996, n° 94-13.187","sol":"Le lien de subordination est caractérisé par l'exécution d'un travail sous l'autorité d'un employeur qui a le pouvoir de donner des ordres et des directives, d'en contrôler l'exécution et d'en sanctionner les manquements.","portee":"Critère de la compétence prud'homale."},{"c":"p2","nom":"Compétence territoriale et délai raisonnable","ref":"Cass. 2e civ., 3 oct. 2024, n° 22-14.853","sol":"Les parties ne peuvent écarter les règles de compétence territoriale des juridictions prud'homales en invoquant la surcharge du conseil compétent.","portee":"Caractère d'ordre public de l'article R. 1412-1."},{"c":"p5","nom":"Office du bureau de conciliation","ref":"Cass. soc., 28 mars 2000, n° 97-42.419","sol":"Le procès verbal de conciliation n'est valable que si le bureau a rempli son office en s'assurant que les parties étaient informées de leurs droits respectifs.","portee":"La conciliation prud'homale est un acte juridictionnel contrôlé."},{"c":"p6","nom":"Preuve illicite ou déloyale","ref":"Ass. plén., 22 déc. 2023, n° 20-20.648","sol":"Une preuve obtenue de manière déloyale n'est pas nécessairement écartée : le juge apprécie si elle est indispensable à l'exercice du droit à la preuve et si l'atteinte est strictement proportionnée.","portee":"Rendue en matière prud'homale (enregistrement clandestin d'un salarié)."},{"c":"p3","nom":"Concentration des moyens","ref":"Ass. plén., 7 juill. 2006, n° 04-10.672","sol":"Il incombe au demandeur de présenter dès l'instance relative à la première demande l'ensemble des moyens de nature à la fonder.","portee":"Applicable au contentieux prud'homal depuis la suppression de l'unicité de l'instance."},{"c":"p6","nom":"Barème d'indemnisation","ref":"Cass. soc., 11 mai 2022, n° 21-14.490","sol":"Le barème de l'article L. 1235-3 du code du travail est compatible avec l'article 10 de la convention n° 158 de l'OIT ; le juge ne peut l'écarter, même au cas par cas, au titre d'une réparation adéquate.","portee":"Fin des résistances de certains conseils de prud'hommes et cours d'appel."},{"c":"p5","nom":"Prise d'acte","ref":"Cass. soc., 25 juin 2003, n° 01-42.335","sol":"Lorsque le salarié prend acte de la rupture en raison de faits qu'il reproche à l'employeur, la rupture produit les effets d'un licenciement sans cause réelle et sérieuse si les faits la justifient, ou d'une démission dans le cas contraire.","portee":"Le législateur a ensuite prévu la saisine directe du bureau de jugement, qui statue dans le mois (art. L. 1451-1)."},{"c":"p5","nom":"Gravité du manquement justifiant la prise d'acte","ref":"Cass. soc., 26 mars 2014, n° 12-23.634","sol":"La prise d'acte n'est justifiée qu'en présence d'un manquement de l'employeur suffisamment grave pour empêcher la poursuite du contrat de travail.","portee":"Exigence d'un manquement actuel et grave."}],"delais":[{"a":"Appel d'un jugement rendu en matière contentieuse","d":"1 mois","n":1,"u":"m","dep":"Notification du jugement","s":"","t":"CPC art. 528 et 538","dist":1},{"a":"Appel d'une décision rendue en matière gracieuse","d":"15 jours","n":15,"u":"j","dep":"Notification","s":"","t":"CPC art. 538","dist":1},{"a":"Appel d'une ordonnance de référé","d":"15 jours","n":15,"u":"j","dep":"Notification","s":"","t":"CPC art. 490","dist":1},{"a":"Appel d'un jugement statuant sur la compétence","d":"15 jours","n":15,"u":"j","dep":"Notification du jugement","s":"","t":"CPC art. 84","dist":1},{"a":"Appel d'une ordonnance rejetant une requête","d":"15 jours","n":15,"u":"j","dep":"Voir le texte","s":"","t":"CPC art. 496","dist":1},{"a":"Opposition à un jugement rendu par défaut","d":"1 mois","n":1,"u":"m","dep":"Notification","s":"","t":"CPC art. 538 et 571","dist":1},{"a":"Opposition à une ordonnance d'injonction de payer","d":"1 mois","n":1,"u":"m","dep":"Signification de l'ordonnance","s":"","t":"CPC art. 1416","dist":1},{"a":"Pourvoi en cassation","d":"2 mois","n":2,"u":"m","dep":"Notification de la décision","s":"","t":"CPC art. 612","dist":1},{"a":"Recours en révision","d":"2 mois","n":2,"u":"m","dep":"Jour où la partie a eu connaissance de la cause de révision","s":"","t":"CPC art. 596","dist":1},{"a":"Tierce opposition formée à titre principal","d":"30 ans","n":30,"u":"a","dep":"Jugement","s":"","t":"CPC art. 586","dist":0},{"a":"Tierce opposition du tiers à qui le jugement a été notifié","d":"2 mois","n":2,"u":"m","dep":"Notification au tiers, comportant les mentions requises","s":"","t":"CPC art. 586","dist":1},{"a":"Conclusions de l'appelant, procédure avec mise en état","d":"3 mois","n":3,"u":"m","dep":"Déclaration d'appel","s":"Caducité de la déclaration d'appel, relevée d'office","t":"CPC art. 908","dist":0},{"a":"Conclusions de l'intimé, procédure avec mise en état","d":"3 mois","n":3,"u":"m","dep":"Notification des conclusions de l'appelant","s":"Irrecevabilité relevée d'office","t":"CPC art. 909","dist":0},{"a":"Conclusions de l'appelant, procédure à bref délai","d":"2 mois","n":2,"u":"m","dep":"Réception de l'avis de fixation à bref délai","s":"Caducité de la déclaration d'appel, relevée d'office","t":"CPC art. 906-2","dist":0},{"a":"Péremption d'instance","d":"2 ans","n":2,"u":"a","dep":"Dernière diligence des parties","s":"Extinction de l'instance, non de l'action","t":"CPC art. 386 et 389","dist":0},{"a":"Notification d'un jugement par défaut ou réputé contradictoire au seul motif qu'il est susceptible d'appel","d":"6 mois","n":6,"u":"m","dep":"Date du jugement","s":"Jugement non avenu","t":"CPC art. 478","dist":0},{"a":"Requête en omission de statuer","d":"1 an","n":1,"u":"a","dep":"Passage en force de chose jugée de la décision","s":"","t":"CPC art. 463","dist":0},{"a":"Délai de distance, partie demeurant à l'étranger (devant une juridiction métropolitaine)","d":"2 mois","n":null,"dep":"S'ajoute au délai concerné","s":"","t":"CPC art. 643","dist":0},{"a":"Délai de distance, partie demeurant outre mer (devant une juridiction métropolitaine)","d":"1 mois","n":null,"dep":"S'ajoute au délai concerné","s":"","t":"CPC art. 643","dist":0},{"a":"Indisponibilité du conciliateur dispensant de la tentative préalable","d":"3 mois","n":null,"dep":"Premier rendez vous proposé au delà de ce délai","s":"","t":"CPC art. 750-1","dist":0},{"a":"Recours contre un jugement non notifié, partie qui a comparu","d":"2 ans","n":2,"u":"a","dep":"Prononcé de la décision","s":"","t":"CPC art. 528-1","dist":0},{"a":"Durée initiale de la médiation ou de la conciliation judiciaire","d":"5 mois","n":5,"u":"m","dep":"Décision qui ordonne la mesure ; période complémentaire possible de trois mois","s":"","t":"CPC art. 1534-4","dist":0},{"a":"Recueil du consentement à la médiation ordonnée à double détente","d":"3 mois","n":3,"u":"m","dep":"Décision du juge, sauf délai différent fixé par lui (depuis le 1er oct. 2026)","s":"","t":"CPC art. 1534-1","dist":0},{"a":"Reprise de la prescription après une médiation ou une conciliation (durée minimale)","d":"6 mois","n":6,"u":"m","dep":"Déclaration de fin du processus","s":"","t":"C. civ. art. 2238","dist":0},{"a":"Durée de la mission du tribunal arbitral à défaut de stipulation","d":"6 mois","n":6,"u":"m","dep":"Saisine du tribunal arbitral ; prorogation possible","s":"","t":"CPC art. 1463","dist":0},{"a":"Recours en annulation d'une sentence (interne ou internationale)","d":"1 mois","n":1,"u":"m","dep":"Notification de la sentence","s":"","t":"CPC art. 1494 et 1519","dist":0},{"a":"Durée d'exécution d'un titre exécutoire juridictionnel","d":"10 ans","n":10,"u":"a","dep":"Titre exécutoire, sauf prescription plus longue","s":"","t":"CPCE art. L. 111-4","dist":0},{"a":"Exécution d'une autorisation de mesure conservatoire","d":"3 mois","n":3,"u":"m","dep":"Ordonnance d'autorisation","s":"Caducité de l'autorisation","t":"CPCE art. R. 511-6","dist":0},{"a":"Engagement de la procédure en vue d'un titre après une mesure conservatoire","d":"1 mois","n":1,"u":"m","dep":"Exécution de la mesure","s":"Caducité de la mesure","t":"CPCE art. R. 511-7","dist":0},{"a":"Contestation d'une saisie attribution","d":"1 mois","n":1,"u":"m","dep":"Dénonciation de la saisie au débiteur","s":"Irrecevabilité","t":"CPCE art. R. 211-11","dist":0},{"a":"Délai d'expulsion après commandement de quitter les lieux (lieu habité)","d":"2 mois","n":2,"u":"m","dep":"Commandement de quitter les lieux","s":"","t":"CPCE art. L. 412-1","dist":0},{"a":"Délais de grâce de droit commun (maximum)","d":"2 ans","n":2,"u":"a","dep":"Décision du juge","s":"","t":"C. civ. art. 1343-5","dist":0},{"a":"Action portant sur l'exécution du contrat de travail","d":"2 ans","n":2,"u":"a","dep":"Connaissance des faits","s":"Prescription","t":"C. trav. art. L. 1471-1","dist":0},{"a":"Action portant sur la rupture du contrat de travail","d":"1 an","n":12,"u":"m","dep":"Notification de la rupture (douze mois)","s":"Prescription","t":"C. trav. art. L. 1471-1","dist":0},{"a":"Action en paiement du salaire","d":"3 ans","n":3,"u":"a","dep":"Connaissance des faits","s":"Prescription","t":"C. trav. art. L. 3245-1","dist":0},{"a":"Action en réparation d'une discrimination","d":"5 ans","n":5,"u":"a","dep":"Révélation de la discrimination","s":"Prescription","t":"C. trav. art. L. 1134-5","dist":0},{"a":"Contestation de la rupture conventionnelle","d":"1 an","n":12,"u":"m","dep":"Date d'homologation (douze mois)","s":"Irrecevabilité","t":"C. trav. art. L. 1237-14","dist":0},{"a":"Appel d'un jugement du conseil de prud'hommes","d":"1 mois","n":1,"u":"m","dep":"Notification du jugement","s":"Irrecevabilité","t":"C. trav. art. R. 1461-1","dist":1},{"a":"Appel d'une ordonnance de référé prud'homale","d":"15 jours","n":15,"u":"j","dep":"Notification de l'ordonnance","s":"Irrecevabilité","t":"C. trav. art. R. 1455-11","dist":1},{"a":"Contestation de l'avis du médecin du travail","d":"15 jours","n":15,"u":"j","dep":"Notification de l'avis","s":"Irrecevabilité","t":"C. trav. art. R. 4624-45","dist":0},{"a":"Audience de départage (bureau de jugement)","d":"1 mois","n":1,"u":"m","dep":"Renvoi après partage des voix","s":"","t":"C. trav. art. R. 1454-29","dist":0},{"a":"Jugement de la formation restreinte","d":"3 mois","n":3,"u":"m","dep":"Renvoi par le bureau de conciliation et d'orientation","s":"","t":"C. trav. art. L. 1454-1-1","dist":0},{"a":"Jugement sur la requalification d'un CDD en CDI","d":"1 mois","n":1,"u":"m","dep":"Saisine directe du bureau de jugement","s":"","t":"C. trav. art. L. 1245-2","dist":0},{"a":"Jugement sur la prise d'acte de la rupture","d":"1 mois","n":1,"u":"m","dep":"Saisine directe du bureau de jugement","s":"","t":"C. trav. art. L. 1451-1","dist":0},{"a":"Audience de départage en référé prud'homal","d":"15 jours","n":15,"u":"j","dep":"Renvoi après partage des voix (au plus tard)","s":"","t":"C. trav. art. R. 1454-29 (référé)","dist":0},{"a":"Rapport de la caducité de la requête prud'homale","d":"15 jours","n":15,"u":"j","dep":"Déclaration de caducité (motif légitime à faire connaître)","s":"Caducité maintenue","t":"C. trav. art. R. 1454-12 ; CPC art. 468","dist":0}],"qualif":[["Le défendeur soutient que le tribunal territorialement compétent est celui de son domicile.",0,"Exception d'incompétence (articles 73 et 75). Elle doit être motivée et désigner la juridiction compétente, in limine litis."],["Le défendeur fait valoir que le même litige est déjà pendant devant une autre juridiction de même degré également compétente.",0,"Exception de litispendance (article 100)."],["Le défendeur demande que l'affaire soit jointe à une instance connexe pendante devant une autre juridiction.",0,"Exception de connexité (article 101)."],["L'assignation ne mentionne pas l'objet de la demande ; le défendeur en invoque la nullité.",0,"Exception de nullité pour vice de forme (articles 112 à 116). Grief requis."],["Le gérant qui a assigné au nom de la société n'en était plus le représentant légal.",0,"Exception de nullité pour irrégularité de fond (article 117) : défaut de pouvoir du représentant d'une personne morale. Proposable en tout état de cause, sans grief."],["L'héritier assigné demande à bénéficier du délai pour faire inventaire et délibérer.",0,"Exception dilatoire (article 108)."],["Le défendeur soutient que l'action est prescrite.",1,"Fin de non recevoir (article 122). Le juge ne peut la relever d'office (article 2247 du Code civil)."],["Le défendeur soutient que le demandeur n'a aucun intérêt à agir.",1,"Fin de non recevoir tirée du défaut d'intérêt (articles 31 et 122)."],["Le défendeur fait valoir que la même demande, entre les mêmes parties et pour la même cause, a déjà été tranchée.",1,"Fin de non recevoir tirée de la chose jugée (article 122 ; article 1355 du Code civil)."],["Le défendeur oppose une clause du contrat imposant une conciliation préalable à toute action, non mise en œuvre.",1,"Fin de non recevoir, selon la Chambre mixte (14 février 2003), qui s'impose au juge si les parties l'invoquent."],["Une demande en paiement de 3 000 euros n'a été précédée d'aucune tentative de conciliation, de médiation ni de procédure participative.",1,"Irrecevabilité de l'article 750-1, que le juge peut prononcer d'office ; elle relève du régime des fins de non recevoir."],["L'action en nullité relative est exercée par une personne que la loi n'entend pas protéger.",1,"Fin de non recevoir tirée du défaut de qualité (articles 31 et 122)."],["L'appel a été interjeté après l'expiration du délai d'un mois.",1,"Fin de non recevoir d'ordre public, que le juge doit relever d'office (article 125)."],["Le défendeur soutient avoir déjà payé la somme réclamée.",2,"Défense au fond (article 71) : elle tend au rejet de la prétention après examen au fond du droit."],["Le défendeur oppose l'exception d'inexécution : le demandeur n'a pas exécuté sa propre obligation.",2,"Malgré son nom, l'exception d'inexécution est une défense au fond (article 71), non une exception de procédure."],["Poursuivi en exécution d'un contrat, le défendeur en invoque la nullité pour vice du consentement afin de faire rejeter la demande.",2,"Défense au fond : l'exception de nullité du contrat vise le fond du droit. Si le défendeur demande en outre restitution ou dommages et intérêts, il forme une demande reconventionnelle."],["Le défendeur conteste avoir commis une quelconque faute.",2,"Défense au fond (article 71)."],["Le défendeur réclame des dommages et intérêts pour procédure abusive.",3,"Demande reconventionnelle (article 64) : il prétend obtenir un avantage autre que le simple rejet de la prétention adverse."],["Le défendeur assigne son assureur afin qu'il le garantisse des condamnations éventuelles.",3,"Demande incidente sous forme d'intervention forcée (articles 63, 66 et 331), aux fins de garantie."],["En cours d'instance, le demandeur augmente le montant de sa réclamation pour tenir compte d'un préjudice aggravé.",3,"Demande additionnelle (article 65), recevable si elle présente un lien suffisant (article 70)."],["Un mineur non émancipé a assigné seul ; le défendeur invoque l'irrégularité.",0,"Exception de nullité pour irrégularité de fond (article 117) : défaut de capacité d'ester en justice. Proposable en tout état de cause, sans grief."],["Un tiers intervient volontairement à l'instance pour revendiquer la propriété du bien litigieux.",3,"Intervention volontaire principale (article 329), demande incidente au sens de l'article 63."]],"cas":[{"c":"def","titre":"La clause, la prescription et l'incompétence","enonce":"M. Lambert, particulier domicilié à Grenoble, a acheté en 2019 du matériel informatique à la société Datanet, dont le siège est à Lyon, qui le lui a livré à Grenoble. Les conditions générales, rédigées en petits caractères, attribuent compétence au tribunal de commerce de Lyon. Le matériel s'étant révélé défectueux, M. Lambert assigne la société en 2026 devant le tribunal judiciaire de Grenoble en paiement de 12 000 euros de dommages et intérêts. Un juge de la mise en état est désigné. La société Datanet conclut d'abord sur le fond en contestant tout défaut, puis, dans des conclusions ultérieures, soulève l'incompétence du tribunal en invoquant la clause, et enfin la prescription de l'action.","questions":[{"q":"La clause attributive de compétence est elle opposable à M. Lambert ?","corr":["Problème. Il s'agit de déterminer si une clause des conditions générales désignant une juridiction lyonnaise peut priver un particulier de la faculté de saisir le juge de son domicile, lieu de livraison.","Règle. En principe, la juridiction territorialement compétente est celle du lieu où demeure le défendeur (art. 42). En matière contractuelle, le demandeur peut aussi saisir la juridiction du lieu de la livraison effective de la chose (art. 46). L'article 48 répute non écrite toute clause qui, directement ou indirectement, déroge aux règles de compétence territoriale, à moins qu'elle n'ait été convenue entre des personnes ayant toutes contracté en qualité de commerçant et qu'elle n'ait été spécifiée de façon très apparente dans l'engagement de la partie à qui elle est opposée. Les deux conditions sont cumulatives.","Application. M. Lambert a contracté en qualité de particulier : la première condition fait défaut. La clause figure en outre en petits caractères dans des conditions générales : la seconde condition fait également défaut. La clause est donc réputée non écrite. Elle désigne en outre une juridiction commerciale : selon une jurisprudence constante, le non commerçant ne peut se voir imposer cette juridiction et dispose, lorsqu'il agit contre un commerçant, d'une option entre la juridiction civile et la juridiction commerciale.","Conclusion. La clause ne lui est pas opposable. Le matériel ayant été livré à Grenoble, le tribunal judiciaire de Grenoble est compétent en vertu de l'option de l'article 46 ; le tribunal judiciaire de Lyon, juridiction du siège du défendeur, l'aurait été également (art. 42). Le montant de la demande, supérieur à 10 000 euros, relève du tribunal judiciaire, devant lequel la constitution d'avocat est en principe obligatoire (art. 760)."]},{"q":"L'exception d'incompétence est elle recevable ?","corr":["Problème. La société a conclu au fond avant de soulever l'incompétence : il faut savoir si cette chronologie rend l'exception irrecevable, indépendamment de son bien fondé.","Règle. Les exceptions de procédure doivent, à peine d'irrecevabilité, être soulevées simultanément et avant toute défense au fond ou fin de non recevoir, et ce alors même que les règles invoquées au soutien de l'exception seraient d'ordre public (art. 74). La partie qui soulève l'incompétence doit, à peine d'irrecevabilité, la motiver et faire connaître devant quelle juridiction elle demande que l'affaire soit portée (art. 75). Devant le tribunal judiciaire, le juge de la mise en état est, de sa désignation à son dessaisissement, seul compétent pour statuer sur les exceptions de procédure (art. 789, 1°). Le juge ne peut relever d'office l'incompétence que dans les cas limitativement prévus par l'article 76 : violation d'une règle de compétence d'attribution d'ordre public ou défaut de comparution du défendeur.","Application. La société Datanet a d'abord contesté l'existence du défaut, ce qui constitue une défense au fond (art. 71). L'exception d'incompétence, soulevée ensuite, est tardive. Le caractère d'ordre public qu'aurait la règle invoquée serait indifférent (art. 74). Le juge ne pourrait davantage relever d'office une incompétence territoriale, le défendeur ayant comparu (art. 76).","Conclusion. L'exception est irrecevable. Elle aurait de toute façon été rejetée au fond, la clause étant réputée non écrite. Pour être recevable, elle aurait dû figurer dans les premières conclusions, adressées au juge de la mise en état, avant toute défense au fond, être motivée et désigner la juridiction prétendument compétente."]},{"q":"La prescription peut elle encore être invoquée, et devant quel juge ?","corr":["Problème. Après avoir conclu au fond et soulevé une exception, le défendeur oppose la prescription : il faut qualifier ce moyen, déterminer s'il est encore recevable et identifier le juge compétent pour en connaître.","Règle. La prescription est une fin de non recevoir (art. 122), qui peut être proposée en tout état de cause, sauf la possibilité pour le juge de condamner à des dommages et intérêts celui qui se serait abstenu, dans une intention dilatoire, de la soulever plus tôt (art. 123). Elle doit être accueillie sans que son auteur ait à justifier d'un grief (art. 124). Les juges ne peuvent pas suppléer d'office le moyen résultant de la prescription (art. 2247 C. civ.). Devant le tribunal judiciaire, le juge de la mise en état est seul compétent pour statuer sur les fins de non recevoir (art. 789, 6°) ; il peut toutefois, si la complexité du moyen ou l'état de l'instruction le justifie, décider par mesure d'administration judiciaire qu'elle sera examinée par la formation de jugement, les parties devant alors la reprendre dans leurs conclusions au fond (art. 789, dernier alinéa). Après l'ordonnance de clôture, une fin de non recevoir n'est recevable que si sa cause survient ou est révélée postérieurement (art. 802).","Application. Le fait d'avoir conclu au fond ne fait pas obstacle à la prescription, qui n'est pas soumise à l'exigence d'antériorité de l'article 74. La société doit cependant saisir le juge de la mise en état par des conclusions qui lui sont spécialement adressées, avant la clôture. Le juge ne pouvant relever la prescription d'office, l'initiative lui appartient. Sur le fond du moyen, le délai dépend du fondement de l'action : l'action en garantie des vices cachés doit être intentée dans les deux ans de la découverte du vice (art. 1648 C. civ.) ; une action fondée sur le droit commun se prescrit par cinq ans à compter du jour où le titulaire a connu ou aurait dû connaître les faits (art. 2224 C. civ.).","Conclusion. Le moyen reste recevable devant le juge de la mise en état. Son succès dépend de la date à laquelle M. Lambert a découvert le défaut : une découverte récente rendrait l'action recevable, une découverte ancienne exposerait la demande à l'irrecevabilité. Point de vigilance : depuis le décret n° 2024-673, l'article 789 ne prévoit plus expressément l'irrecevabilité des fins de non recevoir non soumises au juge de la mise en état ; la question de leur recevabilité devant la formation de jugement est débattue, ce qui commande de les présenter à ce juge."]}]},{"c":"vro","titre":"Le délai d'appel d'un plaideur domicilié à l'étranger","enonce":"Mme Durand, domiciliée à Montréal, a été condamnée par un jugement contradictoire du tribunal judiciaire de Nantes, statuant en matière contentieuse sur une demande de 40 000 euros. Le jugement lui a été signifié le jeudi 1er octobre 2026. Son avocat envisage de faire appel mais hésite sur le délai. Il prépare par ailleurs une déclaration d'appel qui se borne à indiquer que l'appel tend à la réformation du jugement, sans viser les chefs critiqués.","questions":[{"q":"Jusqu'à quelle date l'appel peut il être formé ?","corr":["Problème. Il faut déterminer le délai d'appel applicable à une partie demeurant à l'étranger, puis en calculer le terme en appliquant les règles de computation.","Règle. Le délai de recours par une voie ordinaire est d'un mois en matière contentieuse (art. 538). Il court à compter de la notification du jugement (art. 528), à condition que l'acte de notification indique de manière très apparente le délai et les modalités du recours (art. 680). Lorsque la juridiction a son siège en France métropolitaine, le délai d'appel est augmenté de deux mois pour les personnes qui demeurent à l'étranger (art. 643). Un délai exprimé en mois expire le jour du dernier mois qui porte le même quantième que le jour de la notification (art. 641, al. 2). Tout délai expire le dernier jour à vingt quatre heures ; celui qui expirerait un samedi, un dimanche ou un jour férié ou chômé est prorogé jusqu'au premier jour ouvrable suivant (art. 642).","Application. Le jugement est contradictoire et rendu en matière contentieuse sur une demande de 40 000 euros : il est susceptible d'appel. Mme Durand demeure à Montréal et le tribunal judiciaire de Nantes siège en métropole : le délai est de trois mois. À compter du 1er octobre 2026, il expire au même quantième, soit le 1er janvier 2027. Ce jour est férié ; il est suivi du samedi 2 et du dimanche 3 janvier. Le délai est donc prorogé jusqu'au lundi 4 janvier 2027. Ce calcul suppose que la signification soit régulière et comporte les mentions de l'article 680 ; à défaut, le délai n'aurait pas couru.","Conclusion. L'appel peut être formé jusqu'au lundi 4 janvier 2027 à vingt quatre heures. La déclaration d'appel étant remise par voie électronique à peine d'irrecevabilité (art. 930-1), l'avocat a intérêt à ne pas attendre le dernier jour. Le calcul peut être vérifié dans le calculateur de l'application."]},{"q":"Quelles sont les conséquences d'une déclaration d'appel qui ne vise aucun chef critiqué ?","corr":["Problème. La déclaration d'appel se borne à solliciter la réformation du jugement : il faut déterminer si elle saisit la cour et comment régulariser.","Règle. L'appel défère à la cour la connaissance des chefs du dispositif du jugement qu'il critique expressément et de ceux qui en dépendent ; la dévolution opère pour le tout lorsque l'appel tend à l'annulation du jugement (art. 562). La déclaration d'appel doit mentionner, à peine de nullité, les chefs du jugement critiqués auxquels l'appel est limité (art. 901). La Cour de cassation juge qu'une déclaration d'appel qui ne mentionne pas les chefs critiqués ne produit aucun effet dévolutif (Cass. 2e civ., 2 juill. 2020, n° 19-16.954). Depuis le 1er septembre 2024, l'appelant peut compléter, retrancher ou rectifier les chefs critiqués dans le dispositif de ses premières conclusions remises dans les délais ; la cour est saisie des chefs ainsi déterminés (art. 915-2).","Application. L'appel tend à la réformation et non à l'annulation : la dévolution pour le tout ne joue pas. La déclaration envisagée, sans chef critiqué, exposerait Mme Durand à l'absence d'effet dévolutif. Deux voies de régularisation sont ouvertes : former une nouvelle déclaration d'appel visant les chefs critiqués tant que le délai d'appel n'est pas expiré ; ou, depuis la réforme de 2024, préciser les chefs critiqués dans le dispositif des premières conclusions remises dans le délai de l'article 908.","Conclusion. L'avocat doit, par prudence, viser dès la déclaration d'appel chacun des chefs du dispositif critiqués, au besoin dans une annexe. S'il a déjà déposé une déclaration lacunaire, il la régularise par une nouvelle déclaration avant le 4 janvier 2027 ou dans ses premières conclusions. Il doit en outre présenter, dès ces premières conclusions, l'ensemble de ses prétentions sur le fond, à peine d'irrecevabilité relevée d'office (art. 915-2)."]},{"q":"Dans quel délai l'appelante devra t elle conclure si l'affaire suit la procédure avec mise en état ?","corr":["Problème. Il faut identifier le délai imparti à l'appelante pour remettre ses conclusions, et la sanction de son inobservation, selon le circuit procédural suivi.","Règle. Dans la procédure avec mise en état, l'appelant dispose d'un délai de trois mois à compter de la déclaration d'appel pour remettre ses conclusions au greffe, à peine de caducité de la déclaration d'appel relevée d'office (art. 908). L'intimé dispose ensuite de trois mois à compter de la notification des conclusions de l'appelant pour conclure et former, le cas échéant, appel incident ou provoqué, à peine d'irrecevabilité relevée d'office (art. 909). En procédure à bref délai, l'appelant dispose de deux mois à compter de la réception de l'avis de fixation, et l'intimé de deux mois à compter de la notification des conclusions de l'appelant (art. 906-2). Ces délais sont augmentés de deux mois si l'appelant demeure à l'étranger (art. 915-4). Les conclusions sont remises par voie électronique (art. 930-1).","Application. L'affaire suit la procédure avec mise en état : Mme Durand devra remettre ses conclusions dans les trois mois de sa déclaration d'appel. Ces conclusions devront contenir l'ensemble de ses prétentions sur le fond et, le cas échéant, préciser les chefs critiqués (art. 915-2). Demeurant à Montréal, elle bénéficie de l'augmentation de deux mois de l'article 915-4, distincte de celle de l'article 643 qui ne vise que les délais de comparution et de recours : son délai pour conclure est donc de cinq mois.","Conclusion. L'appelante devra conclure dans les cinq mois de la déclaration d'appel (trois mois augmentés de deux mois), à peine de caducité. Si la déclaration est remise le 4 janvier 2027, le délai expirera le vendredi 4 juin 2027 à vingt quatre heures. En procédure à bref délai, le délai aurait été de quatre mois à compter de la réception de l'avis de fixation. Point de vigilance : l'intimé demeurant en France ne bénéficie d'aucune augmentation."]}]},{"c":"urg","titre":"Le mur du voisin","enonce":"M. Petit constate que son voisin, M. Garnier, vient d'édifier un mur qui empiète de quarante centimètres sur son terrain, selon un ancien plan de bornage. Il souhaite obtenir rapidement la démolition, mais craint de ne pouvoir prouver l'empiètement. Il a par ailleurs enregistré à son insu une conversation au cours de laquelle M. Garnier reconnaît avoir « un peu débordé ».","questions":[{"q":"Quelle voie permet d'obtenir rapidement la démolition, et à quelles conditions ?","corr":["Problème. M. Petit souhaite une décision rapide : il faut déterminer si le juge des référés peut ordonner la démolition d'un ouvrage empiétant, alors que le défendeur contestera vraisemblablement l'empiètement.","Règle. Le président du tribunal judiciaire peut toujours, même en présence d'une contestation sérieuse, prescrire en référé les mesures conservatoires ou de remise en état qui s'imposent, soit pour prévenir un dommage imminent, soit pour faire cesser un trouble manifestement illicite (art. 835, al. 1). L'urgence n'est pas une condition de ce pouvoir, à la différence du référé de l'article 834. L'ordonnance est une décision provisoire (art. 484), qui n'a pas au principal l'autorité de la chose jugée (art. 488) ; le juge peut l'assortir d'une astreinte et s'en réserver la liquidation (art. 491). Sur le fond, nul ne peut être contraint de céder sa propriété (art. 545 C. civ.) : la jurisprudence en déduit que l'empiètement, même minime, justifie la démolition de la partie de l'ouvrage qui empiète.","Application. Un mur édifié sur le terrain d'autrui constitue une atteinte au droit de propriété susceptible de caractériser un trouble manifestement illicite. La difficulté tient à l'évidence requise : le juge des référés doit constater l'empiètement avec certitude. Un ancien plan de bornage peut y suffire s'il est précis et non contesté ; à défaut, le juge refusera d'ordonner une mesure aussi radicale. Le juge compétent est celui du lieu de l'immeuble, compétence exclusive en matière réelle immobilière (art. 44).","Conclusion. M. Petit peut saisir le président du tribunal judiciaire en référé sur le fondement de l'article 835, alinéa 1, en sollicitant la démolition sous astreinte. Le succès dépend de la preuve de l'empiètement : à défaut d'évidence, il devra d'abord faire établir les faits par une mesure d'instruction, puis agir au fond."]},{"q":"Comment établir la preuve de l'empiètement avant tout procès au fond ?","corr":["Problème. Il incombe à M. Petit de prouver les faits nécessaires au succès de sa prétention (art. 9). Il faut déterminer comment obtenir, avant tout procès, une mesure technique établissant la ligne divisoire.","Règle. S'il existe un motif légitime de conserver ou d'établir avant tout procès la preuve de faits dont pourrait dépendre la solution d'un litige, les mesures d'instruction légalement admissibles peuvent être ordonnées à la demande de tout intéressé, sur requête ou en référé (art. 145). Le référé suppose un débat contradictoire. La requête n'est possible que si les circonstances exigent que la mesure ne soit pas prise contradictoirement (art. 493 et 875), ce que le requérant doit justifier. La mesure doit être utile à un litige potentiel, et non à un procès déjà engagé au fond.","Application. Le litige futur est caractérisé : M. Petit envisage une action en démolition. La solution dépend de la position exacte de la limite séparative, que seule une mesure technique peut établir : expertise confiée à un géomètre expert ou constatations. Rien ne justifie de priver M. Garnier du débat contradictoire, le mur étant déjà construit et ne risquant pas de disparaître : la voie du référé s'impose. Les deux demandes peuvent être présentées dans la même assignation, à titre principal la démolition (art. 835) et à titre subsidiaire l'expertise (art. 145).","Conclusion. M. Petit peut obtenir en référé une expertise sur le fondement de l'article 145. Le rapport lui permettra soit de revenir devant le juge des référés avec un trouble devenu manifeste, soit d'agir au fond en démolition. Une action en bornage peut également être envisagée si la limite est incertaine."]},{"q":"L'enregistrement clandestin est il recevable ?","corr":["Problème. M. Petit dispose d'un enregistrement réalisé à l'insu de son voisin : il faut savoir si cette preuve, obtenue de manière déloyale, peut être produite.","Règle. L'Assemblée plénière a abandonné le principe d'irrecevabilité de la preuve déloyale : dans un procès civil, l'illicéité ou la déloyauté dans l'obtention d'un moyen de preuve ne conduit pas nécessairement à l'écarter. Le juge doit apprécier si l'utilisation de cette preuve porte atteinte au caractère équitable de la procédure dans son ensemble, en mettant en balance le droit à la preuve et les droits antinomiques en présence ; le droit à la preuve peut justifier la production d'éléments portant atteinte à d'autres droits à condition que cette production soit indispensable à son exercice et que l'atteinte soit strictement proportionnée au but poursuivi (Ass. plén., 22 déc. 2023, n° 20-20.648).","Application. L'enregistrement porte atteinte à la vie privée de M. Garnier et a été obtenu par un procédé déloyal. Son caractère indispensable est discutable : la preuve de l'empiètement peut être rapportée par des moyens loyaux, plan de bornage ou expertise. En outre, la phrase enregistrée (« un peu débordé ») est imprécise et n'établit pas l'ampleur de l'empiètement. Le juge pourrait donc écarter la pièce.","Conclusion. La recevabilité de l'enregistrement est incertaine. Il convient de fonder la demande sur des preuves loyales et de ne produire l'enregistrement qu'à titre subsidiaire, en justifiant précisément de son caractère indispensable et proportionné."]}]},{"c":"m2","titre":"Le voisin récalcitrant et la médiation","enonce":"Mme Bernard a assigné son voisin, M. Leroy, devant le tribunal judiciaire en démolition d'un abri de jardin et en paiement de 4 000 euros de dommages et intérêts. Le juge de la mise en état enjoint aux parties de rencontrer un médiateur pour une réunion d'information. M. Leroy ne s'y rend pas, sans explication. Quelques semaines plus tard, les parties envisagent finalement un accord, mais s'inquiètent de la confidentialité des échanges et de la manière de rendre l'accord exécutoire.","questions":[{"q":"M. Leroy peut il contester l'injonction, et que risque t il ?","corr":["Problème. Il faut déterminer la nature de l'injonction de rencontrer un médiateur, les recours ouverts contre elle et la sanction de l'absence à la réunion d'information.","Règle. Le juge peut enjoindre aux parties de rencontrer un conciliateur de justice ou un médiateur, qui les informe sur l'objet et le déroulement du processus. Depuis le décret n° 2026-683, cette injonction est expressément une mesure d'administration judiciaire, insusceptible de recours (art. 1533). Le tiers informe le juge de l'absence d'une partie à la réunion d'information. La partie qui, sans motif légitime, n'a pas déféré à l'injonction peut être condamnée à une amende civile d'un maximum de 10 000 euros (art. 1533-3). Cette amende sanctionne l'absence à la réunion d'information, non le refus d'entrer en médiation, la médiation demeurant un processus consensuel.","Application. M. Leroy ne peut former aucun recours contre l'injonction, mesure d'administration judiciaire. Il ne s'est pas rendu à la réunion sans fournir d'explication : faute de motif légitime, il s'expose à l'amende civile, dont le juge apprécie le montant dans la limite du plafond. Il pourrait éviter la sanction en justifiant d'un motif légitime, tel un empêchement sérieux. Il reste libre, en revanche, de refuser d'entrer en médiation après avoir été informé.","Conclusion. M. Leroy ne peut contester l'injonction et encourt une amende civile d'un montant maximal de 10 000 euros. Il ne peut être contraint d'entrer en médiation. La sanction a été critiquée, le Conseil national des barreaux y voyant une mesure disproportionnée et contraire à la nature consensuelle de l'amiable."]},{"q":"Ce que les parties se diront en médiation pourra t il être invoqué devant le juge en cas d'échec ?","corr":["Problème. Les parties craignent que leurs concessions soient utilisées contre elles si la médiation échoue : il faut déterminer l'étendue de la confidentialité.","Règle. Sauf accord contraire des parties, tout ce qui est dit, écrit ou fait au cours de l'audience de règlement amiable, d'une conciliation confiée à un conciliateur de justice ou d'une médiation est confidentiel (art. 1528-3). Seuls les documents élaborés pendant le processus, comme les projets d'accord ou les déclarations écrites, sont couverts ; les pièces produites ne le sont pas, afin de préserver le droit à la preuve. La confidentialité légale ne s'applique ni à la procédure participative aux fins de règlement amiable ni à la conciliation menée par le juge en dehors de l'audience de règlement amiable.","Application. Les propositions de M. Leroy, ses éventuels aveux et les projets d'accord ne pourront être produits devant le juge si la médiation échoue. En revanche, les pièces existantes, tels des photographies de l'abri ou un plan cadastral, restent utilisables par chacune des parties. Les parties peuvent, d'un commun accord, lever la confidentialité, par exemple pour produire l'accord en vue de son homologation.","Conclusion. Les échanges et documents élaborés au cours de la médiation ne pourront être invoqués. Les parties peuvent négocier librement, sans craindre que leurs concessions soient retenues contre elles, mais doivent conserver leurs pièces, qui demeurent produisibles."]},{"q":"Comment rendre l'accord exécutoire ?","corr":["Problème. Un accord amiable n'a qu'une force contractuelle : il faut identifier les moyens de lui conférer force exécutoire.","Règle. L'accord issu d'une médiation peut être homologué par le juge, à la demande de l'ensemble des parties ou de l'une d'elles avec l'accord exprès des autres ; le juge contrôle sa licéité et sa conformité à l'ordre public sans pouvoir en modifier les termes (art. 1543 et 1544). Les accords auxquels les juridictions ont conféré force exécutoire constituent des titres exécutoires (art. L. 111-3, 1° CPCE). L'accord constaté dans un acte contresigné par les avocats de chacune des parties peut aussi être revêtu de la formule exécutoire par le greffe (art. L. 111-3, 7° CPCE).","Application. L'instance étant pendante, les parties peuvent solliciter l'homologation du juge saisi. L'homologation éteint l'instance et confère à l'accord force exécutoire : Mme Bernard pourra faire procéder à la démolition ou au paiement par un commissaire de justice en cas d'inexécution. Si les deux parties sont assistées d'avocats, la voie de l'acte contresigné revêtu de la formule exécutoire est également ouverte, sans contrôle juridictionnel.","Conclusion. Les parties peuvent présenter au juge une requête en homologation, conjointe ou formée par l'une avec l'accord exprès de l'autre, ou faire contresigner l'accord par leurs avocats en vue de l'apposition de la formule exécutoire par le greffe."]},{"q":"Quel est l'effet de la médiation sur l'instance en cours ?","corr":["Problème. Il faut déterminer si le temps consacré à la médiation expose l'instance à la péremption et quelle est la durée de la mesure.","Règle. L'instance est périmée lorsque aucune des parties n'accomplit de diligences pendant deux ans (art. 386). La médiation ordonnée par le juge interrompt la péremption ; un nouveau délai court à l'expiration de la durée fixée ou à la date à laquelle le juge constate la fin du processus (art. 1534 et 1535-5). La durée initiale de la médiation judiciaire est de cinq mois, suivie le cas échéant d'une période de trois mois (art. 1534-4). Lorsque l'ordonnance est à double détente, le consentement des parties doit, depuis le 1er octobre 2026, intervenir dans un délai de trois mois, sauf délai différent fixé par le juge (art. 1534-1).","Application. Si la médiation est ordonnée, l'instance n'est pas exposée à la péremption pendant son déroulement, et un délai de deux ans recommencera à courir à son terme. La médiation peut s'étendre sur cinq mois, éventuellement prolongés de trois mois.","Conclusion. La médiation ne fait courir aucun risque de péremption. En cas d'accord, l'homologation mettra fin à l'instance ; en cas d'échec, l'instance reprendra son cours devant le juge de la mise en état."]}]},{"c":"a2","titre":"La clause compromissoire contestée","enonce":"La société Batinor, entreprise de construction établie à Lille, a conclu avec M. Faure, particulier, un contrat de rénovation de sa maison comportant une clause compromissoire. Elle a conclu par ailleurs un contrat de fourniture avec la société Acierlux, établie en Belgique, également assorti d'une clause compromissoire désignant un arbitre unique. Un litige survient avec chacun de ses cocontractants. M. Faure saisit le tribunal judiciaire. La société Acierlux, de son côté, saisit également le tribunal judiciaire en soutenant que le contrat de fourniture est nul pour dol, ce qui entraînerait selon elle la nullité de la clause. Un arbitre est finalement désigné dans le second litige ; on apprend après la sentence qu'il conseillait régulièrement la société Batinor.","questions":[{"q":"La clause compromissoire peut elle être opposée à M. Faure ?","corr":["Problème. Il s'agit de déterminer si une clause compromissoire stipulée dans un contrat conclu entre un professionnel et un particulier peut être opposée à ce dernier, qui a saisi le juge étatique.","Règle. La clause compromissoire est la convention par laquelle les parties à un contrat s'engagent à soumettre à l'arbitrage les litiges qui pourraient naître relativement à ce contrat (art. 1442). Elle doit avoir été acceptée par la partie à laquelle on l'oppose ; lorsque l'une des parties n'a pas contracté dans le cadre de son activité professionnelle, la clause ne peut lui être opposée (art. 2061 C. civ.). La règle protège le non professionnel sans frapper la clause de nullité : celui ci peut s'en prévaloir s'il le souhaite.","Application. M. Faure a conclu le contrat de rénovation de sa maison en qualité de particulier, en dehors de toute activité professionnelle. La clause ne peut donc lui être opposée par la société Batinor. Le tribunal judiciaire, valablement saisi, ne pourra se déclarer incompétent au profit de l'arbitrage sur le fondement de la clause. M. Faure conserve toutefois la faculté d'invoquer lui même la clause, ou de conclure un compromis une fois le litige né.","Conclusion. La clause est inopposable à M. Faure. Si la société Batinor soulevait l'incompétence du tribunal en se fondant sur elle, l'exception serait rejetée."]},{"q":"Le tribunal judiciaire saisi par la société Acierlux doit il examiner la validité de la clause ?","corr":["Problème. Une partie saisit le juge étatique en soutenant que la nullité du contrat principal emporte celle de la clause compromissoire : il faut déterminer l'étendue du contrôle du juge étatique.","Règle. L'arbitrage est international lorsqu'il met en cause des intérêts du commerce international (art. 1504). La convention d'arbitrage est indépendante du contrat auquel elle se rapporte et n'est pas affectée par l'inefficacité de celui ci (art. 1447, applicable en matière internationale par l'article 1506). Lorsqu'un litige relevant d'une convention d'arbitrage est porté devant une juridiction de l'État, celle ci se déclare incompétente, sauf si le tribunal arbitral n'est pas encore saisi et si la convention est manifestement nulle ou manifestement inapplicable ; elle ne peut relever d'office son incompétence (art. 1448). Le tribunal arbitral est seul compétent pour statuer sur les contestations relatives à son pouvoir juridictionnel (art. 1465).","Application. Le contrat de fourniture entre une société française et une société belge met en cause des intérêts du commerce international : l'arbitrage est international. Le dol allégué vise le contrat principal ; en vertu du principe d'autonomie, il n'affecte pas la clause. Celle ci n'est donc pas manifestement nulle, et la société Batinor peut soulever l'incompétence du tribunal judiciaire, qui ne pourrait la relever d'office. Le juge étatique se limite à un contrôle de l'apparence ; il n'examine pas au fond la validité de la clause.","Conclusion. Le tribunal judiciaire doit se déclarer incompétent si la société Batinor soulève l'exception. Il appartiendra à l'arbitre de statuer sur sa propre compétence, sous le contrôle ultérieur du juge de l'annulation."]},{"q":"Quel recours contre la sentence, compte tenu des liens entre l'arbitre et la société Batinor ?","corr":["Problème. L'arbitre n'a pas révélé ses liens d'affaires avec l'une des parties : il faut identifier le recours ouvert contre la sentence internationale rendue en France et le grief invocable.","Règle. Il appartient à l'arbitre, avant d'accepter sa mission, de révéler toute circonstance susceptible d'affecter son indépendance ou son impartialité, et de révéler sans délai toute circonstance de même nature survenue après l'acceptation (art. 1456, applicable par l'article 1506). La sentence rendue en France en matière d'arbitrage international ne peut faire l'objet que d'un recours en annulation (art. 1518), porté devant la cour d'appel de Paris dans le mois de la signification de la sentence (art. 1519). Le recours n'est ouvert que dans les cas limitativement énumérés, notamment lorsque le tribunal arbitral a été irrégulièrement constitué (art. 1520, 2°). La partie qui, en connaissance de cause et sans motif légitime, s'abstient d'invoquer en temps utile une irrégularité est réputée y avoir renoncé (art. 1466). Le recours n'est pas suspensif (art. 1526).","Application. Un courant d'affaires régulier entre l'arbitre et la société Batinor constitue une circonstance susceptible d'affecter son indépendance, qui devait être révélée. La société Acierlux ne l'a découverte qu'après la sentence : la renonciation de l'article 1466 ne peut lui être opposée. Le grief de constitution irrégulière du tribunal arbitral est donc invocable.","Conclusion. La société Acierlux peut former un recours en annulation devant la cour d'appel de Paris dans le mois de la signification de la sentence. Le recours n'étant pas suspensif, la sentence revêtue de l'exequatur pourra être exécutée dans l'intervalle, sauf décision du premier président ou du conseiller de la mise en état si l'exécution est susceptible de léser gravement ses droits (art. 1526). En cas d'annulation, le litige devra être soumis à un nouveau tribunal arbitral."]}]},{"c":"e4","titre":"Le créancier pressé","enonce":"M. Robert a obtenu un jugement du tribunal judiciaire, signifié et assorti de l'exécution provisoire, condamnant Mme Lenoir à lui payer 18 000 euros. Mme Lenoir ne paie pas. M. Robert apprend qu'elle détient un compte bancaire, qu'elle perçoit un salaire et qu'elle s'apprête à vendre sa voiture. Par ailleurs, il dispose contre M. Simon, un ancien associé, d'une créance de 7 000 euros non constatée par un titre, et craint que celui ci n'organise son insolvabilité.","questions":[{"q":"Quelles mesures M. Robert peut il pratiquer contre Mme Lenoir ?","corr":["Problème. Muni d'un jugement exécutoire, M. Robert veut recouvrer sa créance : il faut vérifier qu'il peut engager l'exécution forcée, puis choisir les saisies adaptées aux biens de la débitrice.","Règle. Tout créancier muni d'un titre exécutoire constatant une créance liquide et exigible peut en poursuivre l'exécution forcée (art. L. 111-2 CPCE). Constituent notamment des titres exécutoires les décisions des juridictions judiciaires lorsqu'elles ont force exécutoire (art. L. 111-3, 1°). Le créancier a le choix des mesures, dont l'exécution ne peut excéder ce qui est nécessaire pour obtenir le paiement (art. L. 111-7). La saisie attribution permet de saisir entre les mains d'un tiers les créances de somme d'argent du débiteur (art. L. 211-1) et emporte attribution immédiate des sommes saisies (art. L. 211-2) ; la banque doit laisser au débiteur personne physique une somme à caractère alimentaire égale au montant forfaitaire du revenu de solidarité active pour un allocataire seul (art. L. 162-2). La saisie des rémunérations peut être pratiquée un mois après la signification d'un commandement, inscrit par le commissaire de justice sur le registre numérique des saisies des rémunérations (art. L. 212-2). La saisie vente des meubles corporels suppose la signification préalable d'un commandement de payer dans les huit jours (art. L. 221-1 et R. 221-1).","Application. Le jugement signifié et assorti de l'exécution provisoire est un titre exécutoire ; la créance de 18 000 euros est liquide et exigible. M. Robert peut pratiquer une saisie attribution sur le compte bancaire, sous réserve du solde bancaire insaisissable ; une saisie des rémunérations, après commandement et délai d'un mois ; une saisie vente du véhicule, après commandement de payer. L'urgence tient à la vente annoncée de la voiture : le commandement de saisie vente doit être signifié sans attendre. Le cumul des mesures doit rester proportionné au montant de la créance.","Conclusion. La saisie attribution du compte est la mesure la plus rapide, son effet attributif étant immédiat ; elle doit être dénoncée à Mme Lenoir par acte de commissaire de justice dans les huit jours, à peine de caducité (art. R. 211-3). M. Robert peut y joindre une saisie vente du véhicule et, si le compte est insuffisamment provisionné, une saisie des rémunérations. Point de vigilance : l'exécution d'une décision exécutoire à titre provisoire se fait aux risques du créancier, qui devra restituer si la décision est infirmée (art. L. 111-10)."]},{"q":"Mme Lenoir peut elle obtenir des délais ou contester ?","corr":["Problème. Il faut déterminer les pouvoirs du juge de l'exécution face aux demandes de la débitrice : délais de paiement, contestation de la saisie, remise en cause de la condamnation.","Règle. Le juge de l'exécution ne peut ni modifier le dispositif de la décision de justice qui sert de fondement aux poursuites, ni en suspendre l'exécution ; toutefois, après signification du commandement ou de l'acte de saisie, il a compétence pour accorder un délai de grâce (art. R. 121-1 CPCE). Le juge peut, compte tenu de la situation du débiteur et des besoins du créancier, reporter ou échelonner le paiement dans la limite de deux années (art. 1343-5 C. civ.). Les contestations relatives à la saisie attribution sont formées dans le délai d'un mois à compter de sa dénonciation, à peine d'irrecevabilité, et dénoncées le même jour ou au plus tard le premier jour ouvrable suivant au commissaire de justice qui a procédé à la saisie (art. R. 211-11).","Application. Mme Lenoir peut saisir le juge de l'exécution d'une demande de délais, après signification d'un commandement ou d'un acte de saisie, en justifiant de sa situation. Elle peut contester la régularité de la saisie attribution, par exemple une irrégularité de l'acte de dénonciation, dans le mois de cette dénonciation. Elle ne peut, en revanche, contester devant le juge de l'exécution le bien fondé de sa condamnation : cette contestation relève de l'appel contre le jugement. Elle peut aussi demander au premier président d'arrêter l'exécution provisoire, si elle a fait appel et justifie d'un moyen sérieux d'annulation ou de réformation et d'un risque de conséquences manifestement excessives (art. 514-3 CPC).","Conclusion. Mme Lenoir peut solliciter des délais de grâce dans la limite de deux ans et contester la régularité des saisies devant le juge de l'exécution, mais non remettre en cause la condamnation elle même."]},{"q":"Que peut faire M. Robert contre M. Simon ?","corr":["Problème. M. Robert ne dispose d'aucun titre exécutoire contre M. Simon, mais craint son insolvabilité : il faut déterminer s'il peut immobiliser ses biens avant d'obtenir un titre.","Règle. Toute personne dont la créance paraît fondée en son principe peut solliciter du juge l'autorisation de pratiquer une mesure conservatoire sur les biens de son débiteur, sans commandement préalable, si elle justifie de circonstances susceptibles d'en menacer le recouvrement ; la mesure prend la forme d'une saisie conservatoire ou d'une sûreté judiciaire (art. L. 511-1 CPCE). L'autorisation est caduque si la mesure n'est pas exécutée dans les trois mois de l'ordonnance (art. R. 511-6). Sauf si la mesure a été pratiquée avec un titre exécutoire, le créancier doit, dans le mois de son exécution et à peine de caducité, introduire une procédure ou accomplir les formalités nécessaires à l'obtention d'un titre exécutoire (art. R. 511-7).","Application. La créance de 7 000 euros paraît fondée en son principe si M. Robert en justifie par des écrits, comme une reconnaissance de dette ou des échanges. La crainte d'une organisation d'insolvabilité doit être étayée par des éléments concrets, comme la mise en vente de biens. M. Robert présente une requête au juge de l'exécution (art. R. 511-1), qui statue sans débat contradictoire. Il fait ensuite pratiquer la saisie conservatoire dans les trois mois, par exemple sur les comptes bancaires de M. Simon.","Conclusion. M. Robert peut obtenir l'autorisation de pratiquer une saisie conservatoire, puis doit, dans le mois de son exécution, engager une action au fond ou une procédure d'injonction de payer. Une fois le titre obtenu, la saisie conservatoire de créances pourra être convertie en saisie attribution par un acte de conversion signifié au tiers saisi (art. R. 523-7)."]}]},{"c":"p5","titre":"La vendeuse licenciée","enonce":"Mme Benali, vendeuse depuis six ans dans une boutique de prêt à porter à Rennes, a été licenciée pour faute grave le 4 septembre 2026. Son employeur, dont le siège est à Nantes, ne lui a remis ni son attestation destinée à France Travail, ni son dernier bulletin de paie, ni le salaire d'août. Elle vous consulte le 27 octobre 2026 : elle souhaite contester son licenciement et obtenir rapidement ses documents et son salaire.","questions":[{"q":"Quel conseil de prud'hommes saisir, comment et dans quel délai ?","corr":["Problème. Il faut identifier le conseil territorialement compétent, les formes de la saisine depuis la réforme du 1er octobre 2026 et les délais de prescription applicables aux différentes demandes.","Règle. Le conseil de prud'hommes est seul compétent pour connaître des différends nés du contrat de travail, quel que soit le montant de la demande (art. L. 1411-4 C. trav.). Le conseil territorialement compétent est celui dans le ressort duquel est situé l'établissement où est accompli le travail ; le salarié peut aussi saisir le conseil du lieu où l'engagement a été contracté ou celui du lieu où l'employeur est établi (art. R. 1412-1). La demande est formée par requête, faite, remise ou adressée au greffe ; la saisine, même d'un conseil incompétent, interrompt la prescription (art. R. 1452-1). La requête comporte les mentions de l'article 57 du code de procédure civile, un exposé sommaire des motifs et chacun des chefs de demande (art. R. 1452-2). Pour les instances introduites à compter du 1er octobre 2026, elle est accompagnée du bordereau des pièces et du dernier bulletin de salaire ou, à défaut, d'une pièce permettant d'identifier l'activité de l'employeur ; les pièces sont communiquées entre les parties (décret n° 2026-683). L'action portant sur la rupture se prescrit par douze mois à compter de sa notification (art. L. 1471-1) ; l'action en paiement du salaire, par trois ans (art. L. 3245-1).","Application. Mme Benali travaille à Rennes : le conseil de Rennes est compétent, celui de Nantes l'étant aussi au titre du siège de l'employeur. La section compétente est celle du commerce et des services commerciaux. La requête énumérera chaque chef de demande : contestation de la faute grave, indemnités de préavis et de licenciement, dommages et intérêts pour licenciement sans cause réelle et sérieuse, rappel du salaire d'août, remise des documents. À défaut de dernier bulletin, elle joindra une pièce identifiant l'activité de l'employeur, comme un extrait du registre du commerce. Elle acquittera la contribution pour l'aide juridique de 50 euros, sauf si elle bénéficie de l'aide juridictionnelle (art. 1635 bis Q CGI).","Conclusion. Mme Benali peut saisir le conseil de Rennes par requête. Elle dispose de douze mois à compter de la notification du licenciement pour le contester, soit jusqu'en septembre 2027, et de trois ans pour le salaire. Elle a toutefois intérêt à agir sans tarder, afin d'obtenir rapidement les mesures provisoires. Elle peut se défendre seule, ou se faire assister ou représenter, notamment par un avocat ou un défenseur syndical (art. R. 1453-2)."]},{"q":"Peut elle obtenir ses documents et son salaire avant le jugement ?","corr":["Problème. La salariée a besoin de ses documents de fin de contrat et de son salaire sans attendre le jugement au fond : il faut identifier les formations susceptibles d'ordonner des mesures provisoires et leurs limites.","Règle. Même en présence d'une exception de procédure et même si le défendeur ne comparaît pas, le bureau de conciliation et d'orientation peut ordonner la délivrance, le cas échéant sous peine d'astreinte, des certificats de travail, bulletins de paie et toute pièce que l'employeur est tenu légalement de délivrer ; lorsque l'existence de l'obligation n'est pas sérieusement contestable, il peut ordonner le versement de provisions sur les salaires et accessoires, sur les indemnités de congés payés, de préavis et de licenciement (art. R. 1454-14 C. trav.). Le total des provisions ne peut excéder six mois de salaire calculés sur la moyenne des trois derniers mois (art. R. 1454-15). Ces décisions sont provisoires, exécutoires par provision et ne peuvent être attaquées qu'avec le jugement sur le fond (art. R. 1454-16). Indépendamment de la conciliation, la formation de référé peut ordonner, en cas d'urgence, les mesures qui ne se heurtent à aucune contestation sérieuse, et accorder une provision lorsque l'obligation n'est pas sérieusement contestable (art. R. 1455-5 et R. 1455-7).","Application. L'attestation destinée à France Travail et le bulletin de paie sont des documents que l'employeur doit légalement remettre : le bureau peut en ordonner la délivrance sous astreinte. Le salaire d'août correspond à une période travaillée, antérieure au licenciement : l'obligation n'est pas sérieusement contestable. En revanche, les indemnités de préavis et de licenciement dépendent de l'appréciation de la faute grave, que l'employeur conteste ; elles se heurtent à une contestation sérieuse et ne pourront être accordées à titre provisionnel. Si la séance de conciliation est fixée à une date lointaine, la saisine de la formation de référé permet d'obtenir plus rapidement les documents et la provision.","Conclusion. Mme Benali doit demander, dès la séance de conciliation ou en référé, la remise des documents sous astreinte et une provision sur le salaire d'août. Les indemnités de rupture devront être discutées au fond."]},{"q":"Si l'employeur ne se présente pas à la conciliation, que peut il se passer ?","corr":["Problème. Il faut déterminer les conséquences de la non comparution du défendeur devant le bureau de conciliation et d'orientation.","Règle. Lorsque, au jour fixé pour la tentative de conciliation, le défendeur ne comparaît pas sans avoir justifié en temps utile d'un motif légitime, il est fait application de l'article L. 1454-1-3 (art. R. 1454-13 C. trav.) : le bureau peut juger l'affaire, en l'état des pièces et moyens que la partie comparante a contradictoirement communiqués, en statuant comme bureau de jugement dans sa composition restreinte. L'affaire peut aussi être renvoyée à une audience ultérieure du bureau de jugement dans sa composition restreinte, le greffier avisant par tous moyens la partie qui ne l'a pas été verbalement (art. R. 1454-17). La convocation du défendeur l'avertit que des décisions exécutoires à titre provisoire peuvent être prises contre lui en cas de non comparution et qu'il pourra être statué en l'état des pièces communiquées (art. R. 1452-4).","Application. Si l'employeur ne se présente pas sans motif légitime, le bureau peut juger immédiatement l'affaire, à condition que Mme Benali ait communiqué ses pièces à l'employeur, ce que la réforme du 1er octobre 2026 rend indispensable puisque les pièces ne sont plus déposées au greffe avec la requête. Le bureau peut aussi, même en l'absence de l'employeur, ordonner les mesures provisoires de l'article R. 1454-14. Le jugement sera réputé contradictoire ou rendu par défaut selon les règles du droit commun (art. 473 CPC).","Conclusion. L'absence de l'employeur ne paralyse pas la procédure : elle peut conduire à un jugement immédiat ou à un renvoi rapide devant la formation restreinte. Mme Benali doit donc avoir adressé ses pièces à l'employeur avant la séance et pouvoir en justifier."]}]},{"c":"p7","titre":"Le salarié sans documents ni salaire","enonce":"M. Caron, cariste dans un entrepôt logistique situé à Orléans, a démissionné le 2 octobre 2026. Son employeur ne lui a versé ni le salaire de septembre, d'un montant de 2 100 euros, ni l'indemnité compensatrice de congés payés, et ne lui a remis aucun document de fin de contrat. Le directeur de l'entrepôt lui a indiqué par courriel qu'il « réglerait tout quand il aurait le temps ». M. Caron, qui vient d'être recruté par une autre entreprise, a besoin de son certificat de travail. Il vous consulte le 28 octobre 2026.","questions":[{"q":"Quelle procédure lui permet d'obtenir rapidement satisfaction, et devant quelle formation ?","corr":["Problème. M. Caron a besoin d'une décision rapide sur des obligations dont l'existence n'est pas discutée : il faut choisir entre la saisine du conseil au fond, avec sa phase de conciliation, et le référé prud'homal.","Règle. Chaque conseil de prud'hommes comprend une formation de référé commune à l'ensemble de ses sections, composée d'un conseiller salarié et d'un conseiller employeur (art. R. 1455-1 C. trav.). Dans tous les cas d'urgence, elle peut ordonner, dans la limite de la compétence du conseil, toutes les mesures qui ne se heurtent à aucune contestation sérieuse ou que justifie l'existence d'un différend (art. R. 1455-5). Dans le cas où l'obligation n'est pas sérieusement contestable, elle peut accorder une provision au créancier ou ordonner l'exécution de l'obligation, même s'il s'agit d'une obligation de faire (art. R. 1455-7). Le référé n'est pas soumis au préalable de conciliation.","Application. Le salaire de septembre correspond à un travail accompli et n'est pas contesté : le courriel du directeur reconnaît même la dette. L'indemnité compensatrice de congés payés est due pour la fraction de congé non prise, que la rupture résulte du fait du salarié ou de l'employeur (art. L. 3141-28). À l'expiration du contrat, l'employeur délivre un certificat de travail (art. L. 1234-19) et les attestations permettant au salarié d'exercer ses droits à l'assurance chômage (art. R. 1234-9). L'urgence est caractérisée par la nouvelle embauche, qui rend le certificat nécessaire, et par la privation de salaire. Aucune contestation sérieuse n'apparaît.","Conclusion. M. Caron doit saisir la formation de référé du conseil de prud'hommes d'Orléans, compétent comme conseil du lieu de l'établissement où le travail était accompli (art. R. 1412-1). Il sollicitera une provision égale au salaire de septembre et à l'indemnité de congés payés, ainsi que la remise des documents de fin de contrat sous astreinte. S'il entend former d'autres demandes, par exemple des dommages et intérêts pour le retard, il devra saisir le conseil au fond, ces demandes excédant les pouvoirs du juge des référés."]},{"q":"Comment saisir la formation de référé, et quelle est la portée de l'ordonnance ?","corr":["Problème. Il faut préciser les modalités de saisine du référé prud'homal et le régime de la décision rendue.","Règle. La demande en référé est formée soit par acte de commissaire de justice, soit par requête dans les conditions de l'article R. 1452-1 ; lorsqu'elle est formée par acte de commissaire de justice, une copie de l'assignation est remise au greffe au plus tard la veille de l'audience ; lorsqu'elle est formée par requête, les articles R. 1452-2 à R. 1452-4 s'appliquent (art. R. 1455-9 C. trav.). Les articles 484, 486, 488 à 492 et 514 du code de procédure civile sont applicables au référé prud'homal (art. R. 1455-10). L'ordonnance de référé est une décision provisoire (art. 484 CPC), qui n'a pas, au principal, l'autorité de la chose jugée et ne peut être modifiée ou rapportée en référé qu'en cas de circonstances nouvelles (art. 488 CPC) ; le juge qui l'assortit d'une astreinte peut s'en réserver la liquidation (art. 491 CPC). Elle est exécutoire à titre provisoire (art. 514 CPC).","Application. M. Caron peut saisir la formation de référé par requête, plus simple et moins coûteuse, en joignant le bordereau des pièces et son dernier bulletin de salaire ou une pièce identifiant l'activité de l'employeur. S'il souhaite une date d'audience certaine, il peut faire délivrer une assignation par commissaire de justice et en remettre la copie au greffe au plus tard la veille de l'audience. Il peut se présenter seul ou se faire assister ou représenter, notamment par un défenseur syndical ou un avocat (art. R. 1453-2). L'ordonnance, exécutoire de droit, permettra de faire procéder à une saisie si l'employeur ne paie pas.","Conclusion. La saisine par requête ou par assignation est possible ; l'ordonnance obtenue sera immédiatement exécutoire, mais provisoire : l'employeur pourra soumettre le litige au juge du fond, sans que cela suspende l'exécution."]},{"q":"L'employeur peut il faire appel, et la formation de référé peut elle renvoyer l'affaire au fond ?","corr":["Problème. Il faut déterminer les voies de recours contre l'ordonnance de référé prud'homale et la possibilité d'un renvoi devant le bureau de jugement.","Règle. Le délai d'appel d'une ordonnance de référé prud'homale est de quinze jours (art. R. 1455-11 C. trav.). L'appel est porté devant la chambre sociale de la cour d'appel et suit la procédure avec représentation obligatoire, les parties étant représentées par un avocat ou un défenseur syndical (art. R. 1461-1 et R. 1461-2). La formation de référé peut, lorsque la demande excède ses pouvoirs et présente une particulière urgence, renvoyer l'affaire devant le bureau de jugement, avec l'accord de toutes les parties et après avoir tenté de les concilier en audience non publique (art. R. 1455-8). L'ordonnance de référé peut être frappée d'appel, à moins qu'elle n'ait été rendue en dernier ressort en raison du montant ou de l'objet de la demande (art. 490 CPC, applicable par l'article R. 1455-10) ; le conseil statue en dernier ressort lorsque la valeur des prétentions ne dépasse pas 5 000 euros ou lorsque la demande tend seulement à la remise de documents (art. R. 1462-1 et D. 1462-3).","Application. Les demandes de M. Caron, salaire et congés payés, sont inférieures à 5 000 euros, et la remise des documents relève du dernier ressort : l'ordonnance sera en principe rendue en dernier ressort et ne pourra faire l'objet que d'un pourvoi en cassation, dans les deux mois (art. 612 CPC). Si M. Caron sollicitait aussi des dommages et intérêts excédant les pouvoirs de la formation, celle ci pourrait renvoyer l'affaire au bureau de jugement, à condition que l'employeur y consente.","Conclusion. Compte tenu du montant, l'appel sera vraisemblablement fermé ; l'employeur ne pourra contester l'ordonnance que par un pourvoi, non suspensif, ou en saisissant le juge du fond. Le renvoi au bureau de jugement suppose l'accord de toutes les parties."]}]},{"c":"p8","titre":"Le départage et l'appel","enonce":"La société Optima, entreprise de services informatiques établie à Lille, a licencié pour insuffisance professionnelle Mme Vasseur, ingénieure. Le bureau de conciliation et d'orientation, faute d'accord, a orienté l'affaire vers le bureau de jugement de la section encadrement. Lors du délibéré, les quatre conseillers n'ont pu se départager. Le juge départiteur a finalement rendu, le 15 octobre 2026, un jugement condamnant la société à verser 38 000 euros de dommages et intérêts pour licenciement sans cause réelle et sérieuse, avec exécution provisoire de droit à hauteur de 9 000 euros de rappel de salaires. Le jugement a été notifié par le greffe à la société le 20 octobre 2026.","questions":[{"q":"Comment s'est déroulé le départage, et le juge départiteur pouvait il statuer seul ?","corr":["Problème. Il faut décrire la procédure suivie en cas de partage des voix et préciser les hypothèses dans lesquelles le juge départiteur statue seul.","Règle. Le bureau de jugement comprend deux conseillers employeurs et deux conseillers salariés (art. L. 1423-12 C. trav.). En cas de partage, l'affaire est renvoyée devant le même bureau de jugement ou la même formation de référé, présidé par un juge du tribunal judiciaire, désigné chaque année par le président du tribunal judiciaire ; l'affaire est reprise dans le délai d'un mois (art. L. 1454-2). L'audience de départage est tenue dans le mois du renvoi ; en référé, elle l'est au plus tard dans les quinze jours (art. R. 1454-29). Si la formation n'est pas réunie au complet, le juge départiteur statue seul après avoir recueilli l'avis des conseillers présents (art. R. 1454-31). Le bureau de conciliation et d'orientation aurait aussi pu, en cas de litige sur un licenciement, renvoyer directement l'affaire devant le bureau de jugement présidé par le juge départiteur (art. L. 1454-1-1).","Application. Le partage des voix au sein du bureau de la section encadrement a entraîné le renvoi de l'affaire devant ce bureau présidé par le juge départiteur, à une audience tenue dans le mois. Le jugement a été rendu par la formation de départage, composée des quatre conseillers et du juge, statuant à la majorité. Si un ou plusieurs conseillers avaient été absents, le juge départiteur aurait pu statuer seul, après avoir recueilli l'avis des conseillers présents.","Conclusion. La procédure est régulière si le renvoi a été fait au juge désigné par le président du tribunal judiciaire et si les conseillers absents, le cas échéant, ont été consultés. Le jugement de départage est un jugement du conseil de prud'hommes, soumis aux voies de recours ordinaires."]},{"q":"Dans quel délai et selon quelles modalités la société peut elle faire appel ?","corr":["Problème. Il faut vérifier que le jugement est susceptible d'appel, puis déterminer le délai, la juridiction et les règles de représentation.","Règle. Le conseil statue en dernier ressort lorsque la valeur totale des prétentions d'aucune des parties ne dépasse 5 000 euros (art. R. 1462-1 et D. 1462-3 C. trav.). Les décisions sont notifiées par le greffe par lettre recommandée avec avis de réception (art. R. 1454-26). Le délai d'appel est d'un mois (art. R. 1461-1) ; il court à compter de la notification (art. 528 CPC) et, exprimé en mois, expire au même quantième (art. 641 CPC). L'appel est porté devant la chambre sociale de la cour d'appel et suit la procédure avec représentation obligatoire ; les parties sont représentées par un défenseur syndical ou constituent avocat (art. R. 1461-1 et R. 1461-2). La déclaration d'appel mentionne les chefs du jugement critiqués (art. 901 CPC), et l'appelant conclut dans les délais de la procédure applicable, à peine de caducité (art. 906-2 ou 908 CPC).","Application. Les prétentions de Mme Vasseur excèdent 5 000 euros : le jugement est rendu en premier ressort. Notifié le 20 octobre 2026, il peut être frappé d'appel jusqu'au 20 novembre 2026 à vingt quatre heures, ce jour étant un vendredi. L'appel sera porté devant la chambre sociale de la cour d'appel de Douai, dans le ressort de laquelle se trouve Lille. La société devra constituer avocat et viser, dans sa déclaration, le chef du dispositif la condamnant à 38 000 euros et celui relatif aux rappels de salaires.","Conclusion. La société peut faire appel jusqu'au 20 novembre 2026, par déclaration d'appel remise par voie électronique par son avocat (art. 930-1 CPC), en visant les chefs critiqués."]},{"q":"L'appel suspend il l'exécution du jugement ?","corr":["Problème. Il faut déterminer si le jugement prud'homal est exécutoire malgré l'appel, et dans quelle mesure.","Règle. À la différence du droit commun, où les décisions de première instance sont de droit exécutoires à titre provisoire (art. 514 CPC), les jugements du conseil de prud'hommes ne le sont pas, sauf exceptions (art. R. 1454-28 C. trav.). Sont de droit exécutoires à titre provisoire le jugement qui n'est susceptible d'appel que par suite d'une demande reconventionnelle, celui qui ordonne la remise de documents que l'employeur est tenu de délivrer, et celui qui ordonne le paiement de sommes au titre des rémunérations et indemnités mentionnées à l'article R. 1454-14, dans la limite maximale de neuf mois de salaire calculés sur la moyenne des trois derniers mois, cette moyenne étant mentionnée dans le jugement. Le conseil peut, pour le surplus, ordonner l'exécution provisoire. En appel, la radiation de l'affaire peut être demandée lorsque l'appelant ne justifie pas avoir exécuté la décision assortie de l'exécution provisoire (art. 524 CPC).","Application. Les rappels de salaires de 9 000 euros relèvent des sommes de l'article R. 1454-14 : ils sont exécutoires de droit, dans la limite de neuf mois de salaire. Les dommages et intérêts pour licenciement sans cause réelle et sérieuse ne figurent pas parmi ces sommes : sauf décision expresse du conseil, ils ne sont pas exécutoires par provision et l'appel suspend leur exécution.","Conclusion. L'appel ne suspend pas l'exécution des 9 000 euros de rappel de salaires, que la société doit payer sous peine de radiation de son appel à la demande de Mme Vasseur. Il suspend en revanche l'exécution de la condamnation à 38 000 euros, sauf si le jugement a expressément ordonné l'exécution provisoire sur ce point."]}]}],"entretien":{"cats":{"parcours":"Parcours et motivation","metier":"Le métier de greffier","institution":"L'institution judiciaire","deonto":"Déontologie et fonction publique","culture":"Culture juridique et actualité","situation":"Mise en situation"},"questions":[{"cat":"parcours","q":"Pourquoi souhaitez vous devenir greffier ?","p":["Relier un élément concret de votre parcours (stage, audience à laquelle vous avez assisté, expérience d'accueil du public) au métier.","Montrer que vous connaissez la réalité des fonctions : assistance du magistrat, authentification des actes, accueil des justiciables.","Mettre en avant le sens du service public, la rigueur et le goût du travail en équipe, qualités recherchées par le jury."],"r":"Rapport du jury, Aix-en-Provence, 2024"},{"cat":"parcours","q":"Avez vous assisté à une audience ? Qu'en avez vous retenu ?","p":["Le jury relève que l'absence de visite d'audience publique est une faiblesse fréquente : assistez à plusieurs audiences avant l'oral.","Décrivez précisément le rôle du greffier observé : appel des affaires, note d'audience, tenue des dossiers, mention des décisions.","Tirez en une réflexion sur le métier (rythme, relation avec le magistrat, contact avec le public)."],"r":"Rapport du jury, Aix-en-Provence, 2024"},{"cat":"parcours","q":"Quelle est la compétence de votre parcours qui vous sera la plus utile comme greffier ?","p":["Choisir une compétence illustrée par un exemple vérifiable de la fiche individuelle de renseignement.","Rattacher la compétence à une mission : rigueur procédurale, organisation, maîtrise de l'outil informatique, sens de l'accueil.","Rester précis et sincère ; le jury sanctionne un projet professionnel peu cohérent."],"r":"Guide de remplissage de la fiche individuelle de renseignement"},{"cat":"parcours","q":"Où vous voyez vous dans cinq ans ?","p":["Montrer un projet cohérent : maîtrise des fonctions de greffier, diversité des services (civil, pénal, mineurs, prud'hommes).","Évoquer l'évolution possible vers le corps des cadres greffiers (catégorie A), sans donner l'impression que le poste de greffier n'est qu'une étape.","Accepter la mobilité géographique, inhérente au métier."],"r":"Décret n° 2024-1089"},{"cat":"parcours","q":"Avec un diplôme de niveau bac + 5, pourquoi ne pas avoir tenté un concours de catégorie A ?","p":["Assumer le choix du métier pour lui même : la procédure, l'audience, le contact avec le justiciable.","Montrer que vous connaissez les perspectives d'évolution (examen ou sélection professionnelle vers les cadres greffiers).","Éviter tout discours de repli ou de déclassement."],"r":"Conseil méthodologique"},{"cat":"metier","q":"Quelles sont les missions du greffier ?","p":["Assister les magistrats à l'audience et dans les cas prévus par les textes ; dresser les actes de greffe, notes et procès verbaux (art. R. 123-13 COJ).","Authentifier les actes : le greffier signe le jugement avec le président (art. 456 CPC).","Accueillir et informer les justiciables, enregistrer les actes et recours, préparer les dossiers, notifier les décisions lorsque la loi le prévoit."],"r":"COJ, art. R. 123-13 ; CPC, art. 456"},{"cat":"metier","q":"Quelle différence faites vous entre un greffier, un cadre greffier et un directeur des services de greffe judiciaires ?","p":["Greffier : assistance du magistrat et authentification des actes.","Cadre greffier : corps de catégorie A créé au 1er janvier 2025 (décret n° 2024-1089), encadrement de premier niveau et expertise procédurale.","Directeur des services de greffe judiciaires : direction et gestion administrative et budgétaire des greffes."],"r":"Décret n° 2024-1089"},{"cat":"metier","q":"Qu'est ce que le service d'accueil unique du justiciable ?","p":["Service dont la compétence s'étend au delà de la juridiction où il est implanté : il informe les personnes sur les procédures qui les concernent et reçoit leurs actes (art. L. 123-3 COJ).","Implanté au siège de chaque tribunal judiciaire et de chaque chambre de proximité (art. R. 123-26 COJ).","Il reçoit notamment les actes civils lorsque la représentation n'est pas obligatoire, les requêtes prud'homales et certaines demandes pénales (art. R. 123-28 COJ)."],"r":"COJ, art. L. 123-3, R. 123-26 et R. 123-28"},{"cat":"metier","q":"Qui sont les attachés de justice et comment travaillerez vous avec eux ?","p":["Ils assistent les magistrats du siège et du parquet : aide à la décision, recherches, soutien administratif ; ils prêtent serment et sont tenus au secret (art. L. 123-4 COJ).","Ils forment, avec le greffier, l'équipe autour du magistrat voulue par la loi de programmation 2023-2027.","Insister sur la complémentarité : le greffier garde l'authentification des actes et la régularité de la procédure."],"r":"COJ, art. L. 123-4 ; loi n° 2023-1059"},{"cat":"metier","q":"Pourquoi la présence du greffier est elle indispensable à l'audience ?","p":["Il assiste le magistrat et dresse les notes et procès verbaux (art. R. 123-13 COJ).","Il garantit l'authenticité de la décision, qu'il signe avec le président (art. 456 CPC).","Il assure la traçabilité de la procédure : mentions au dossier, notes d'audience, notification."],"r":"COJ, art. R. 123-13 ; CPC, art. 456"},{"cat":"metier","q":"Quel rôle joue le greffier au conseil de prud'hommes ?","p":["Enregistrement de la requête, avis au demandeur et convocation du défendeur (art. R. 1452-3 et R. 1452-4 C. trav.).","Consignation au procès verbal des prétentions non conciliées (art. R. 1454-10 C. trav.).","Notification des décisions par lettre recommandée avec avis de réception (art. R. 1454-26 C. trav.)."],"r":"Code du travail"},{"cat":"institution","q":"Comment est organisé un tribunal judiciaire ?","p":["Deux chefs de juridiction : le président du tribunal (siège) et le procureur de la République (parquet).","Un greffe dirigé par un directeur de greffe ; des services civils, pénaux, de la famille, des mineurs, de l'application des peines.","Le juge des contentieux de la protection, issu de la réforme du 1er janvier 2020 (loi n° 2019-222)."],"r":"Loi n° 2019-222"},{"cat":"institution","q":"Citez les directions du ministère de la Justice. De laquelle relèverez vous ?","p":["Secrétariat général ; DSJ, DACS, DACG, DGAP, DPJJ, DNUM ; inspection générale de la justice (organigramme de mars 2026).","Le greffier relève de la direction des services judiciaires, qui gère les juridictions judiciaires et leurs personnels.","Le jury relève que de trop nombreux candidats ne savent pas répondre sur les directions du ministère."],"r":"Organigramme du ministère, mars 2026 ; rapport du jury 2024"},{"cat":"institution","q":"Quelle différence entre le siège et le parquet ?","p":["Les magistrats du siège jugent ; ils sont inamovibles (art. 64 de la Constitution).","Les magistrats du parquet requièrent l'application de la loi au nom de la société ; ils sont placés sous l'autorité du garde des Sceaux, qui ne peut leur adresser d'instructions dans des affaires individuelles (art. 30 CPP).","Le greffe travaille avec les deux : greffe du siège et secrétariat du parquet."],"r":"Constitution, art. 64 ; CPP, art. 30"},{"cat":"institution","q":"Qui sont les partenaires de la juridiction ?","p":["Les auxiliaires de justice : avocats, commissaires de justice, experts, interprètes.","Les services d'enquête, l'administration pénitentiaire, la protection judiciaire de la jeunesse.","Les acteurs de l'accès au droit (points justice, maisons de justice et du droit) et les associations d'aide aux victimes."],"r":"Rapport du jury 2024 (partenaires de la juridiction)"},{"cat":"institution","q":"Quelle est la différence entre l'ordre judiciaire et l'ordre administratif ?","p":["L'ordre judiciaire juge les litiges entre personnes privées et les infractions ; au sommet, la Cour de cassation.","L'ordre administratif juge les litiges avec l'administration ; au sommet, le Conseil d'État.","Le Tribunal des conflits tranche les conflits de compétence entre les deux ordres (arrêt Blanco, 8 février 1873)."],"r":"Culture juridique générale"},{"cat":"deonto","q":"Quelles sont vos obligations en tant qu'agent public ?","p":["Dignité, impartialité, intégrité et probité (art. L. 121-1 CGFP).","Neutralité et respect du principe de laïcité ; égalité de traitement (art. L. 121-2 CGFP).","Secret professionnel (art. L. 121-6) et discrétion professionnelle (art. L. 121-7) ; obéissance hiérarchique, sauf ordre manifestement illégal et de nature à compromettre gravement un intérêt public (art. L. 121-10)."],"r":"Code général de la fonction publique, art. L. 121-1 et s."},{"cat":"deonto","q":"Quelle différence entre secret professionnel et discrétion professionnelle ?","p":["Le secret professionnel est pénalement sanctionné (art. L. 121-6 CGFP, renvoyant aux art. 226-13 et 226-14 du code pénal) : il protège les informations confiées par les usagers.","La discrétion professionnelle couvre tous les faits, informations ou documents connus dans l'exercice des fonctions ; seule l'autorité hiérarchique peut en délier (art. L. 121-7 CGFP).","Au greffe, les deux s'appliquent : dossiers, audiences à huis clos, informations sur les parties."],"r":"CGFP, art. L. 121-6 et L. 121-7"},{"cat":"deonto","q":"Pouvez vous afficher vos convictions religieuses ou politiques au travail ?","p":["Non : l'agent public est tenu à la neutralité et s'abstient de manifester ses opinions religieuses dans l'exercice de ses fonctions (art. L. 121-2 CGFP).","Il traite de façon égale toutes les personnes et respecte leur liberté de conscience.","Cette exigence est renforcée à l'audience, où l'impartialité de la justice doit être aussi apparente."],"r":"CGFP, art. L. 121-2"},{"cat":"deonto","q":"Quelles précautions prenez vous en matière de sécurité informatique ?","p":["Le jury relève la sécurité informatique comme un point faible des candidats.","Bonnes pratiques : verrouiller son poste à chaque absence, ne jamais communiquer ses identifiants, se méfier des courriels et pièces jointes suspects, ne pas utiliser de supports personnels, signaler sans délai tout incident.","Rattacher ces précautions au secret et à la discrétion professionnels, qui couvrent les données des dossiers."],"r":"Rapport du jury 2024 ; CGFP, art. L. 121-6 et L. 121-7"},{"cat":"culture","q":"Que symbolise le chêne de Saint Louis ?","p":["L'image, rapportée par Joinville, du roi Louis IX rendant la justice sous un chêne de Vincennes : une justice accessible et directe.","Nuance historique : le roi jugeait rarement lui même et confiait la justice à des légistes.","Le symbole se retrouve dans les terrasses arborées du tribunal de Paris."],"r":"Voir le chapitre « Symboles, budget et actualité de la justice »"},{"cat":"culture","q":"Le ministère avait promis de recruter des greffiers : où en est on ?","p":["La loi de programmation 2023-2027 prévoit 1 500 magistrats et 1 800 greffiers supplémentaires.","Au 1er décembre 2025, 571 greffiers étaient arrivés en juridiction et 833 en formation (ministère).","Le Sénat relève des retards ; le projet de budget 2027 prévoit 334 emplois de greffiers. Répondre de façon mesurée et factuelle."],"r":"Loi n° 2023-1059 ; ministère, 12 janv. 2026 ; Sénat ; PLF 2027"},{"cat":"culture","q":"Quand la peine de mort a t elle été abolie ?","p":["Loi du 9 octobre 1981, défendue par le garde des Sceaux Robert Badinter (discours du 17 septembre 1981).","Inscription à l'article 66-1 de la Constitution par la loi constitutionnelle du 23 février 2007.","Robert Badinter est entré au Panthéon le 9 octobre 2025."],"r":"Constitution, art. 66-1"},{"cat":"culture","q":"Qui fut la première femme magistrate ?","p":["Charlotte Béquignon-Lagarde, installée à la Cour de cassation en 1946, après la loi du 11 avril 1946.","En 2026, les femmes représentent 72 % des magistrats.","Simone Rozès fut la première femme première présidente de la Cour de cassation (1984)."],"r":"Ministère de la Justice"},{"cat":"culture","q":"Citez une réforme récente de la justice.","p":["Loi n° 2026-651 du 23 juillet 2026 sur la justice criminelle et le respect des victimes (loi « SURE »).","Décret n° 2026-683 du 27 juillet 2026 : saisine allégée du conseil de prud'hommes au 1er octobre 2026.","Création du corps des cadres greffiers (2025) ; direction générale de l'administration pénitentiaire (1er février 2026)."],"r":"Voir les chapitres de culture juridique"},{"cat":"culture","q":"Qui est le garde des Sceaux et que signifie ce titre ?","p":["Gérald Darmanin, ministre de la Justice.","Le titre renvoie à la garde des sceaux de la République, apposés notamment sur les lois constitutionnelles.","Le ministère siège place Vendôme, d'où le nom de « Chancellerie »."],"r":"Ministère de la Justice"},{"cat":"situation","q":"À l'accueil, un justiciable vous demande s'il va gagner son procès et ce qu'il doit répondre à son adversaire.","p":["Rester courtois et à l'écoute, mais ne jamais donner de consultation juridique ni préjuger de la décision : c'est une exigence d'impartialité (art. L. 121-1 CGFP).","Informer sur la procédure, les délais et les formalités, mission du service d'accueil unique (art. L. 123-3 COJ).","Orienter vers un avocat, un point justice ou l'aide juridictionnelle."],"r":"CGFP, art. L. 121-1 ; COJ, art. L. 123-3"},{"cat":"situation","q":"Un justiciable s'énerve au guichet et devient menaçant.","p":["Garder son calme, ne pas répondre à l'agressivité, reformuler sa demande pour désamorcer.","Si la situation dégénère, alerter sa hiérarchie et le service de sécurité de la juridiction ; ne pas rester seul.","Rendre compte par écrit de l'incident ; l'agent bénéficie de la protection fonctionnelle s'il est victime de menaces (art. L. 134-1 CGFP)."],"r":"CGFP, art. L. 134-1"},{"cat":"situation","q":"Un ami vous demande où en est la procédure de divorce d'un voisin, dont vous traitez le dossier.","p":["Refuser poliment : le secret et la discrétion professionnels s'imposent (art. L. 121-6 et L. 121-7 CGFP).","Ne consulter les dossiers que pour les besoins du service.","Si la demande insiste ou laisse craindre un conflit d'intérêts, en informer sa hiérarchie."],"r":"CGFP, art. L. 121-6 et L. 121-7"},{"cat":"situation","q":"Un journaliste vous appelle pour connaître la date du jugement d'une affaire médiatique.","p":["Ne donner aucune information personnellement, même si elle paraît publique : discrétion professionnelle (art. L. 121-7 CGFP).","Orienter vers l'interlocuteur habilité de la juridiction (chef de juridiction ou parquet, selon l'organisation locale) et en informer sa hiérarchie.","Rester courtois et ne pas commenter l'affaire."],"r":"CGFP, art. L. 121-7"},{"cat":"situation","q":"En classant un dossier, vous découvrez des éléments laissant penser qu'un délit a été commis.","p":["Tout fonctionnaire qui, dans l'exercice de ses fonctions, acquiert la connaissance d'un crime ou d'un délit est tenu d'en donner avis sans délai au procureur de la République (art. 40, al. 2, CPP ; art. L. 121-11 CGFP).","En pratique, en référer immédiatement à sa hiérarchie, qui saisira le parquet.","Ne pas enquêter soi même et préserver les pièces."],"r":"CPP, art. 40 ; CGFP, art. L. 121-11"},{"cat":"situation","q":"Votre supérieur vous demande d'antidater un procès verbal pour éviter une nullité.","p":["Refuser : l'agent doit se conformer aux instructions, sauf si l'ordre est manifestement illégal et de nature à compromettre gravement un intérêt public (art. L. 121-10 CGFP) ; antidater un acte authentique peut constituer un faux.","Exposer calmement le problème, proposer une solution régulière.","Si l'instruction est maintenue, en référer au directeur de greffe."],"r":"CGFP, art. L. 121-10"},{"cat":"situation","q":"Vous constatez qu'une convocation est partie avec une mauvaise date d'audience.","p":["Signaler immédiatement l'erreur au magistrat et à sa hiérarchie : l'agent est responsable des tâches qui lui sont confiées (art. L. 121-9 CGFP).","Proposer une correction : nouvelle convocation dans les formes, information des parties, éventuel renvoi.","Montrer sa capacité à prendre une initiative adaptée à son statut, point relevé par le jury."],"r":"CGFP, art. L. 121-9 ; rapport du jury 2024"},{"cat":"situation","q":"Vous recevez un courriel d'un expéditeur inconnu vous demandant de cliquer sur un lien pour « mettre à jour vos identifiants ».","p":["Ne pas cliquer, ne pas répondre, ne communiquer aucun identifiant.","Signaler le courriel au service informatique selon la procédure de la juridiction.","Rappeler l'enjeu : la protection des données des justiciables et la continuité du service."],"r":"Rapport du jury 2024 (sécurité informatique)"},{"cat":"situation","q":"Deux magistrats vous demandent en même temps un travail urgent.","p":["Ne pas arbitrer seul : informer les deux magistrats et, si nécessaire, le directeur de greffe ou le chef de service.","Hiérarchiser selon les délais légaux et les audiences à venir.","Montrer le sens de l'organisation et du travail en équipe, attendus par le jury."],"r":"Rapport du jury 2024"},{"cat":"situation","q":"Une partie se présente à l'audience sans avocat et ne comprend pas ce qui se passe.","p":["Rester dans son rôle : le greffier n'assiste pas la partie et ne plaide pas pour elle.","Lui indiquer, avec bienveillance et neutralité, où et quand elle sera appelée, et l'informer de la possibilité de solliciter l'aide juridictionnelle ou un avocat.","Signaler au magistrat toute difficulté de compréhension (barrière de la langue, vulnérabilité)."],"r":"CGFP, art. L. 121-1 et L. 121-2"}]}};